export const PART: Chapter[] = [{"n":23,"title":"学什么技能划算","intro":"口径是金钱回报与时间成本，第 2 条另算死亡率。前六条回答「还要不要接着读」——法律先划掉一段选项，然后是寿命账、学历在人群里的稀缺度、读不起时的资助、没上普高的通道，最后给一个自己算的方法；后七条回答「决定学点东西之后怎么挑」。中国分职业的工资统计难以从公开官方渠道逐项核实，所以只写能查到出处的：教育回报率的证据、证书的合法性怎么验、培训补贴从哪来、以及挑技能时哪个维度更抗替代。具体某个工种一个月挣多少，本书不给数字。","entries":[{"id":"23.1","sec":23,"n":1,"title":"不满 16 周岁没有「去打工」这个选项：招你的单位每月被罚 5000 元，肯招的都是黑工","cost":"0 元；先算一下自己的年龄","human":"初中毕业通常 15 到 16 岁，正好卡在这条线上。义务教育法写明父母应当送子女入学接受并完成义务教育，也禁止用人单位招用还该上学的孩子；《禁止使用童工规定》再加一层：机关、社团、企事业单位、民办非企业单位和个体工商户都不得招用不满 16 周岁的人，每用一名童工每月罚 5000 元，逾期不改按每人每月 1 万元，介绍一个人去当童工也罚 5000 元。所以不满 16 岁能找到的活，只会来自明知违法还敢用你的单位——出了事按《禁止使用童工规定》的一次性赔偿走，不适用工伤保险待遇。","gain":"《义务教育法》第十一条「凡年满六周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育」；第十四条「禁止用人单位招用应当接受义务教育的适龄儿童、少年」；第五十八条，无正当理由未依照本法规定送适龄儿童少年入学的，由当地乡镇人民政府或者县级人民政府教育行政部门「给予批评教育，责令限期改正」。《禁止使用童工规定》第二条：国家机关、社会团体、企业事业单位、民办非企业单位或者个体工商户「均不得招用不满16周岁的未成年人」；第六条「按照每使用一名童工每月处5000元罚款的标准给予处罚」，逾期未改正的按每人每月 1 万元罚；第七条介绍童工就业的「按照每介绍一人处5000元罚款」；第十条童工患病或者受伤的，用人单位「应当负责送到医疗机构治疗，并负担治疗期间的全部医疗和生活费用」，伤残或死亡的还要一次性赔偿。第十三条只留了一个例外：文艺、体育单位经父母或者其他监护人同意，可以招用不满 16 周岁的专业文艺工作者、运动员（全国）","grade":"A","src":"全国人大常委会 (2018). 义务教育法（2018 年第二次修正，第十一、十四、五十八条）. <http://www.moe.gov.cn/jyb_sjzl/sjzl_zcfg/zcfg_jyfl/202110/t20211029_575949.html>（教育部刊登）；国务院 (2002). 禁止使用童工规定（国务院令第 364 号，第二、六、七、十、十三条）. <http://www.gov.cn/gongbao/content/2002/content_61798.htm>","note":"受益人是自己。满 16 岁之后打工是合法的，但「肯要 16 岁、没学历的人」的岗位，恰好就是本节第 10 条（挑抗自动化的技能）讲的那一类：流程固定、可替代性最高。第 19 节的加班费、年休假、工伤待遇都以有劳动关系和有证据为前提，黑工这些一样都没有","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"23.2","sec":23,"n":2,"title":"把「读书有没有用」也放进死亡率账里：每多受一年教育，成人死亡风险降约 1.9%","cost":"多读的那几年时间和精力，学费部分见本节第 4 条","human":"59 个国家、603 项研究、一万多个观测点汇总出来的结果是：教育年限和死亡率是剂量关系，每多读一年书，成年后的死亡风险平均低约 1.9%；18 到 49 岁这一段最明显，每多一年低约 2.9%，70 岁以上降到 0.8%。男女之间、穷国富国之间没看出差别。也就是说，读到高中和只读到初中，差的不只是工资。","gain":"系统综述与荟萃分析，检索 1980 年 1 月至 2023 年 5 月，最终纳入 603 项研究、59 个国家 70 个地点、10355 个观测：教育与全因成人死亡率呈剂量反应关系，每多受一年教育，死亡风险平均下降 1.9%（95% 不确定区间 1.8–2.0）；18 至 49 岁人群每多一年下降 2.9%（2.8–3.0），70 岁以上人群下降 0.8%（0.6–1.0）；未发现按性别或社会人口指数分层的效应差异","grade":"A","src":"IHME-CHAIN Collaborators (2024). Effects of education on adult mortality: a global systematic review and meta-analysis. The Lancet Public Health, 9(3), e155-e165. <https://doi.org/10.1016/S2468-2667(23)00306-7>","note":"争议。作者自己报告了发表偏倚（p<0.0001）和研究间的高异质性；纳入的都是观察性研究，教育年限和家庭条件、地区、职业高度纠缠，这个 1.9% 里有多少是教育本身带来的、有多少是「能一直读下去的人本来条件就好」，无法用这类研究分开。所以它是「多读书和活得久同向」的强证据，不是「让你去读书就能延寿 1.9%」的因果保证。受益人是自己","money":"0","time":"多","will":"是","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"23.3","sec":23,"n":3,"title":"判断「学历是不是贬值了」之前，先看全国的学历结构：每 10 万人里只有 15467 人有大学文化程度","cost":"0 元；看一眼数字","human":"2020 年第七次人口普查的结果是，全国每 10 万人里大专及以上只有 15467 人（约 15%），高中含中专 15088 人，初中 34507 人，小学 24767 人；15 岁以上人口的平均受教育年限是 9.91 年，也就是刚过初中毕业。初中学历在中国不是「够用」，是人数最多的那一档。「985 送外卖」「初中毕业当老板」之所以被反复讲，正因为它们反常；讲得多不等于发生得多。","gain":"第七次全国人口普查（标准时点 2020 年 11 月 1 日）：全国人口中，拥有大学（大专及以上）文化程度的 218360767 人，高中（含中专）213005258 人，初中 487163489 人，小学 349658828 人。与 2010 年第六次人口普查相比，每 10 万人中拥有大学文化程度的由 8930 人上升为 15467 人，高中由 14032 人上升为 15088 人，初中由 38788 人下降为 34507 人，小学由 26779 人下降为 24767 人；15 岁及以上人口的平均受教育年限由 9.08 年提高至 9.91 年，文盲率由 4.08% 下降为 2.67%","grade":"A","src":"国家统计局、国务院第七次全国人口普查领导小组办公室 (2021). 第七次全国人口普查公报（第六号）——人口受教育情况. <https://www.stats.gov.cn/sj/tjgb/rkpcgb/qgrkpcgb/202302/t20230206_1902006.html>","note":"这条只回答「学历在人群里稀不稀缺」，不回答「某个具体的人读书划不划算」——后者要按本节第 6 条的方法自己算。要注意的是：普查统计的是全国人口的存量，年轻人的比例远高于这个平均值，所以拿它去比同龄人会高估自己的优势；反过来，用它去否定「读书没用」是成立的，因为分母就是你要跟之竞争的整个劳动力。受益人是自己","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"23.4","sec":23,"n":4,"title":"「读不起」先按政策算一遍：中职学费大多已免，助学金 2300 元，助学贷款每年最高 2 万","cost":"0 元；开学前在学校学生资助管理机构问一次，交一次材料","human":"义务教育本来就免学杂费；中职这边，公办学校里农村（含县镇）学生、城市涉农专业学生和家庭经济困难学生的学费已经免掉；中职和普通高中的国家助学金 2025 年春季学期起从每年 2000 元提到 2300 元；上了大学，本专科国家助学金从 3300 元提到 3700 元、国家励志奖学金从 5000 元提到 6000 元，国家助学贷款本专科每年最高从 1.6 万提到 2 万、研究生从 2 万提到 2.5 万，利率是同期同档次 LPR 减 70 个基点。钱不够可以是推迟、可以是换路径，但按这些数字算下来，很少构成「必须现在退学去打工」。","gain":"2012 年秋季学期起，「对公办中等职业学校全日制正式学籍一、二、三年级在校生中所有农村（含县镇）学生、城市涉农专业学生和家庭经济困难学生免除学费（艺术类相关表演专业学生除外）」。2024 年调整学生资助政策：本专科生国家助学金由每生每年 3300 元提高到 3700 元、国家励志奖学金由 5000 元提高到 6000 元，自 2024 年秋季学期（励志奖学金自 2024 年）起执行；中等职业学校国家助学金、普通高中国家助学金均由每生每年 2000 元提高到 2300 元，自 2025 年春季学期起执行。国家助学贷款自 2024 年秋季学期起，本专科学生「每人每年申请贷款额度由不超过16000元提高至不超过20000元」，研究生「由不超过20000元提高至不超过25000元」，利率为同期同档次 LPR 减 70 个基点（全国）","grade":"A","src":"财政部、发展改革委、教育部、人力资源社会保障部 (2012). 关于扩大中等职业教育免学费政策范围 进一步完善国家助学金制度的意见（财教〔2012〕376 号）. <http://www.gov.cn/gongbao/content/2013/content_2332779.htm>；财政部、教育部、人力资源社会保障部有关司局负责人 (2024). 就调整学生资助政策有关问题答记者问. <https://www.gov.cn/zhengce/202410/content_6983672.htm>；财政部、教育部、人民银行、金融监管总局 (2024). 关于调整完善国家助学贷款有关政策的通知（财教〔2024〕188 号）. <https://www.gov.cn/zhengce/zhengceku/202411/content_6984812.htm>","note":"受益人是自己和子女。免学费的具体覆盖面和助学金的分档比例由各省定，民办学校按当地公办同类专业标准补助、差额部分仍要自付，所以入学前要按本地文件核一遍。助学贷款是贷款不是补助，毕业后要还，但它把「现在拿不出学费」和「这几年划不划算」拆成了两件事——先别把资金问题当成结论。第 7 节写过失业期间的培训补贴和临时救助，家庭确实断了收入时先走那条线","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"23.5","sec":23,"n":5,"title":"没考上普高不等于路断了：中职有贯通招生和单独考试，技能岗位招聘还可以降学历要求","cost":"0 元；在中考志愿之前查一次本省的职教招生平台","human":"2022 年修订的职业教育法把职业教育写成「与普通教育具有同等重要地位的教育类型」，并且给了明文的升学通道：中职可以在有关专业与高职贯通招生培养，高职可以用文化素质加职业技能的方式招生，高职和办职业教育的普通高校还必须在招生计划里留出比例或者单独考试专门招中职毕业生。就业这头也有明文：用人单位不得设置妨碍职业学校毕业生平等就业的报考、录用、聘用条件，事业单位公开招聘中有职业技能等级要求的岗位可以适当降低学历要求。分数不够上普高，是换一条路，不是停在初中学历。","gain":"《职业教育法》（2022 年 5 月 1 日起施行）第三条：「职业教育是与普通教育具有同等重要地位的教育类型」。第三十七条：中等职业学校「可以按照国家有关规定，在有关专业实行与高等职业学校教育的贯通招生和培养」；高等职业学校「可以按照国家有关规定，采取文化素质与职业技能相结合的考核方式招收学生」；省级以上教育行政部门要建立职业教育统一招生平台，汇总发布学校、专业设置和招生情况并提供查询报考服务。第五十三条：「职业学校学生在升学、就业、职业发展等方面与同层次普通学校学生享有平等机会」；高等职业学校和实施职业教育的普通高等学校「应当在招生计划中确定相应比例或者采取单独考试办法，专门招收职业学校毕业生」；「用人单位不得设置妨碍职业学校毕业生平等就业、公平竞争的报考、录用、聘用条件」，事业单位公开招聘中有职业技能等级要求的岗位「可以适当降低学历要求」（全国）","grade":"A","src":"全国人大常委会 (2022). 职业教育法（2022 年修订，第三、三十七、五十三条）. <http://www.moe.gov.cn/jyb_sjzl/sjzl_zcfg/zcfg_jyfl/202204/t20220421_620064.html>（教育部刊登）","note":"受益人是自己和子女。这些是法定的通道，不是保证录取：贯通培养的专业范围、单独招生的比例、职教高考的科目都由各省定，报志愿前必须查本省当年的职教招生平台和招生计划，别按外省经验推。挑中职专业时用本节第 10 条（挑抗自动化的技能）的维度过一遍——要到现场、环境不标准的专业更抗替代。选学校前先按第 8 条（查证书在不在目录里）的三步验一遍办学资质，招生宣传里承诺「包分配」「保过」的一律不要","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"23.6","sec":23,"n":6,"title":"把「读书还是打工」算成一道题：早挣的三年工资，对上往后几十年的年收入差","cost":"0 元；坐下来算一次，半小时","human":"把两条路摊在纸上。早工作这条：收益是三年低门槛岗位的工资，成本是往后每年少掉的那一截。继续读这条：成本是学费加生活费，减掉本节第 4 条那些免学费、助学金和助学贷款，再加上没去挣的那几年工资；收益是每多一年教育带来的收入差，乘以剩下的三四十年工作期，另外还有本节第 2 条那笔死亡率账。关键在于早挣的那笔是一次性的，年收入差是要乘以工作年数的。中国城镇的估计从 1988 年每年 4.0% 涨到 2001 年 10.2%，数据老，只能当量级用。","gain":"对中国城镇 1988 至 2001 年的估计：教育回报率「从 1988 年每受教育一年 4.0% 大幅上升到 2001 年的 10.2%」，涨幅主要发生在 1992 年之后，反映的是高等教育工资溢价的上升。这是把「多读一年」折成年收入差时可用的中国本土量级，全球平均值见本节第 7 条","grade":"B","src":"Zhang J, Zhao Y, Park A, Song X (2005). Economic returns to schooling in urban China, 1988 to 2001. Journal of Comparative Economics, 33(4), 730-752. <https://doi.org/10.1016/j.jce.2005.05.008>","note":"数据截至 2001 年、只覆盖城镇，不能直接当今天的数用；本节第 7 条那个全球平均 9% 同理。这条给的是算法不是答案：真按这个算，结论会因人而异——学费高、专业和岗位对不上、读的年限又长的，算出来可能真不划算，这不构成「读书无用」，只构成「这个具体项目不划算」。别把两者混为一谈。另外，收入差之外还有几项进不了公式但确实存在的：法定的学历门槛（本节第 5 条）、抗替代能力（第 10 条，挑抗自动化的技能）、以及能不能换行业。受益人是自己","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"23.7","sec":23,"n":7,"title":"先记住基准线：多受一年教育，全球平均的私人回报约为每年 9%","cost":"0 元；把它当作比较各种「学点东西」方案的基准","human":"覆盖 139 个国家、1120 项估计的综述算出来，多读一年书，个人收入平均每年高约 9%，女性的回报还持续高于男性。这是「多读一年正规教育」的平均值，不是「报一个班」的收益。拿它当尺子：一个课程要你花 3 万元和半年，就问它带来的收入变化抵不抵一年正规教育。","gain":"覆盖 1950 至 2014 年、139 个国家、1120 项估计的综述：「多受一年教育的全球平均私人回报率是每年 9%」；高等教育的私人回报在上升，教育的社会回报仍然很高；女性受教育的平均回报持续高于男性","grade":"A","src":"Psacharopoulos G, Patrinos HA (2018). Returns to investment in education: a decennial review of the global literature. Education Economics, 26(5), 445-458. <https://doi.org/10.1080/09645292.2018.1484426>；世界银行政策研究工作论文 8402. <https://doi.org/10.1596/1813-9450-8402>","note":"这是「多读一年书」的平均值，不是「报一个班」的收益，也不是中国的具体数字，只能当量级参照。它的用处是给所有培训方案一把尺子：一个课程要你花 3 万元和半年时间，就该问它能不能带来相当于一年正规教育的收入变化。全球平均掩盖了巨大的专业差异和国别差异","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"23.8","sec":23,"n":8,"title":"花钱考证之前，先查这张证在不在国家职业资格目录或人社部备案的评价机构名单里","cost":"0 元；查一次，十几分钟","human":"人社部专门治理过这类乱象——有机构打着新职业、技能等级的名义乱办班、乱收费、滥发证，甚至假冒权威机构，查处时联合网信、公安、市场监管关停违规宣传。报名前按三步查：这个职业在不在国家职业资格目录、发证机构是不是人社部门备案的评价机构、证书编号能不能在官方平台查到。查不到的，报名费就是白花。","gain":"人社部专门为此开展过全国性治理：「一些机构和单位以新职业职业资格、职业技能等级等名义随意举办培训、评价、发证活动，乱收费、滥发证；一些机构和单位虚假或夸大宣传，甚至假冒权威机构名义组织培训、评价、颁发证书等」。治理措施包括联合网信、公安、市场监管等部门查处，「严厉打击假冒鉴定机构、人社部门备案评价机构的评价发证活动」，对网站和新媒体上不合规的宣传依法关停。同时要求「引导公众了解证书查询渠道和方式，判断证书合法合规性和含金量」","grade":"A","src":"人力资源社会保障部 (2022). 关于开展技术技能类「山寨证书」专项治理工作的通知. <https://www.gov.cn/zhengce/zhengceku/2022-03/18/content_5679641.htm>","note":"验证顺序：先看这个职业在不在《国家职业资格目录》里，不在目录里的就不是国家职业资格；再看发证机构是不是人社部门备案的评价机构；最后到官方技能人才评价证书查询平台查证书编号能不能查到。查不到的一律不报。带「国际」「高级」「注册」字样、承诺「包过」「挂靠有收入」的，风险最高","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"23.9","sec":23,"n":9,"title":"培训优先走政府补贴渠道，别一上来就自费报商业班","cost":"0 元或大幅减免；培训本身要占时间","human":"2025 年到 2027 年底，国家计划办 3000 万人次以上的补贴培训，钱从就业补助资金、失业保险基金、企业职工教育经费等多个口子出，按工种缺人程度和培训成本定补贴高低；企业还被要求把职工教育经费的六成以上用在一线职工身上。在职的先问单位，其余人先翻当地人社局的补贴目录再决定学什么，比先选好再找补贴省钱。","gain":"国家层面的规模是明确的：2025 年到 2027 年底，「聚焦高精尖产业与急需行业、就业重点群体等开展补贴性培训 3000 万人次以上」。资金来源被打通为一揽子：就业补助资金、失业保险基金、行业发展资金、东西部协作资金、企业职工教育经费等；补贴按职业（工种）的急需紧缺程度和培训成本差异化确定。企业侧还要求「按规定足额提取和使用职工教育经费，确保 60% 以上用于一线职工教育和培训」","grade":"A","src":"国务院就业促进和劳动保护工作领导小组 (2025). 关于开展大规模职业技能提升培训行动的指导意见. <https://www.gov.cn/zhengce/zhengceku/202507/content_7032222.htm>","note":"领取路径和金额由各省定，入口是当地人社局官网的「职业培训补贴目录」和公共实训基地。第 7 节写过失业期间的职业培训补贴（同一人最多享受 3 次）和社保补贴，在职的人则先问单位的职工教育经费。先查补贴目录再选学什么，比先选好再找补贴省钱得多","money":"0","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"23.10","sec":23,"n":10,"title":"挑技能时优先看「要不要动手、要不要现场判断」，这类最难被自动化顶掉","cost":"0 元；选之前先按这个维度过一遍","human":"对美国 702 个职业的评估里，约 47% 的岗位落在高风险区间，卡住机器的是三样东西：手上的灵巧劲、创造力、跟人打交道的能力。所以要到现场、环境不标准、得临场判断的活更难被顶掉，流程固定、主要在处理信息的岗位风险最高。这项研究是按整个职业打分的，后来按具体任务拆分的估计低得多，别盯着 47% 这个数，看那三个维度。","gain":"对美国 702 个职业的可计算化概率评估：约 47% 的就业岗位处于高风险区间。模型里决定风险高低的是三类「工程瓶颈」——感知与操作（手指灵巧度、手部灵巧度、狭窄空间与别扭姿势下作业）、创造性智能、社会智能。也就是说，环境非标准、需要手上功夫和临场判断的活，被替代的概率系统性地更低；而流程固定、以信息处理为主的岗位风险最高","grade":"B","src":"Frey CB, Osborne MA (2017). The future of employment: how susceptible are jobs to computerisation? Technological Forecasting and Social Change, 114, 254-280. <https://doi.org/10.1016/j.techfore.2016.08.019>","note":"争议。这项研究是 2013 年的工作论文，按「整个职业能否自动化」打分，后续研究（如按任务而非职业拆分的估计）得出的高风险比例低得多；它也不预测哪一年会发生。用它的正确方式不是看 47% 这个数，而是看它识别出的那三个瓶颈维度——这解释了为什么现场安装、检修、护理这类活比纯文书更抗替代，也解释了为什么「学个技能」优先该选需要到现场、面对非标准环境的那种","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":true,"todo":false,"ratio":"极高"},{"id":"23.11","sec":23,"n":11,"title":"学之前先确认这个技能有没有等级评价，等级能不能换成钱","cost":"0 元；查一次","human":"国家在推「新八级工」，要求企业把岗位薪酬和技能等级双挂钩、加大高级工以上的评聘，够条件的职工还能不看工龄资历直接认定等级。这是政策方向，不是已经兑现的工资数，各地各企业差别很大。可用的判断是：有国家职业标准和等级通道的技能，往后才谈得上按等级涨薪。","gain":"国家正在推「新八级工」职业技能等级制度，并明确要求把等级与薪酬挂钩：「强化技能导向的薪酬分配制度……指导企业实行岗位薪酬与岗位价值、技能等级双挂钩的分配办法」，各地要「加大高级工以上评聘力度和批次」；符合条件的企业可自主开展职工技能等级评价，对表现突出的职工「可打破工作年限、等级、资历等条件，直接认定相应职业技能等级」","grade":"B","src":"国务院就业促进和劳动保护工作领导小组 (2025). 关于开展大规模职业技能提升培训行动的指导意见. <https://www.gov.cn/zhengce/zhengceku/202507/content_7032222.htm>；人力资源社会保障部 (2021). 「技能中国行动」实施方案. <https://www.gov.cn/zhengce/zhengceku/2021-07/06/content_5622619.htm>","note":"这是政策方向而不是已兑现的工资数，落地程度各地各企业差别很大。可操作的部分：选技能时看它有没有对应的国家职业标准和等级通道，有通道的技能后面才谈得上按等级涨薪；没有等级、也没有行业准入门槛的「技能」，学完只能靠自己找活","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"23.12","sec":23,"n":12,"title":"别把「网上说工资高」当成缺人，去查当地的紧缺职业目录和补贴目录","cost":"0 元；查两份当地文件","human":"各地补贴给多少，本身就是官方对「哪个工种缺人」的定价——补贴额度按急需紧缺程度和培训成本定。同一个工种在不同城市补贴差多少，反映的就是当地缺人程度的差别。网上「某工种月入多少」多半来自招聘平台挂牌价或个人自述，既挑赢家看，也不含工时、通勤、职业病和淡旺季。","gain":"补贴额度本身就是官方对「哪些工种缺人」的定价：政策要求「健全根据职业（工种）急需紧缺程度、培训成本等情况确定的差异化补贴机制」，各地据此确定本地的补贴性职业技能培训项目范围。所以同一个工种在不同城市的补贴额度差异，直接反映了当地的紧缺程度","grade":"C","src":"国务院就业促进和劳动保护工作领导小组 (2025). 关于开展大规模职业技能提升培训行动的指导意见. <https://www.gov.cn/zhengce/zhengceku/202507/content_7032222.htm>","note":"TODO（待核实：全国分职业的平均工资与紧缺职业排行的官方数据源，人社部相关页面本次未能取得）。网上流传的「某工种月入多少」几乎都来自招聘平台的挂牌价或个人自述，既有幸存者偏差又不含工时、通勤、职业病和淡旺季。要看真实需求，去当地人社局官网查补贴目录和公共就业服务机构的岗位需求排行，再去实际的工地、工厂、门店问在职的人","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"23.13","sec":23,"n":13,"title":"同样的钱和时间，优先选能直接上岗的短周期项目","cost":"短期课程的学费和时间","human":"政策鼓励的是能短期实现就业的「短平快」培训和职业院校的微专业。挑项目只看一条：学完有没有一个具体岗位能投简历。学一年半载、结业还要「再积累经验」的，实际花掉的时间远超标价。开工前就写好退出条件：学到什么程度还没找到活就停。","gain":"政策口径与此一致：支持「民办培训机构开展市场化的高质量职业技能培训项目和能短期实现就业的『短平快』式职业技能培训项目」，并推动职业院校「聚焦就业市场急需知识和技能……开设微专业和职业能力培训课程」","grade":"C","src":"国务院就业促进和劳动保护工作领导小组 (2025). 关于开展大规模职业技能提升培训行动的指导意见. <https://www.gov.cn/zhengce/zhengceku/202507/content_7032222.htm>","note":"判断标准就一条：学完之后有没有一个具体的岗位能投简历。学一年半载、结业后还要「再积累经验」的项目，实际成本远高于标价。第 4 节的退出条件同样适用——开工前就写清楚「学到什么程度还没找到活就停」","money":"少","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]},{"n":24,"title":"看病：怎么少花钱少走弯路","intro":"口径：金钱与时间。这一节讲的是就医这件事本身怎么走——先去哪、怎么转、少花在哪，以及到了急诊怎么排队、重伤治完之后该做哪些鉴定和证件。能领什么待遇见第 7 节，慢性病长期怎么管见第 16 节，急症现场先做什么见第 13 节。\n本节主要依据国务院办公厅 2026 年 4 月印发的《关于加快建设分级诊疗体系的若干措施》。这份文件把「去基层」和「省钱」直接挂上了钩，但各地落地进度不同，正文写的是国家层面的规则，具体到你所在的统筹地区，要以当地医保和卫健部门的口径为准。","entries":[{"id":"24.1","sec":24,"n":1,"title":"常见病先在社区看，经基层逐级转诊上去，住院起付线接着算","cost":"0 元；代价是先去一趟社区，心理上要接受「不直接挂专家号」","human":"经基层逐级转诊住到上级医院，每次住院要自己先扛的那段起付线只算一次；自己直接跑去三级医院住院、之后再转回社区康复，可能要交两回。由上级医院转回基层继续住的，同一个病这段时间里也不再另设起付线。","gain":"经基层逐级转诊的参保患者，在上级医院的住院起付线可以连续计算；由上级医院下转回基层的住院患者，同一疾病周期内不再另设起付线","grade":"A","src":"国务院办公厅 (2026). 关于加快建设分级诊疗体系的若干措施. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065031.htm>：「统筹地区内经基层医疗卫生机构逐级转诊的参保患者，在上级医院的住院起付线可连续计算；由上级医院下转至基层医疗卫生机构的住院患者，同一疾病周期内不再另设住院起付线。」","note":"起付线是每次住院自付的那一段。自己直接跑去三级医院住院，再转回基层康复，可能要交两次；走转诊就只算一次。转诊规则由各省、市和医联体分别制定，去之前先问社区。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"24.2","sec":24,"n":2,"title":"同一个统筹地区里，级别越低报销比例越高，差距约 10 个百分点","cost":"0 元","human":"同一笔住院费，医院级别越低报得越多，各地按逐级差十个百分点左右的方向拉开，新增的医保基金也往基层倾斜。能在社区办完的事往大医院跑，同一笔费用自付要多掏约一成。","gain":"文件要求各地拉开不同等级医疗机构的住院报销水平，原则上逐级差 10 个百分点左右；年度新增医保基金也向基层倾斜","grade":"A","src":"国务院办公厅 (2026). 关于加快建设分级诊疗体系的若干措施. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065031.htm>：「因地制宜适当拉开参保人员在不同等级医疗卫生机构的住院报销水平，原则上统筹地区内医疗卫生机构住院报销比例逐级拉开10个百分点左右的差距。」「具备条件的地方，可按分级诊疗导向酌情拉开参保人员在不同等级医疗卫生机构的门诊报销水平。」","note":"同一笔住院费，在基层和在三级医院自付的差额可能是几千元。这条不是说什么病都在社区看，是说能在基层办完的别往上跑。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"24.3","sec":24,"n":3,"title":"要去大医院，走基层转诊或者医院的转诊中心，别找号贩子","cost":"0 元；多一道转诊手续","human":"大医院要留出一部分号源和床位给基层转来的人，还要设转诊中心或者固定部门专门管转诊，2027 年全覆盖。挂不到号不等于没有路；号贩子的号除了贵，还可能把你送进不对口的科室。","gain":"紧密型医联体的牵头医院要为基层预留一定比例的号源和床位，并及时接诊经基层转诊的患者；医疗机构要设转诊中心或指定固定部门，到 2027 年实现全覆盖","grade":"A","src":"国务院办公厅 (2026). 关于加快建设分级诊疗体系的若干措施. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065031.htm>：「牵头医院要为基层医疗卫生机构预留一定比例的号源和床位，并及时接诊经基层转诊患者。」「医疗机构要强化转诊服务统一管理，设立转诊中心或指定固定部门承担患者转诊服务工作，到2027年实现全覆盖。」","note":"预留号源就是给转诊患者的通道，抢不到号不等于没有路。号贩子那条路除了贵，还可能让你落到不对口的科室。找不到转诊中心就打医院的服务电话问。","money":"0","time":"中","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"24.4","sec":24,"n":4,"title":"跨省异地就医之前先在本地问一句，必要性原则上要副主任医师以上评估","cost":"0 元，多问一次","human":"要不要去外地看病，原则上由二、三级医院副主任医师以上的医生评估；临时外出就医的报销水平和参保地同级别医院会有差异，具体看本地规定。出发前在本地问一句，比人到了外地才发现报不了强。","gain":"跨统筹地区、跨省异地就医的必要性原则上由二、三级医院副主任医师及以上职称人员评估；跨省临时外出就医人员的报销水平与参保地同级别机构保持合理差异","grade":"A","src":"国务院办公厅 (2026). 关于加快建设分级诊疗体系的若干措施. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065031.htm>：「原则上由二、三级医院副主任医师及以上职称人员评估患者跨统筹地区、跨省异地就医的必要性。」「进一步强化异地就医直接结算管理服务，跨省临时外出就医人员报销水平与参保地同级别医疗机构报销水平保持合理差异。」","note":"「临时外出就医」和「长期异地居住」是两种备案，报销水平不一样。备案怎么办、哪几类病能直接结算见第 16 节。别先跑到外地再想报销的事。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"24.5","sec":24,"n":5,"title":"别再拿三级医院当开药点，稳定期的慢病回基层","cost":"0 元；要改掉「只信大医院」的习惯","human":"三级医院要往急危重症和疑难病上收，常见病复诊和病情稳定的慢病普通门诊会被逐步减掉，专家团队的普通门诊改往社区延伸。把大医院当开药点，以后会越来越挂不上号。","gain":"三级医院要聚焦急危重症和疑难复杂疾病，逐步酌减常见病复诊和诊断明确、病情稳定的慢性病等普通门诊；上级医院会把专家团队的普通门诊延伸到基层","grade":"A","src":"国务院办公厅 (2026). 关于加快建设分级诊疗体系的若干措施. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065031.htm>：「三级医院要聚焦急危重症和疑难复杂疾病，加强转诊会诊和住院服务，逐步酌减常见病复诊和诊断明确、病情稳定的慢性病等普通门诊。」「紧密型医联体内上级医院要在基层医疗卫生机构开设高血压、糖尿病、慢性阻塞性肺疾病等常见病、慢性病门诊，提供诊疗和健康管理服务，并将专家团队普通门诊向基层医疗卫生机构延伸。」","note":"这是政策方向，不是建议：以后大医院的普通门诊会越来越难挂。稳定期慢病在基层一次能开 12 周的药，见第 16 节。","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"24.6","sec":24,"n":6,"title":"每次看完病，把病历、检查报告和影像自己存一份","cost":"0 元；医院复印可以按规定收工本费，收费标准应当公开","human":"查阅和复制自己的病历是法律给的权利，范围包括门诊病历、住院志、化验单、影像、手术和麻醉记录、病理资料和费用清单；医院有专门窗口受理，只能收工本费且标准要公开。换医院、找第二诊疗意见、报商业保险、真起纠纷，凭的都是这一摞材料。","gain":"法规明确把查阅、复制病历列为患者的权利，且范围覆盖门诊病历、住院志、化验单、医学影像、手术及麻醉记录、病理资料、医疗费用等全部资料；换医院、找二次诊疗意见、报商业保险、真起了纠纷，靠的都是这些","grade":"A","src":"国务院 (2018). 医疗纠纷预防和处理条例（国务院令第 701 号）第十六条：「患者有权查阅、复制其门诊病历、住院志、体温单、医嘱单、化验单（检验报告）、医学影像检查资料、特殊检查同意书、手术同意书、手术及麻醉记录、病理资料、护理记录、医疗费用以及国务院卫生主管部门规定的其他属于病历的全部资料。」「患者要求复制病历资料的，医疗机构应当提供复制服务，并在复制的病历资料上加盖证明印记……可以收取工本费，收费标准应当公开。」「患者死亡的，其近亲属可以依照本条例的规定，查阅、复制病历资料。」第十五条「任何单位和个人不得篡改、伪造、隐匿、毁灭或者抢夺病历资料。」<https://www.gov.cn/zhengce/zhengceku/2018-08/31/content_5318057.htm>；国家卫生计生委、国家中医药管理局 (2013). 医疗机构病历管理规定（2013 年版）：医疗机构「应当指定部门或者专（兼）职人员负责受理复制病历资料的申请」，复制在申请人在场的情况下进行并加盖证明印记. <http://www.gov.cn/gongbao/content/2014/content_2600084.htm>","note":"复印是有专门窗口的，不用去求医生。要复印的清单直接照第十六条念。按时间顺序存一个文件夹，出院小结、手术记录、病理报告、关键影像最要紧。慢性病的历次指标记在同一个本子上，见第 16 节。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"24.7","sec":24,"n":7,"title":"对诊疗有疑问就当场要求封存病历，双方在场、开清单、各执一份","cost":"0 元；向医疗机构提出封存要求，等双方在场把手续做完","human":"对诊疗有疑问可以要求封存病历：双方在场进行，开清单、签字盖章、各执一份，还没写完的先封已完成的部分。怀疑是输液、输血、打针、用药出的问题，那袋液体、那支药和输液器要一起封存。封存之后再补写或者改动就是违法的，清单上双方都签了字。","gain":"条例规定「发生医疗纠纷需要封存、启封病历资料的，应当在医患双方在场的情况下进行」；封存的可以是原件也可以是复制件，由医疗机构保管；病历尚未完成需要封存的，对已完成部分先行封存，后续完成后再封存；医疗机构应当对封存的病历开列封存清单，由医患双方签字或者盖章，各执一份。疑似输液、输血、注射、用药等引起不良后果的，医患双方应当共同对现场实物进行封存、启封，需要检验的应当由双方共同委托有检验资格的机构，双方无法共同委托的由医疗机构所在地县级人民政府卫生主管部门指定；疑似输血引起不良后果需要封存血液的，医疗机构应当通知血站派员到场。另有一条硬约束：「任何单位和个人不得篡改、伪造、隐匿、毁灭或者抢夺病历资料。」封存后纠纷已解决，或者满 3 年未再提出解决要求的，医疗机构可以自行启封（全国，2018 年 10 月 1 日起施行）","grade":"A","src":"国务院 (2018). 医疗纠纷预防和处理条例（国务院令第 701 号，第十五、二十四、二十五条）. <https://www.gov.cn/zhengce/zhengceku/2018-08/31/content_5318057.htm>","note":"封存和复印是两件事：复印是平时就该做的（见第 6 条，病历和影像自己存一份），封存是纠纷发生时把证据固定住，防的是事后补写和修改。疑似输液、输血、用药出问题的，除了病历还要一起封存那袋液体、那支药和输液器，别让人收走扔掉。医疗机构应当在显著位置公布医疗纠纷解决途径、程序和联系方式，并设置统一的投诉管理部门，先找那个部门而不是找当班医生理论。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"24.8","sec":24,"n":8,"title":"急重的伤病直奔急诊预检分诊台，别去挂号窗口排队","cost":"0 元；进门多走几步找到分诊台，把最要命的那个症状一句话说清","human":"急诊不按先来后到，按病情分四级排。1 级濒危的立即进复苏室或抢救室，四个等级是全国口径，具体时限各地自定，北京的标准是 2 级危重 10 分钟内得到救治，3 级急症排在 4 级前面、等超过 30 分钟要再评一次，4 级非急症顺序等、候诊超过 4 小时才重新评估。定级的地方是急诊入口的预检分诊台，不是挂号窗口——不去分诊，你在系统里就没有级别，伤得再重也只能跟着队伍慢慢挪。到了先报最危险的那一条：大出血、喘不上气、意识不清、身上扎着东西、胸口压着疼。反过来，只是开药、拆线、看老毛病，会被定成 4 级，去急诊只会等更久。","gain":"国家卫生健康委 2024 年版急诊医学质控指标规定，急诊预检分诊「按病情危重程度将患者分为四级：I 级为急危患者，需要立即得到救治；II 级为急重患者，往往评估与救治同时进行；III 级为急症患者，需要短时间内得到诊治；IV 级为非急症患者或亚急症患者，在普通诊疗区顺序就诊」。北京市的执行标准给出各级响应要求：1 级「立即进行评估和救治，安排患者进入复苏室或抢救室」；2 级「立即监护生命体征，10 分钟内得到救治，安排患者进入抢救室」；3 级「先于 4 级患者优先诊治，安排患者在普通诊疗区候诊；若候诊时间大于 30 分钟，需再次评估」；4 级「顺序就诊，除非病情变化，否则候诊时间较长；若候诊时间大于 4 小时，可再次评估」；分诊要「坚持急危重症优先就诊原则」，急诊科入口显著位置应设预检分诊区域（四级标准为全国口径，响应时间为北京市标准）","grade":"A","src":"国家卫生健康委办公厅 (2024). 关于印发急诊医学等 6 个专业医疗质量控制指标（2024 年版）的通知（国卫办医政函〔2024〕150 号）附件 1，指标四「急诊分级分诊执行率」. <https://www.gov.cn/zhengce/zhengceku/202405/content_6951260.htm>；北京市卫生健康委员会 (2019). 北京市加强急诊预检分诊分级工作方案及附件《北京市医院急诊预检分诊分级标准（试行）》：「坚持急危重症优先就诊原则。按照患者病情的严重程度，遵循从重到轻、从病情迅速变化到相对稳定的原则，合理安排患者就诊顺序。」「在急诊科入口的显著位置，设置急诊预检分诊区域」. <http://wjw.beijing.gov.cn/zwgk_20040/ylws/201912/t20191216_1242338.html>","note":"四级分诊是全国口径，各级的响应时间由各省市自己定，北京这份是能逐字核对的一版。定级看的是生命体征和症状，不是你觉得有多疼：1 级的硬指标包括心率大于 180 次/分或小于 40 次/分、收缩压低于 70 mmHg、血氧低于 80%、休克、明确心肌梗死、急性意识障碍。觉得分诊定低了，就补充说清最危险的那个症状；候诊中病情变化要立刻回分诊台重新评估。真正危重的时候打 120 比自己去更快，院前医生会按同一套标准初步定级并提前通知医院备接诊（见第 13 节）。","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"24.9","sec":24,"n":9,"title":"没带钱、没带证件、说不清自己是谁，急诊也必须先救","cost":"0 元","human":"国家有一笔疾病应急救助基金，专门付两种人的急救费：身份查不出来的，和身份清楚但掏不出钱的。医疗机构不得以任何理由拒绝、推诿或者拖延救治，急救中心也不得因为费用问题拒绝或延误出车。所以别因为身上没钱就在家硬扛，也别因为怕欠费不敢叫救护车。这笔钱只管急救那一段，后面的住院治疗还是走医保和医疗救助。","gain":"疾病应急救助制度的救助对象是「在中国境内发生急重危伤病、需要急救但身份不明确或无力支付相应费用的患者」，基金支付「无法查明身份患者所发生的急救费用」和「身份明确但无力缴费的患者所拖欠的急救费用」；「各级各类医疗机构及其工作人员必须及时、有效地对急重危伤患者施救，不得以任何理由拒绝、推诿或拖延救治」。院前一段：全国院前医疗急救呼叫号码为「120」，急救中心（站）「不得因指挥调度原因拒绝、推诿或者延误院前医疗急救服务」，且「不得因费用问题拒绝或者延误院前医疗急救服务」，转运遵循「就近、就急、满足专业需要、兼顾患者意愿的原则」（全国，2013 年起）","grade":"A","src":"国务院办公厅 (2013). 关于建立疾病应急救助制度的指导意见（国办发〔2013〕15 号）. <https://www.gov.cn/zhengce/zhengceku/2013-03/01/content_6069.htm>；国家卫生和计划生育委员会 (2014). 院前医疗急救管理办法（委令第 3 号，第十三、二十二、二十三、二十五条）. <http://www.gov.cn/gongbao/content/2014/content_2580977.htm>","note":"基金只兜「急救费用」那一段，而且是先救治、事后由医疗机构向基金申请，不是你去窗口领钱；有医保的照常先走医保，各省的申请流程和限额不同。转运原则里「就近、就急」排在「患者意愿」前面，所以救护车不一定送你指定的那家医院，危重时以最近能处理的为准。后续自付仍然过重的，走医疗救助（见第 7 节）。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"24.10","sec":24,"n":10,"title":"伤残鉴定要等治疗终结之后再做，做早了等级会评低","cost":"鉴定费几百到两千元不等，一般由申请方先垫；要等治疗终结或临床效果稳定，通常是伤后三到六个月甚至更久","human":"赔多少钱主要看评几级，评几级看的是治完之后还剩多少功能障碍。标准写明要在治疗终结或者临床治疗效果稳定之后做，骨头还没长好、钢板还没取就跑去评，评的是当时那个样子，等于自己把等级压低。十级对应致残率 10%，往上每级差 10%，一级是 100%。骨折想评上十级要落到具体条款上，比如一个椎体压缩达三分之一、骨盆两处以上骨折且畸形愈合、大关节功能丧失 25% 以上——长好了不影响功能的普通骨折，评不上。","gain":"《人体损伤致残程度分级》规定鉴定时机「应在原发性损伤及其与之确有关联的并发症治疗终结或者临床治疗效果稳定后进行鉴定」；「本标准将人体损伤致残程度划分为 10 个等级，从一级（人体致残率 100%）到十级（人体致残率 10%），每级致残率相差 10%」；判断依据是「人体组织器官结构破坏、功能障碍及其对医疗、护理的依赖程度，适当考虑由于残疾引起的社会交往和心理因素影响」；十级里与骨折有关的条款包括「一椎体压缩性骨折（压缩程度达 1/3）或者粉碎性骨折」「骨盆两处以上骨折或者粉碎性骨折，畸形愈合」「四肢任一大关节（踝关节除外）功能丧失 25% 以上」；同一部位和性质的残疾不得重复计算，两处以上致残的应分别写明等级（全国，2017 年 1 月 1 日起施行）","grade":"A","src":"最高人民法院、最高人民检察院、公安部、国家安全部、司法部 (2016). 关于发布《人体损伤致残程度分级》的公告（2016 年 4 月 18 日发布，2017 年 1 月 1 日施行），标准第 4.2、4.4、4.5、5.10.6、6.2 条. <https://www.moj.gov.cn/pub/sfbgw/zwxxgk/fdzdgknr/fdzdgknrtzwj/201908/P020210316701681025917.pdf>","note":"三套评残不通用，别搞混：被人打伤、交通事故和其他人身损害走司法鉴定的《人体损伤致残程度分级》，用来算残疾赔偿金（见第 9 节）；工伤走劳动能力鉴定，用的是另一套十个伤残等级，管的是工伤待遇（见第 19 节）；想享受残疾人的政策待遇要另外办残疾人证（见第 11 条）。鉴定前把病历、手术记录、复查影像备齐（见第 6 条），缺影像是压低等级最常见的原因。损伤与原有伤病共存的，鉴定意见还要写明损伤在残疾后果里起多大作用，这一栏直接影响赔偿比例。","money":"少","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"24.11","sec":24,"n":11,"title":"治完之后确实留下功能障碍，去户籍地县级残联申请残疾人证","cost":"证本身不收工本费，评定费和照片费原则上自理，困难的可申请减免；带身份证、户口本和 3 张两寸白底照片到户籍地县级残联，评定合格后在村（社区）公示 5 个工作日，残联 10 个工作日内审核完毕","human":"残疾人证是领残疾人待遇的门槛，不是伤情证明。分视力、听力、言语、肢体、智力、精神和多重七类，每类一到四级，评定按国家标准来。流程是申请、受理、到指定机构评定、公示、审核批准、发证，有效期十年、到期免费换。评不上就是评不上，这不是找熟人能办下来的东西。后来伤情变了可以申请重新评定；对结论有异议的，十个工作日内可以到市级残联申请重评。","gain":"残疾人证「是认定残疾人及其残疾类别、残疾等级的合法凭证，是残疾人依法享有国家和地方政府优惠政策的重要依据」，评定标准是国家标准《残疾人残疾分类和分级》（GB/T 26341-2010）；坚持申领自愿、属地管理，视力、听力、言语、肢体、智力、精神及多重七类残疾人均可申领，残疾等级为一至四级；县级残联负责申办受理与核发，依据省级指定的医院或专业机构作出的评定结论；评定结论符合标准的在村（社区）公示五个工作日，县级残联「在十个工作日内审核完毕」；「办理残疾人证不收取工本费」，评定与照片费用「原则上由申请人个人自理；有条件的地方可由当地财政予以补贴，对特殊困难的申请人应协调有关部门予以减免」；有效期十年、期满免费换领；残疾类别或等级发生变化的可申请重新评定；对评定结论有异议的可在十个工作日内到地市级残联申请重新评定，仍有异议的由省级残疾评定专家委员会作出最终结论（全国，2018 年 1 月 1 日起施行）","grade":"A","src":"中国残疾人联合会、国家卫生和计划生育委员会 (2017). 中华人民共和国残疾人证管理办法（2017 年 5 月 27 日发布，2018 年 1 月 1 日施行；第二、三、五、七、九、十七、十九、二十二、二十五条）. <https://www.bdpf.org.cn/cms68/web1459/subject/n1/n1459/n1508/n1509/n1512/c68465/content.html>","note":"办不办先算账：证本身不直接发钱，接上的是残疾人两项补贴（低保家庭中的残疾人领生活补贴，一级二级且需长期照护的领护理补贴，见第 7 节第 9 条），以及各地的康复、辅具、税费、就业和交通优惠，标准各省差别很大，先在当地残联官网查清楚再决定跑不跑这一趟。它和司法鉴定的伤残等级、工伤的劳动能力鉴定是三套东西，互不替代（见第 10 条）。证只限本人使用、不得转借；残疾状况不再符合标准的会被注销，注销后一年内不得重新申请。多重残疾按其中最重的一类定等级。","money":"少","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"24.12","sec":24,"n":12,"title":"谢救过你的医生，走感谢信、锦旗和满意度评价，别走红包：准则禁的是财物，不是谢意","cost":"0 元；写一封信或者在满意度平台上填一次，十几分钟","human":"这里是两件事，别混。一件是事前塞钱买「优先」，买不到：九项准则第七项严禁利用号源、床源、紧缺药品耗材，或者检查、手术等诊疗安排收受好处，你想买的那个优先本身就是禁止交易的东西。另一件是事后想谢谢救过你命的人，这该谢，但方式要换：第八项严禁索取或者收受患者及其亲友的礼品、礼金、消费卡、有价证券等财物，也就是说你把烟酒塞过去，是把对方放到违规的位置上——他推回来不是不领情，是在护着自己的饭碗。能真正落到他身上的谢法有三种：① 在国家卫生健康委满意度调查平台上认真填一次，三级公立医院绩效考核的四个维度里就有满意度评价，由门诊患者、住院患者和医务人员满意度构成，调查结果纳入绩效考核；② 写一封点名到人、写清哪天哪台手术的感谢信，交给医院的投诉管理部门（二级以上医疗机构应当设医患关系办公室或者指定部门统一受理意见、建议和投诉），或者送一面锦旗；③ 按医嘱复查、如实反馈恢复情况——对经手的医生来说，你好好活着就是这台手术的最终结果。","gain":"《医疗机构工作人员廉洁从业九项准则》（国卫医发〔2021〕41 号）第七项：「维护诊疗秩序，不破坏就医公平。坚持平等原则，共建公平就医环境。严禁利用号源、床源、紧缺药品耗材等医疗资源或者检查、手术等诊疗安排收受好处、损公肥私」；第八项：「共建和谐关系，不收受患方『红包』。恪守医德、严格自律。严禁索取或者收受患者及其亲友的礼品、礼金、消费卡和有价证券、股权、其他金融产品等财物；严禁参加其安排、组织或者支付费用的宴请或者旅游、健身、娱乐等活动安排」，文件同时要求医疗机构落实主体责任、开展督查、「坚决查处违规行为」。《国务院办公厅关于加强三级公立医院绩效考核工作的意见》（国办发〔2019〕4 号）：「三级公立医院绩效考核指标体系由医疗质量、运营效率、持续发展、满意度评价等 4 个方面的指标构成」；「医院满意度由患者满意度和医务人员满意度两部分组成……通过门诊患者、住院患者和医务人员满意度评价，衡量患者获得感及医务人员积极性」；「国家建立公立医院满意度管理制度……2019 年 3 月底前，全国三级公立医院全部纳入国家卫生健康委满意度调查平台。各地要应用国家卫生健康委满意度调查平台，将调查结果纳入三级公立医院绩效考核」。《医疗机构投诉管理办法》（国家卫生健康委令第 3 号，2019 年施行）第二条：投诉管理是指患者就医疗服务行为、医疗管理、医疗质量安全等方面「提出意见、建议或者投诉请求」，医疗机构调查、处理和反馈的活动；「二级以上医疗机构应当设置医患关系办公室或者指定部门（以下统称投诉管理部门）统一承担投诉管理工作」，投诉管理部门职责包括「统一受理投诉，调查、核实投诉事项，提出处理意见，及时答复患者」，医疗机构「应当鼓励工作人员主动收集患者对医疗服务、医疗质量安全等方面的意见和建议」（全国）","grade":"A","src":"国家卫生健康委、国家医保局、国家中医药局 (2021). 关于印发医疗机构工作人员廉洁从业九项准则的通知（国卫医发〔2021〕41 号）. 国务院公报 <http://www.gov.cn/gongbao/content/2022/content_5678098.htm>；国务院办公厅 (2019). 关于加强三级公立医院绩效考核工作的意见（国办发〔2019〕4 号）. <https://www.gov.cn/zhengce/zhengceku/2019-01/30/content_5362266.htm>；国家卫生健康委 (2019). 医疗机构投诉管理办法（委令第 3 号）. <https://www.gov.cn/zhengce/zhengceku/2019-10/08/content_5436976.htm>","note":"受益人是你自己，也是救了你的那个人。这条不主张「什么都别表达」——通宵抢救之后想谢是人之常情，要改的只是形式：红包和烟酒把风险转给了对方，感谢信、锦旗和满意度评价是制度里认账的那条路。已经送出去、对方推回来的，别当成嫌少或者摆架子，那是他必须做的动作。另外分清楚：送医生红包属于行业纪律和医院处理的范畴，送办案、执法人员财物是刑法上的行贿罪，两件事不是一个量级，后者见第 8 节第 38 条。写感谢信、送锦旗医院普遍接受，但「会进个人和科室记录」是经验之谈、没有文件规定；有文件依据的是满意度调查结果纳入三级公立医院绩效考核这一条。对诊疗本身有疑问时的动作是当场要求封存病历（见本节第 7 条）、留存病历与影像（第 6 条）","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"}]},{"n":25,"title":"人走了以后要办什么","intro":"口径：金钱。这一节只讲手续和钱：人没了当时先做什么、哪些费用有清单可依、哪些账户里的钱能取回来、哪些权利由近亲属行使。前五条按事情发生的先后排——现场、死亡证明、遗体和火化、死因异议、销户，之后几条按性价比排。老人生前该做的安排（意定监护、遗嘱、账户）见第 17 节；因工死亡的三笔待遇见第 19 节。\n殡葬部分依据 2026 年 3 月 30 日起施行的新版《殡葬管理条例》。养老保险的丧葬补助金与遗属抚恤金标准由人力资源社会保障部门另行规定，本次未取得可逐字核对的原文，正文不写具体金额。","entries":[{"id":"25.1","sec":25,"n":1,"title":"人在家里或外面没了，先分清正常死亡还是非正常死亡：意外、死因不明、独居才发现的，立刻报警，遗体和现场不要动","cost":"0 元，打一个电话","human":"意外、死因不明、独居很久才被发现的，死亡证明只有公安能开；现场被动过就既说不清也不好开。这一张纸拿不到，后面火化、销户、保险理赔全部卡住。分不清是哪种情况就先打 110，警察到场调查完照样能出证。","gain":"户口登记条例第八条第二款：「公民因意外事故致死或者死因不明，户主、发现人应当立即报告当地公安派出所或者乡、镇人民委员会」；殡葬管理条例第二十三条：「自然人正常死亡的，医疗卫生机构应当及时出具死亡证明。涉及公安机关依法处置且未经医疗卫生机构救治的非正常死亡案（事）件的逝者，由公安机关出具死亡证明」。非正常死亡的死亡证明只有公安能开，现场被动过就既说不清也不好开，后面火化、销户、保险理赔全部卡在这一张纸上","grade":"A","src":"全国人大常委会 (1958). 中华人民共和国户口登记条例（第八条）. <http://www.gd.gov.cn/zwgk/wjk/zcfgk/content/mpost_2531969.html>（广东省人民政府门户网站刊登）；国务院 (2026). 殡葬管理条例（国务院令第 824 号，自 2026 年 3 月 30 日起施行，第二十三条）. <https://www.gov.cn/zhengce/zhengceku/202601/content_7054169.htm>","note":"长期卧病、在家临终这类正常死亡，联系生前给他看病的机构或本辖区社区卫生服务中心、乡镇卫生院出证（见下一条）。分不清就按非正常处理，先打 110——警察到场调查完照样能出证，反过来把现场收拾干净了再报，谁也帮不了你。不要自行搬运遗体、不要擦洗更衣、不要收走药瓶和字条。","money":"0","time":"少","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"25.2","sec":25,"n":2,"title":"死亡证明是后面所有事的钥匙：谁救治谁开，家中正常死亡找社区卫生服务机构，一日内签发","cost":"0 元","human":"在医疗机构去世的由负责救治的机构开，在家中或别处正常死亡的找辖区社区卫生服务机构、乡镇卫生院开，死因明确的一天内签发，纸质和电子证照效力相同。销户、火化、取公积金、领社保待遇、理赔、办继承每一件都要用它，拿到先多复印几份；丢了只能补发一次，信息有错也只能重新签发一次。","gain":"《人口死亡信息登记管理规范（试行）》：在医疗卫生机构内死亡的，由「负责救治的医疗卫生机构签发」；在家中或其他场所正常死亡的，「由本辖区社区卫生服务机构或乡镇（街道）卫生院签发」；公安司法机构判断为非正常死亡的，由公安司法部门按现行规定及程序办理。2026 年五部门通知：《死亡证明》「纸质版与电子证照具有同等法律效力」，死因已明确的正常死亡应在死亡发生后一日内签发；遗失可向原签发机构申请补发一次，基本信息有误的可凭材料申请重新签发一次","grade":"A","src":"国家卫生计生委办公厅 (2014). 人口死亡信息登记管理规范（试行）（国卫办规划发〔2014〕68 号，第九条）. <https://mzj.sz.gov.cn/szmz/pc/zwgk/jcxxgk/zcfg/byfw/content/post_2952215.html>（深圳市民政局转发）；国家卫生健康委、公安部、民政部、国家中医药局、国家疾控局 (2026). 关于加强居民死亡医学证明信息登记和电子证照管理工作的通知（国卫规划发〔2026〕5 号）. <https://wjw.fujian.gov.cn/xxgk/fgwj/gjwj/202602/t20260228_7102810.htm>（福建省卫生健康委员会转发）","note":"销户、火化、取公积金、领社保待遇、保险理赔、办继承，每一件都要用它。拿到手先多复印几份，能开电子证照的一并申请。补发只有一次机会，原件别弄丢；名字、身份证号有错当场就改，等到办继承时才发现，每个窗口都要重跑一遍。","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"25.3","sec":25,"n":3,"title":"遗体接运、存放、火化只能走殡仪馆，医院太平间不办殡仪，存放一般不超过 3 日","cost":"0 元","human":"接运、存放、防腐、整容、火化只能由殡仪馆做，医院太平间不得外包、不得办殡仪，最多提供暂时停放；殡仪馆存放一般不超过 3 日，要延期得办手续。火化凭死亡证明和火化确认书，出的火化证明后面办继承、理赔、迁骨灰还要用。在医院凑上来的「一条龙」多半不是殡仪馆的人。","gain":"殡葬管理条例第二十五条「遗体接运、存放、防腐、整容、火化服务，由殡仪馆专门负责提供」；第二十四条「医疗卫生机构的太平间不得外包，不得开展殡仪服务，可以为遗体暂时停放提供便利服务」；第二十七条「殡仪馆存放遗体一般不超过 3 日，需要延期存放的，丧属或者遗体移交方应当在殡仪馆办理延期存放手续」；第二十八条「殡仪馆应当凭死亡证明和火化确认书火化遗体，并出具火化证明」；第二十九条「在实行火葬的地区，遗体应当就地、就近在殡仪馆火化」","grade":"A","src":"国务院 (2026). 殡葬管理条例（国务院令第 824 号，自 2026 年 3 月 30 日起施行，第八、九、二十四、二十五、二十七、二十八、二十九条）. <https://www.gov.cn/zhengce/zhengceku/202601/content_7054169.htm>","note":"在医院去世后凑上来的「一条龙」多半不是殡仪馆的人，接运本身属于基础项目、有定价（见第 6 条）。火化证明收好，办继承、保险、迁骨灰都要用。火葬区与土葬区由省级政府划定，少数民族的丧葬习俗受条例第九条保护；该火化而土葬、或者在公墓和生态安葬区域以外埋葬建坟的，民政部门会责令限期改正。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"25.4","sec":25,"n":4,"title":"对死因有异议，48 小时内提出尸检，同时封存病历","cost":"0 元；难的是在那个时候还想得起来提","human":"对死因有异议，要在死亡后 48 小时内提出尸检，有冻存条件的可以延到 7 日，还要经近亲属签字同意；不同意或者拖过时间、影响死因判定的，责任由拖延的一方承担。遗体一旦火化就再没有尸检的可能，所以这件事要在联系殡仪馆之前定下来。","gain":"医疗纠纷预防和处理条例第二十六条：「患者死亡，医患双方对死因有异议的，应当在患者死亡后 48 小时内进行尸检；具备尸体冻存条件的，可以延长至 7 日」「尸检应当经死者近亲属同意并签字，拒绝签字的，视为死者近亲属不同意进行尸检」「不同意或者拖延尸检，超过规定时间，影响对死因判定的，由不同意或者拖延的一方承担责任」；第二十四条：封存、启封病历资料「应当在医患双方在场的情况下进行」","grade":"A","src":"国务院 (2018). 医疗纠纷预防和处理条例（国务院令第 701 号，第二十四、二十六条）. <https://www.gov.cn/zhengce/content/2018-08/31/content_5318057.htm>","note":"过了这个窗口再说「当初就觉得不对」，责任反过来落在拖延的一方。遗体一旦火化就再没有尸检的可能，所以这件事必须在联系殡仪馆之前定下来。病历怎么封存见第 24 节。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"25.5","sec":25,"n":5,"title":"注销户口有法定时限：城市在安葬前，农村在一个月以内","cost":"0 元；带死亡证明和户口簿去派出所跑一趟","human":"城市在安葬前、农村在一个月以内，要拿死亡证明和户口簿去派出所注销户口。拖着不办，继承过户、领待遇、退保都会卡在户籍状态上；拖着不办会影响后面一连串手续。","gain":"户口登记条例第八条第一款：「公民死亡，城市在葬前，农村在一个月以内，由户主、亲属、抚养人或者邻居向户口登记机关申报死亡登记，注销户口。公民如果在暂住地死亡，由暂住地户口登记机关通知常住地户口登记机关注销户口」","grade":"A","src":"全国人大常委会 (1958). 中华人民共和国户口登记条例（第八条）. <http://www.gd.gov.cn/zwgk/wjk/zcfgk/content/mpost_2531969.html>（广东省人民政府门户网站刊登）","note":"拖着不销户，继承过户、领待遇、退保都会卡在户籍状态上；养老金继续发放则构成冒领，早晚要退。去派出所时顺便问清社保、医保待遇怎么停、丧葬补助怎么申领，那几笔钱见第 9 条。","money":"0","time":"少","will":"否","level":"小","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"25.6","sec":25,"n":6,"title":"殡葬服务分基础项目和非基础项目，基础项目有清单、收费依法制定","cost":"0 元，出发前花几分钟看一眼清单","human":"遗体接运、存放、告别、火化、骨灰寄存、生态安葬，以及公办机构提供的骨灰格位安葬，都在国家的基础项目清单里，收费依法制定，清单之外不许另立项目收费。出发前先问清哪几项算基础项目、当地标准是多少，再谈其余的。","gain":"遗体接运、遗体存放、遗体告别、遗体火化、骨灰寄存、生态安葬，以及政府举办的殡葬服务机构提供的骨灰格位安葬，都在国家的基础项目清单里，收费标准依法制定；非基础项目清单由设区的市级以上民政部门确定","grade":"A","src":"国务院 (2026). 殡葬管理条例（国务院令第 824 号，2025 年 11 月 14 日国务院第 72 次常务会议修订通过，「自2026年3月30日起施行」）. <https://www.gov.cn/zhengce/zhengceku/202601/content_7054169.htm> 第五条：「殡葬服务分为基础项目和非基础项目，收费政策由国务院发展改革部门、财政部门会同国务院民政等部门制定。」「国家制定殡葬服务基础项目清单，将遗体接运、遗体存放、遗体告别、遗体火化、骨灰寄存、生态安葬以及政府举办的殡葬服务机构提供的骨灰格位安葬等纳入清单范围」；第五十条「殡葬服务实行清单化管理并动态调整，禁止在清单之外设立项目、收取费用。」","note":"省、自治区、直辖市可以在国家清单基础上再加项目。先问清楚哪几项属于基础项目、当地的收费标准是多少，再谈其余的。想把亲人的后事办得体面一点不是错，这条不劝人从简，只解决一件事：哪些项目有清单、有依法定的收费标准，哪些是自选——把这条线分清楚，钱花在哪儿是你自己定，被人在悲痛里多收的那部分才有得说","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"25.7","sec":25,"n":7,"title":"遇到强制搭售、标价外加价、把一项拆成几项收费，记下来投诉","cost":"0 元；难的是在那个当口还愿意较真","human":"不明码标价、在标价之外加钱、捆绑或者附加条件强卖丧葬用品、逼着接受第三方的有偿服务，是条例点名的价格违法行为；把一项拆成几项、扩大范围收费也算变相涨价。当场先要价目表、留好收费凭据和聊天记录，事后再投诉一样来得及——查价格找市场监管，管殡葬服务找民政。","gain":"条例列了五类价格违法行为，包括不明码标价、标价之外加价、捆绑或附加不合理条件强制销售、强制接受第三方有偿服务；另外禁止「分解项目、扩大范围收费等形式变相提高收费标准」","grade":"A","src":"国务院 (2026). 殡葬管理条例（国务院令第 824 号，2025 年 11 月 14 日国务院第 72 次常务会议修订通过，「自2026年3月30日起施行」）. <https://www.gov.cn/zhengce/zhengceku/202601/content_7054169.htm> 第四十二条：「殡葬服务机构不得违反有关规定擅自设立收费项目，或者采取分解项目、扩大范围收费等形式变相提高收费标准。」第四十三条列举的价格违法行为含「（一）不按规定明码标价，或者在标价之外加价或者收取未标明的费用」「（三）采取捆绑、附加不合理条件或者不合理限制等方式，强制或者变相强制销售丧葬用品、提供殡葬相关服务并收取费用」「（四）强制或者变相强制丧属接受第三方的有偿服务，或者利用相关服务网点重复收取费用」；第五十一条要求民政部门与政务服务便民热线建立信息共享监督机制，「对丧属反映的殡葬服务问题，应当会同有关部门及时予以处理并将处理结果告知丧属」","note":"查处价格违法归市场监管部门，殡葬服务本身归民政部门。当场先要价目表、留好收费凭据和聊天记录，事后再投诉也来得及。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"25.8","sec":25,"n":8,"title":"殡葬代理、用品代购、策划主持这类中介，要在县级民政备案","cost":"0 元，问一句备没备案","human":"殡葬代理、用品代购、策划主持、信息咨询这类中介要在县级民政部门备案，没备案的不进殡葬服务信息系统。用骗术乱收费、诱导大操大办、强迫接受服务、倒卖逝者信息的会被依法处置，还要在系统里标注并向社会公开。刚办完手续就接到一堆推销电话，多半就是信息被卖了出去。","gain":"未备案的中介不在殡葬服务信息系统里；以欺骗手段违规收费、诱导大操大办、强迫接受服务、倒卖逝者信息的，会被依法处置并在系统中标注、向社会公开","grade":"A","src":"国务院 (2026). 殡葬管理条例（国务院令第 824 号，2025 年 11 月 14 日国务院第 72 次常务会议修订通过，「自2026年3月30日起施行」）. <https://www.gov.cn/zhengce/zhengceku/202601/content_7054169.htm> 第四十一条：「除殡葬服务机构外，从事殡葬服务代理、用品代购、策划主持、信息咨询等殡葬相关服务活动的组织和个人，应当向县级人民政府民政部门备案。」「对存在以欺骗等手段违规收费、诱导大操大办、强迫接受服务、倒卖逝者信息等损害丧属权益行为的依法处置，并在殡葬服务信息系统中进行标注，向社会公开。」","note":"「倒卖逝者信息」是这一行里最常见的坑：刚办完手续就接到一堆推销电话，多半是信息被转卖了。网络祭扫平台同样受约束，条例第四十五条禁止诱导消费和违法处理逝者信息。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"25.9","sec":25,"n":9,"title":"分散在各处的钱要逐个去取：公积金余额、社保待遇、工伤待遇","cost":"跑几个窗口，备齐死亡证明与亲属关系证明","human":"住房公积金账户里的余额，继承人和受遗赠人可以提取——这笔钱不在银行账户里、不会自动进入遗产分配，最容易被漏掉。因工死亡的另有丧葬补助金、供养亲属抚恤金和一次性工亡补助金三笔。养老保险个人账户余额和遗属待遇要去参保地社保经办机构问，各地要的材料不一样。","gain":"住房公积金账户余额，继承人、受遗赠人可以提取；因工死亡的有丧葬补助金、供养亲属抚恤金和一次性工亡补助金三笔","grade":"A","src":"国务院 (2026). 住房公积金管理条例（国务院令第 844 号修改，2026 年 9 月 20 日起施行）第二十四条末款. <https://www.gov.cn/gongbao/2026/issue_12946/202608/content_7079363.html>：「职工死亡或者被宣告死亡的，职工的继承人、受遗赠人可以提取职工住房公积金账户内的存储余额；无继承人也无受遗赠人的，职工住房公积金账户内的存储余额纳入住房公积金的增值收益。」；工伤保险条例第三十九条的三笔待遇见第 19 节. <https://www.gov.cn/gongbao/content/2011/content_1778064.htm>；TODO（待核实：基本养老保险个人账户余额的继承规则，以及丧葬补助金与遗属抚恤金的具体标准，人社部相关文件本次未取得）","note":"公积金那笔常被忘掉，因为它不在银行账户里、不会自动进入遗产分配。养老保险个人账户余额和遗属待遇要去参保地社保经办机构问，各地的材料清单不一样。遗嘱和继承的形式要求见第 17 节。","money":"0","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"25.10","sec":25,"n":10,"title":"死者的账号和个人信息，近亲属可以要求查阅、复制、更正、删除","cost":"0 元；平台不配合才需要投诉或起诉","human":"人走以后，近亲属为了自己的合法正当利益，可以要求平台查阅、复制、更正、删除死者的个人信息；平台拒绝要说明理由，也可以去法院起诉。例外是他生前另有安排——设过账号继承人或者留下明确意愿的，按那个来。","gain":"法律明写：自然人死亡的，近亲属为了自身合法、正当利益，可以对死者的相关个人信息行使查阅、复制、更正、删除等权利","grade":"A","src":"全国人大常委会 (2021). 个人信息保护法. 中国人大网. <http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html> 第四十九条：「自然人死亡的，其近亲属为了自身的合法、正当利益，可以对死者的相关个人信息行使本章规定的查阅、复制、更正、删除等权利；死者生前另有安排的除外。」；第五十条「个人信息处理者应当建立便捷的个人行使权利的申请受理和处理机制。拒绝个人行使权利的请求的，应当说明理由」「个人可以依法向人民法院提起诉讼」","note":"「死者生前另有安排的除外」——生前设过账号继承人或者留过明确意愿的，按那个来。这也是为什么值得趁清醒时把账号和密码的去向写下来，见第 17 节。注销账号和删除个人信息是两件事，见第 14 节。","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"}]},{"n":26,"title":"做一个网站或平台：资质、备案和服务器","intro":"本节回答一件事：你要做的这个网站或 App，在法律上算什么业务，需要哪张证，服务器该放在哪里，用户在上面发的东西和收的钱由谁负责。口径是人身自由与金钱：先写会碰到刑事红线的，再写需要行政许可的，然后是平台的日常义务，最后是选服务器这类只能给判断的经验条目。受雇技术人的红线在第 11 节，公司怎么注册、怎么报税在第 12 节，本节不重复。各类证的对照表和选服务器的决策表见 [docs/做平台要办哪些证.md](../docs/做平台要办哪些证.md)。","entries":[{"id":"26.1","sec":26,"n":1,"title":"平台不要自己收钱再转给卖家，让钱走持牌支付机构直接结算","cost":"0 元；接入持牌支付机构的分账或担保交易产品，买家的钱直接结算给卖家，不落进平台自己的账户","human":"买家的钱先进平台自己的账户再转给卖家，做的就是支付业务：这件事要中国人民银行批准，注册资本最低一亿元且实缴。没批准就干，会被取缔、没收违法所得，罚款几十万到几百万，法定代表人和直接责任人另罚十万到五十万；按非法经营论处的，情节严重判五年以下，特别严重五年以上。稳妥做法只有一条，钱不进平台账户。","gain":"支付业务是「根据收款人或者付款人提交的电子支付指令转移货币资金」，设立支付机构「应当经中国人民银行批准，取得支付业务许可」，注册资本最低 1 亿元且为实缴货币资本；「未经依法批准，擅自设立非银行支付机构、从事或者变相从事支付业务的，由中国人民银行依法予以取缔，没收违法所得」，违法所得 50 万元以上的并处 1 到 5 倍罚款，没有违法所得或不足 50 万元的处 50 万到 200 万元罚款，法定代表人和直接责任人另处 10 万到 50 万元；刑法把「非法从事资金支付结算业务」列为非法经营行为，情节严重处 5 年以下，特别严重处 5 年以上，两高解释的「情节严重」线是非法经营数额 500 万元以上或者违法所得 10 万元以上（全国，2024 年 5 月起）","grade":"A","src":"国务院 (2023). 非银行支付机构监督管理条例（国务院令第 768 号，第二、六、八、二十七、四十七条）. <https://www.gov.cn/gongbao/2024/issue_11086/202401/content_6924970.html> ; 中国人民银行 (2024). 非银行支付机构监督管理条例实施细则（中国人民银行令〔2024〕第 4 号，第六十八条）. <https://www.gov.cn/gongbao/2024/issue_11546/202408/content_6970979.html> ; 全国人大 (1997). 刑法（第二百二十五条第三项）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml> ; 最高人民法院、最高人民检察院 (2019). 关于办理非法从事资金支付结算业务、非法买卖外汇刑事案件适用法律若干问题的解释（第一、三、四条）. <https://www.spp.gov.cn/xwfbh/wsfbt/201901/t20190131_407161.shtml>","note":"官方文件里没有「二清」这个词，实施细则的说法是「变相从事支付业务」，指未经批准「根据用户提交的电子支付指令转移货币资金」。两高解释列举的三种情形是虚构交易套现、单位账户套现和支票套现，没有点名平台代收代付，所以本条按法条口径写，不写「一定构成犯罪」。稳妥做法只有一条：钱不进平台账户","money":"0","time":"中","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"26.2","sec":26,"n":2,"title":"收费的网站要许可证，撮合交易的是另一类许可，免费的只要备案","cost":"备案免费；申请增值电信业务经营许可要有公司，省内经营注册资本不低于 100 万元，跨省不低于 1000 万元，审查期 60 日，证的有效期 5 年","human":"向用户收钱的网站属于经营性，要办增值电信业务经营许可：申请人必须是公司，个人办不了，省内经营注册资本不低于 100 万、跨省不低于 1000 万，审查 60 日，证有效期 5 年。免费的网站只要备案，备案不花钱。无证或者超范围经营的，没收违法所得再罚 3 到 5 倍，没有违法所得的罚 10 万到 100 万，情节严重的关站。","gain":"「国家对经营性互联网信息服务实行许可制度；对非经营性互联网信息服务实行备案制度。未取得许可或者未履行备案手续的，不得从事互联网信息服务」，经营性指「通过互联网向上网用户有偿提供信息或者网页制作等服务活动」；在线数据处理与交易处理业务指「利用各种与公用通信网或互联网相连的数据与交易/事务处理应用平台，通过公用通信网或互联网为用户提供在线数据处理和交易/事务处理的业务」，「包括交易处理业务、电子数据交换业务和网络/电子设备数据处理业务」；无证经营或者超范围经营的，没收违法所得并处违法所得 3 到 5 倍罚款，没有违法所得或者不足 5 万元的处 10 万到 100 万元罚款，情节严重的责令关闭网站（全国）","grade":"A","src":"国务院 (2000). 互联网信息服务管理办法（国务院令第 292 号，2024 年 12 月 6 日第二次修订，第三、四、七、十九条）. <https://www.gov.cn/gongbao/content/2011/content_1860864.htm> ; 国务院 (2024). 关于修改和废止部分行政法规的决定（国务院令第 797 号，第十八项）. <https://www.gov.cn/gongbao/2025/issue_11786/202501/content_6997034.html> ; 国务院 (2000). 电信条例（2016 年第二次修订，第七、九、十三、六十九条）. <https://www.gov.cn/gongbao/content/2016/content_5139478.htm> ; 工业和信息化部 (2017). 电信业务经营许可管理办法（工信部令第 42 号，第六、九、十一、十四条）. <https://www.gov.cn/gongbao/content/2017/content_5240090.htm>","note":"官方没有任何一句话明说「带撮合和资金处理的电商平台必须办 EDI 许可」，工信部办事指南只说「按照业务界定申请相应的电信业务经营许可」，判断依据是分类目录里那条业务定义本身，所以本条只写定义，不替你下结论。个人办不了这张证：申请人必须是依法设立的公司","money":"多","time":"多","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.3","sec":26,"n":3,"title":"做直播要网络文化经营许可证，做视听节目的那张证民营基本拿不到","cost":"网络文化经营许可证由省级文化行政部门审批，受理后 20 日内决定，有效期 3 年，届满前 30 日续办；视听节目许可要求申请人是国有独资或国有控股单位","human":"做直播、游戏解说这类网络表演，要省级文化部门发的网络文化经营许可证，经营范围里得写明网络表演，受理后 20 日内出结果、有效期 3 年，表演视频要留够 60 天。没批就干，责令停止、警告并罚 3 万元以下，不停的进文化市场黑名单。做视听节目的那张证要求申请人是国有独资或国有控股，民营基本拿不到。","gain":"网络表演经营单位「应当根据《互联网文化管理暂行规定》，向省级文化行政部门申请取得《网络文化经营许可证》，许可证的经营范围应当明确包括网络表演」，游戏技法展示或者解说「参照本办法进行管理」，全部网络表演视频资料「保存时间不得少于60日」；未经批准擅自从事经营性互联网文化活动的，责令停止、予以警告并处 3 万元以下罚款，拒不停止的列入文化市场黑名单；从事互联网视听节目服务应当取得《信息网络传播视听节目许可证》，申请人应「具备法人资格，为国有独资或国有控股单位」，擅自从事的予以警告、责令改正并可处 3 万元以下罚款，情节严重的按广播电视管理条例处罚（全国）","grade":"A","src":"文化部 (2016). 网络表演经营活动管理办法（文市发〔2016〕33 号，第二、四、六、十三、二十条）. <https://zwgk.mct.gov.cn/zfxxgkml/scgl/202012/t20201206_918194.html> ; 文化部 (2011). 互联网文化管理暂行规定（文化部令第 51 号，2017 年经文化部令第 57 号修订，第七、八、九、十六、二十一、二十八条）. <https://zwgk.mct.gov.cn/zfxxgkml/zcfg/bmgz/202012/t20201204_905340.html> ; 广电总局、信息产业部 (2007). 互联网视听节目服务管理规定（第 56 号令，2015 年修订，第二、七、八、二十四条）. <https://www.gov.cn/zhengce/2022-08/23/content_5722664.htm> ; 国家网信办等七部门 (2021). 关于加强网络直播规范管理工作的指导意见（国信办发文〔2021〕3 号，第 9 项）. <https://www.gov.cn/zhengce/zhengceku/2021-02/10/content_5586472.htm>","note":"七部门文件把对应关系写得最清楚：经营性网络表演的平台要网文证加 ICP 备案，网络视听要视听证或者完成登记，互联网新闻信息要新闻信息服务许可证。中国政府网 2025 年转发的《互联网文化管理暂行规定》登的是 2011 年未修订原文，引用要以文化和旅游部的现行文本为准","money":"多","time":"多","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.4","sec":26,"n":4,"title":"服务器放境内就要备案，接入商必须自己持有增值电信许可","cost":"备案免费，随服务器在服务商处提交，通常几天到几周；查一次服务商资质十分钟","human":"服务器放在境内就要备案，备案免费、跟着服务器在服务商那里提交，通常几天到几周。没备案会被责令限期改正并罚 1 万元，不改就关站；主页不挂备案号另罚 5000 元到 5 万元。机房托管、云主机、宽带接入本身都是要许可的业务，先在工信部系统查服务商有没有证再谈价。机器搬到境外能绕开备案，但用户和钱都在境内，后面几条义务一条不少，还多一层数据出境的成本。","gain":"「未经备案，不得在中华人民共和国境内从事非经营性互联网信息服务」；未备案的责令限期改正并处 1 万元罚款，拒不改正的关闭网站；「互联网接入服务提供者不得为未经备案的组织或者个人从事非经营性互联网信息服务提供互联网接入服务」，提供接入服务的增值电信业务经营者「不得为未依法取得经营许可证或者履行非经营性互联网信息服务备案手续的单位或者个人提供接入或者代收费等服务」；机房托管与云主机（互联网数据中心业务）、宽带接入（互联网接入服务业务）本身都是需要许可的增值电信业务；网站主页不标备案号的，责令改正并处 5000 元到 5 万元罚款（全国）","grade":"A","src":"信息产业部 (2005). 非经营性互联网信息服务备案管理办法（信产部令第 33 号，2024 年经工信部令第 68 号修订，第五、十三、十八、二十二条）. <https://www.miit.gov.cn/gyhxxhb/jgsj/cyzcyfgs/bmgz/xxtxl/art/2024/art_84a0cfa0ebd049bbbe751dca9a008e56.html> ; 工业和信息化部 (2017). 电信业务经营许可管理办法（工信部令第 42 号，第二十、二十四条）. <https://www.gov.cn/gongbao/content/2017/content_5240090.htm> ; 工业和信息化部 (2015). 电信业务分类目录（2015 年版，B11、B14、B21、B25）. <https://www.miit.gov.cn/zwgk/zcwj/wjfb/tg/art/2020/art_e98406cd89844f7e92ea1bcf3b5301e0.html>","note":"查服务商有没有证，用工信部电信业务市场综合管理信息系统 tsm.miit.gov.cn，按公司全称或者证号查；查网站备案用 beian.miit.gov.cn。先查证再谈价，没有相应许可的「机房」出事时你连申诉对象都没有。把机器放到境外能绕开备案，但用户在境内、钱在境内，本节第 5 到第 10 条的义务一条都不会少，还多一层数据出境的成本","money":"0","time":"中","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.5","sec":26,"n":5,"title":"让用户上来卖东西，平台就要核验登记、报送信息、留存三年","cost":"0 元；后台要做资质核验和登记档案，按季度报送涉税信息，交易数据留三年","human":"让别人上来卖东西，就要核验并登记卖家的身份、地址、联系方式和行政许可，建档后至少每六个月复核更新一次，把身份信息报市场监管、按季度把涉税信息报税务，商品和交易信息保存三年。少做任何一项，先责令改正，逾期不改罚 2 万到 10 万，情节严重的停业整顿再罚 10 万到 50 万。","gain":"平台「应当要求申请进入平台销售商品或者提供服务的经营者提交其身份、地址、联系方式、行政许可等真实信息，进行核验、登记，建立登记档案，并定期核验更新」，部门规章细化为「至少每六个月核验更新一次」；应当向市场监管部门报送平台内经营者身份信息，并「依照税收征收管理法律、行政法规的规定，向税务部门报送平台内经营者的身份信息和与纳税有关的信息」；商品和服务信息、交易信息「保存时间自交易完成之日起不少于三年」；违反上述任一项的，责令限期改正，逾期不改正处 2 万到 10 万元罚款，情节严重的责令停业整顿并处 10 万到 50 万元；涉税信息应当「于季度终了的次月内」报送，未按期报送的罚则相同（全国）","grade":"A","src":"全国人大常委会 (2018). 电子商务法（第十、二十七、二十八、三十一、八十条）. <https://flk.npc.gov.cn/detail?id=2c909fdd678bf17901678bf8af050b81> ; 市场监管总局 (2021). 网络交易监督管理办法（市场监管总局令第 37 号，第八、二十四、二十五、三十一条）. <https://www.gov.cn/gongbao/content/2021/content_5602020.htm> ; 国务院 (2025). 互联网平台企业涉税信息报送规定（国务院令第 810 号，第二、三、四、十条）. <https://www.gov.cn/gongbao/2025/issue_12146/202507/content_7030983.html> ; 国家税务总局 (2025). 关于互联网平台企业报送涉税信息有关事项的公告（税务总局公告 2025 年第 15 号）. <https://www.gov.cn/zhengce/zhengceku/202506/content_7029727.htm>","note":"卖家一侧也有登记义务，法定例外是「个人销售自产农副产品、家庭手工业产品，个人利用自己的技能从事依法无须取得许可的便民劳务活动和零星小额交易活动」，零星小额的量化口径见网络交易监督管理办法第八条的年交易额 10 万元。平台还要区分标记已登记和未登记的经营者，并且不得删除消费者的评价","money":"0","time":"多","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.6","sec":26,"n":6,"title":"用户发的内容你要管：审核机制、举报入口、发现违法立即停传并报告","cost":"审核人力和机制是平台最大的一笔长期开支；举报入口和处置记录都要留痕","human":"用户发的东西由平台负责管：注册、发布审核、评论审核、实时巡查、应急处置这套制度要建起来，显著位置放举报入口，发现违法信息立即停止传输、保存记录并向主管部门报告。不履行的，责令改正、警告通报并罚 5 万到 50 万；拒不改正或者情节严重罚 50 万到 200 万，还可能停业整顿、关站、吊证，直接责任人另罚 5 万到 20 万。审核人力是长期最大的一笔开支。","gain":"平台「应当履行信息内容管理主体责任」，「健全用户注册、账号管理、信息发布审核、跟帖评论审核、版面页面生态管理、实时巡查、应急处置和网络谣言、黑色产业链信息处置等制度」，并「应当在显著位置设置便捷的投诉举报入口」；发现违法信息的「应当依法立即采取处置措施，保存有关记录，并向有关主管部门报告」；网络安全法要求「发现法律、行政法规禁止发布或者传输的信息的，应当立即停止传输该信息，采取消除等处置措施，防止信息扩散，保存有关记录，并向有关主管部门报告」，不履行的责令改正、给予警告、予以通报并可处 5 万到 50 万元罚款，拒不改正或者情节严重的处 50 万到 200 万元，并可责令停业整顿、关闭网站或者应用程序、吊销许可证或者营业执照，直接责任人处 5 万到 20 万元（全国）","grade":"A","src":"国家互联网信息办公室 (2019). 网络信息内容生态治理规定（网信办令第 5 号，第八、九、十、十六、三十七条）. <http://www.cac.gov.cn/2019-12/20/c_1578375159509309.htm> ; 全国人大常委会 (2025). 网络安全法（2025 年修正，2026 年 1 月 1 日施行，第四十九、六十九条）. <https://www.cac.gov.cn/2025-12/29/c_1768735112911946.htm> ; 国务院 (2000). 互联网信息服务管理办法（第十五、十六、二十三条）. <https://www.gov.cn/gongbao/content/2011/content_1860864.htm>","note":"禁止内容的九项清单在互联网信息服务管理办法第十五条，审核规则照着写就行。做直播的还要「建立直播内容审核平台」并具备「即时阻断互联网直播的技术能力」，直播内容和日志保存 60 日，网络表演的视频资料同样不少于 60 日","money":"少","time":"多","will":"是","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.7","sec":26,"n":7,"title":"提供信息发布、即时通讯服务，必须要求用户提供真实身份信息","cost":"接入实名核验通道按次收费；产品上按「后台实名、前台自愿」设计","human":"提供信息发布、即时通讯这类服务，签协议或者开通服务时就要求用户交真实身份信息，不提供的不能给他用。产品上按后台实名、前台自愿设计，用手机号一类方式核验。不做实名、或者对没实名的用户照常提供服务的，先责令改正；不改或者情节严重罚 5 万到 50 万，可以暂停业务、停业整顿、关站、吊证，直接责任人另罚 1 万到 10 万。","gain":"「网络运营者为用户办理网络接入、域名注册服务，办理固定电话、移动电话等入网手续，或者为用户提供信息发布、即时通讯等服务，在与用户签订协议或者确认提供服务时，应当要求用户提供真实身份信息。用户不提供真实身份信息的，网络运营者不得为其提供相关服务」；未要求实名或者对不提供真实身份信息的用户仍提供服务的，责令改正，拒不改正或者情节严重的处 5 万到 50 万元罚款，并可责令暂停相关业务、停业整顿、关闭网站或者应用程序、吊销许可证或者营业执照，直接责任人处 1 万到 10 万元；直播服务按「后台实名、前台自愿」原则做「基于移动电话号码等方式的真实身份信息认证」；直播带货一侧的核验口径是「基于身份证件信息、统一社会信用代码等真实身份信息认证」（全国）","grade":"A","src":"全国人大常委会 (2025). 网络安全法（2025 年修正，2026 年 1 月 1 日施行，第二十六、六十四条；2016 年文本为第二十四、六十一条）. <https://www.cac.gov.cn/2025-12/29/c_1768735112911946.htm> ; 国家互联网信息办公室 (2016). 互联网直播服务管理规定（第十二、十六条）. <https://www.cac.gov.cn/2016-11/04/c_1119847629.htm> ; 国家网信办等七部门 (2021). 网络直播营销管理办法（试行）（国信办发文〔2021〕5 号，第八条）. <https://www.gov.cn/zhengce/zhengceku/2021-04/23/content_5601682.htm>","note":"网络安全法 2025 年修正、2026 年 1 月 1 日施行，实名条从第二十四条移到第二十六条，罚则从第六十一条移到第六十四条，条文文字没变，引旧条号的材料要改","money":"少","time":"中","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.8","sec":26,"n":8,"title":"不给未满 16 周岁的人开直播，打赏按年龄分档处理","cost":"0 元；注册和支付环节加一道年龄判断与监护人同意的流程","human":"不满 16 周岁的人不能注册直播发布者账号；满 16 周岁的要核验身份并经父母或其他监护人同意。打赏现在按年龄分三档：不满 8 岁不提供打赏，8 到 16 岁要监护人同意，16 岁以上要监护人同意或者核验收入证明。限制民事行为能力的孩子未经监护人同意打出去的钱，监护人要求返还的，法院支持。","gain":"「网络直播服务提供者不得为未满十六周岁的未成年人提供网络直播发布者账号注册服务；为年满十六周岁的未成年人提供网络直播发布者账号注册服务时，应当对其身份信息进行认证，并征得其父母或者其他监护人同意」；条例要求「建立网络直播发布者真实身份信息动态核验机制」，并「合理限制不同年龄阶段未成年人在使用其服务中的单次消费数额和单日累计消费数额」；打赏的现行分档是「不得向八周岁以下的未成年人提供打赏服务。向八周岁至十六周岁的未成年人提供打赏服务，应征得其监护人同意。向十六周岁以上的未成年人提供打赏服务，应征得其监护人同意或核验其收入证明材料」；限制民事行为能力人未经监护人同意的打赏，监护人请求返还的，法院应予支持（全国）","grade":"A","src":"全国人大常委会 (2020). 未成年人保护法（第七十四、七十六条）. <https://www.cac.gov.cn/2020-10/22/c_1604928959588622.htm> ; 国务院 (2023). 未成年人网络保护条例（国务院令第 766 号，第三十一、四十四条）. <https://www.gov.cn/gongbao/2023/issue_10806/202311/content_6913813.html> ; 中央网信办秘书局 (2026). 关于加强网络直播打赏规范管理的通知（第 7 项）. <https://www.cac.gov.cn/2026-04/13/c_1777815804150225.htm> ; 最高人民法院 (2020). 关于依法妥善审理涉新冠肺炎疫情民事案件若干问题的指导意见（二）（法发〔2020〕17 号，第九条）. <https://www.court.gov.cn/fabu/xiangqing/230181.html>","note":"口径变过。2022 年四部门意见和广电总局 2020 年的通知说的是未成年人一律不得打赏，2026 年 4 月的新通知改成按 8 岁、16 岁分档，且没有写明废止前两份文件，官方也没做衔接说明，所以「未成年人一律禁止打赏」这句话现在不准确。退款争议按最有利于未成年人的原则处理","money":"0","time":"中","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.9","sec":26,"n":9,"title":"接到侵权通知要及时处理，转送声明后 15 日没有下文就恢复","cost":"0 元；建一条通知、转送、声明、公示的流程，全部记录留档","human":"权利人带初步证据发来侵权通知，平台要及时删除、屏蔽或者断开链接，并把通知转给卖家；没及时处理的，损失扩大的那部分要和卖家一起赔。卖家提出反通知转送给权利人后 15 日内没收到投诉或者起诉的通知，就恢复。明知侵权还不处理的连带赔偿，另可责令改正并罚 5 万到 50 万，情节严重 50 万到 200 万；恶意发错误通知造成卖家损失的加倍赔。","gain":"权利人「有权通知电子商务平台经营者采取删除、屏蔽、断开链接、终止交易和服务等必要措施。通知应当包括构成侵权的初步证据」，平台接到通知后「应当及时采取必要措施，并将该通知转送平台内经营者；未及时采取必要措施的，对损害的扩大部分与平台内经营者承担连带责任」；平台「在转送声明到达知识产权权利人后十五日内，未收到权利人已经投诉或者起诉通知的，应当及时终止所采取的措施」；平台知道或者应当知道侵权而未采取必要措施的，与侵权人承担连带责任，并可由知识产权部门责令限期改正，逾期不改正处 5 万到 50 万元罚款，情节严重的处 50 万到 200 万元；「恶意发出错误通知，造成平台内经营者损失的，加倍承担赔偿责任」（全国）","grade":"A","src":"全国人大常委会 (2018). 电子商务法（第四十二、四十三、四十四、四十五、八十四条）. <https://flk.npc.gov.cn/detail?id=2c909fdd678bf17901678bf8af050b81> ; 全国人大 (2020). 民法典（第一千一百九十五、一千一百九十六、一千一百九十七条）. <https://www.court.gov.cn/zixun/xiangqing/233181.html>","note":"电商法之外的一般网络服务适用民法典的通知删除规则，区别是反通知的等待期写的是「合理期限」而不是 15 日。把收到的通知、声明和处理结果公示出来，是电商法第四十四条的明文要求","money":"0","time":"中","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.10","sec":26,"n":10,"title":"用户信息不要随手放到境外，出境有法定条件和人数门槛","cost":"0 元；把用户数据留在境内最省事，确需出境的走标准合同或者认证","human":"把境内用户的信息传到境外机器上就算出境，服务器在境外不等于数据没出境。要走四条路之一：网信部门的安全评估、专业机构的认证、按标准合同签约，或者法律另有规定；还要告知境外接收方是谁、怎么处理，并单独取得用户同意。按当年 1 月 1 日起累计的人数分档：不满 10 万人且不含敏感信息的三条都免，10 万到 100 万要标准合同或者认证，100 万以上、或者敏感信息满 1 万人的要申报安全评估。","gain":"向境外提供个人信息应当具备四项条件之一：通过网信部门组织的安全评估、经专业机构做个人信息保护认证、按网信部门制定的标准合同与境外接收方订立合同，或者法律行政法规规定的其他条件；并且应当告知境外接收方的名称、联系方式、处理目的、处理方式、个人信息种类和行使权利的方式，「并取得个人的单独同意」；门槛按累计人数分档：关键信息基础设施运营者以外的数据处理者「自当年1月1日起累计向境外提供不满10万人个人信息（不含敏感个人信息）的」免予申报评估、订立标准合同和做认证；10 万人以上不满 100 万人的应当订立标准合同或者通过认证；100 万人以上，或者敏感个人信息 1 万人以上的，应当申报安全评估（全国，2024 年 3 月起）","grade":"A","src":"全国人大常委会 (2021). 个人信息保护法（第三十八、三十九、四十条）. <https://www.spp.gov.cn/spp/fl/202108/t20210820_527244.shtml> ; 国家互联网信息办公室 (2024). 促进和规范数据跨境流动规定（网信办令第 16 号，第三、四、五、七、八条）. <https://www.gov.cn/gongbao/2024/issue_11366/202405/content_6954192.html> ; 国家互联网信息办公室 (2022). 数据出境安全评估办法（网信办令第 11 号，第四条）. <https://www.cac.gov.cn/2022-07/07/c_1658811536396503.htm>","note":"服务器放境外不等于「数据没出境」，用户在境内注册、你把他的信息传到境外机器上就是出境。跨境购物、跨境寄递、机票酒店预订这类「为订立、履行个人作为一方当事人的合同」确需提供的，免予走三条路径。人数口径是「自当年 1 月 1 日起累计」，不是任意十二个月","money":"0","time":"中","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"26.11","sec":26,"n":11,"title":"选服务器先看停机能不能忍，再看有没有人运维，最后才比价","cost":"入门 VPS 每月几十元，扛得住真实流量的云主机每月数百到数千元，独立服务器托管每年数千元起且要自己买硬件","human":"三档的差别不在价格，在出事那天你手上有什么：主流云厂商有备案通道、资质公开、故障有公告和赔偿条款；小服务商能便宜一半，但超售、跑路、上游被封时你没有申诉对象；独立服务器托管只有在带宽硬件明显划算、自己又有人运维时才合算。没有用户数据的静态站，每月几十元的 VPS 就够；有注册和交易的，选能弹性扩容、能快照备份的云主机，备份放两个地方。","gain":"三档的差别不在价格，在出事时你有什么。主流云厂商有备案通道、资质公开、故障有公告和赔偿条款，出问题能找到人；小服务商价格能低一半，但超售、跑路、上游被封时你没有申诉对象，先在工信部系统查它有没有增值电信业务经营许可再谈价；独立服务器托管只有在带宽或硬件成本明显划算、并且你自己有人运维时才合算。没有用户数据的静态站用最便宜的 VPS 就够，有用户注册和交易的选能弹性扩容、能快照备份的云主机，备份至少放两个地方","grade":"C","src":"作者经验，无直接文献；服务商资质与备案的法定要求见本节第 4 条，日志留存 6 个月和等级保护义务见第 11 节第 16 条","note":"这条是判断，不是证据。能核查的只有一件事：服务商的许可证。省钱的正确位置是配置和带宽，不是资质","money":"少","time":"中","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]},{"n":27,"title":"怀孕和生产：从发现怀孕到出院办证","intro":"口径混在一起：前半节是死亡率（孕产妇和胎儿的），后半节是金钱和办事时间，两者不做换算。这一节只写「时间点」和「该做什么」，不写孕期营养、胎教这类没有硬证据或效应量很小的内容。生育津贴、产假和养孩子的钱账见第 18 节，孩子出生之后怎么带见第 20 节，急症见第 13 节。\n世界卫生组织的口径是：2023 年全球约有 26 万名女性死于妊娠和分娩，其中约 75% 死于产后大出血、感染、妊娠期高血压疾病（子痫前期和子痫）、分娩并发症和不安全人工流产这五类，而「大多数孕产妇死亡是可以预防的，因为预防和处理并发症的医疗手段都是已知的」。这一节里效应量最大的几条，都是把这几类问题提前拦下来。","entries":[{"id":"27.1","sec":27,"n":1,"title":"准备怀孕就开始每天补 0.4 毫克叶酸，一直吃到孕早期满 3 个月","cost":"几十元一瓶；农村妇女由国家免费增补叶酸项目发放。每天吃一粒，需要记得住","human":"孕前后每天吃一粒叶酸，孩子出现神经管缺陷（无脑儿、脊柱裂那一类）的概率大约能降七成；已经生过一个的人，再发生的概率也大约降到原来的三分之一。","gain":"Cochrane 系统综述（5 项试验、6708 例分娩、高质量证据）：孕前后每日补充叶酸，胎儿神经管缺陷风险 RR 0.31（95% CI 0.17 至 0.58），也就是降低约七成；对已经生过神经管缺陷患儿的人，再发风险 RR 0.34（95% CI 0.18 至 0.64）。亚组分析显示 0.4 毫克和更高剂量效果没有差别，单独吃叶酸和吃复合维生素也没有差别","grade":"A","src":"De-Regil LM, Peña-Rosas JP, Fernández-Gaxiola AC, Rayco-Solon P (2015). Effects and safety of periconceptional oral folate supplementation for preventing birth defects. Cochrane Database of Systematic Reviews, (12), CD007950. <https://doi.org/10.1002/14651858.CD007950.pub3>","note":"关键在「孕前就开始」——神经管在受孕后 28 天内就闭合了，等测出怀孕再吃已经错过大半。所以有生育打算就提前 3 个月吃。同一篇综述里，叶酸对唇腭裂、先天性心脏病、流产都没有明确效果，别指望它治别的","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"27.2","sec":27,"n":2,"title":"孕 13 周前去社区卫生服务中心建《母子健康手册》，把免费产检额度用掉","cost":"0 元，这是国家基本公共卫生服务项目的内容；要按孕周跑几趟","human":"孕期至少五次产检、加上产后访视和产后 42 天检查，是国家掏钱的。13 周前去社区建上《母子健康手册》就能用，不建就白白错过。","gain":"《国家基本公共卫生服务规范（第三版）》的孕产妇健康管理服务，给辖区内常住孕产妇的是 1 次孕早期健康检查、2 次孕中期健康检查、2 次孕晚期健康检查、1 次产后访视和 1 次产后 42 天健康检查。孕 13 周前建册并做第 1 次产前检查，孕中期两次分别在孕 16 至 20 周、21 至 24 周，孕晚期两次分别在孕 28 至 36 周、37 至 40 周。地方公开的服务清单里还包含首次的一整套化验和产后抑郁筛查","grade":"A","src":"国家卫生计生委 (2017). 国家基本公共卫生服务规范（第三版）. <https://www.nhc.gov.cn/ewebeditor/uploadfile/2017/04/20170417104506514.pdf>；靖江市人民政府. 国家基本公共卫生服务项目——孕产妇健康管理服务（地方服务清单公开）. <https://www.jingjiang.gov.cn/xxgk/zdlyxxgk/wsjk/art/2023/art_383017a2e7794892bc772bfbe042f379.html>","note":"这 5 次是免费的下限，不是产检的全部；医院会按情况加做超声、血糖、胎心监护等自费项目。建册越早，妊娠风险分级越早做出来，高危的人才能被转到有能力接的医院。跨区居住的按现住址建，不必回户籍地","money":"0","time":"中","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"27.3","sec":27,"n":3,"title":"第一次产检就把艾滋病、梅毒、乙肝三项查掉，查出来也有免费的阻断","cost":"0 元，预防母婴传播项目提供免费检测","human":"第一次产检把艾滋病、梅毒、乙肝这三样查掉，检测免费；真查出来也不是绝路，国家免费给阻断的药和方案，能把传给孩子的可能压下去。","gain":"《预防艾滋病、梅毒和乙肝母婴传播工作规范（2020 年版）》要求在孕早期或初次产前检查时告知相关信息并「提供适宜、规范的免费检测」，根据结果提供检测后咨询或转诊。查出阳性也不是绝路：《艾滋病防治条例》第四十四条规定，向感染艾滋病病毒的孕产妇「免费提供预防艾滋病母婴传播的治疗和咨询」；第四十三条要求提供阻断、治疗、产后访视、婴儿随访和检测等服务。母亲乙肝表面抗原阳性的，新生儿出生时要同时打乙肝疫苗和乙肝免疫球蛋白（见第 20 节第 2 条）","grade":"A","src":"国家卫生健康委办公厅 (2020). 预防艾滋病、梅毒和乙肝母婴传播工作规范（2020 年版）. <https://wjw.xinjiang.gov.cn/hfpc/zhgl6/202012/08b7de496f0b40e586d4b99d00cf79c4.shtml>（新疆维吾尔自治区卫生健康委员会转载）；国务院 (2006). 艾滋病防治条例（第四十三、四十四条）. <https://wjw.beijing.gov.cn/zwgk_20040/zcwj2022/flfg/202304/t20230408_2992986.html>（北京市卫生健康委员会转载）","note":"这三项越早查越有意义，因为干预都要时间。艾滋病防治条例第三条同时写明「任何单位和个人不得歧视艾滋病病毒感染者、艾滋病病人及其家属」，婚姻、就业、就医、入学等合法权益受法律保护。日常的预防和检测见第 1 节，暴露后阻断见第 13 节","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"27.4","sec":27,"n":4,"title":"整个孕期一支烟一口酒都不要，家里人也别在屋里抽","cost":"0 元，还省钱；难在让同住的人一起戒","human":"孕期抽烟，孩子早产、生下来太小、唇腭裂的概率都往上走，孕期和生产时异常出血的风险直接翻一倍，婴儿猝死的风险也更高。家里人在屋里抽一样算。什么时候戒都还来得及。","gain":"美国疾病控制与预防中心的口径：孕期吸烟会让孩子「足月出生也可能过小」「可能早产」，会「使孕期和分娩期异常出血的风险翻倍」，会提高唇裂、腭裂等出生缺陷的风险，并「损害胎儿正在发育的肺和大脑，损害可持续到儿童期」；孕期吸烟的母亲所生的婴儿、以及出生后接触烟雾的婴儿，婴儿猝死综合征风险更高。官方建议是「最好在怀孕前就戒烟，但如果已经怀孕，戒了仍然有用」「什么时候戒都不晚」","grade":"A","src":"Centers for Disease Control and Prevention. Smoking During Pregnancy. <https://www.cdc.gov/tobacco/campaign/tips/diseases/pregnancy.html>","note":"二手烟对胎儿同样算数，所以这条是全家的事，不只是孕妇自己的事。酒精没有已知的安全剂量，孕期最省事的做法是完全不喝。烟酒对成年人自己的账见第 2 节","money":"0","time":"少","will":"是","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"27.5","sec":27,"n":5,"title":"有子痫前期高危因素的，孕 12 周后开始每天一片小剂量阿司匹林","cost":"几十元；每天一片，要吃到分娩前","human":"属于高危的那几类人，从孕 12 周起每天一片小剂量阿司匹林，子痫前期的概率低约一成半，早产低约两成，孩子在围产期死亡的概率低约两成。不属于这几类的别自己吃。","gain":"美国预防服务工作组的 B 级推荐：对子痫前期高危人群，在孕 12 周后开始使用小剂量阿司匹林（81 毫克/天）作为预防用药。汇总效应：子痫前期 RR 0.85（95% CI 0.75 至 0.95，16 项研究），早产 RR 0.80（95% CI 0.67 至 0.95，13 项研究），围产期死亡 RR 0.79（95% CI 0.66 至 0.96，11 项研究），小于胎龄儿／宫内生长受限 RR 0.82（95% CI 0.68 至 0.99，16 项研究）","grade":"A","src":"US Preventive Services Task Force (2021). Aspirin Use to Prevent Preeclampsia and Related Morbidity and Mortality: Preventive Medication. <https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/low-dose-aspirin-use-for-the-prevention-of-morbidity-and-mortality-from-preeclampsia-preventive-medication>","note":"高危因素清单是既往子痫前期病史、多胎妊娠、慢性高血压、孕前 1 型或 2 型糖尿病、肾病、自身免疫病（系统性红斑狼疮、抗磷脂综合征）。不属于这几类的不要自己吃，这是处方决定，产检时把病史说清楚让医生判断。国内剂型多为 100 毫克肠溶片，按医嘱来","money":"少","time":"少","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"27.6","sec":27,"n":6,"title":"孕 24 周及以后做一次妊娠期糖尿病筛查，别嫌喝糖水麻烦","cost":"几十到一百多元；空腹抽几次血，占掉半个上午","human":"24 周以后花半个上午喝一次糖水抽血，就能查出妊娠期糖尿病。不查不管，巨大儿、难产、挨一刀、子痫前期和新生儿低血糖的风险都会往上走。","gain":"美国预防服务工作组 B 级推荐：对无症状孕妇在孕 24 周及以后筛查妊娠期糖尿病，且一次性筛查应在孕 24 周及以后进行。对孕 24 周之前筛查，工作组的结论是现有证据不足以判断利弊（I 级）。妊娠期糖尿病不管会推高巨大儿、难产、剖宫产、子痫前期和新生儿低血糖的风险","grade":"A","src":"US Preventive Services Task Force (2021). Gestational Diabetes: Screening. <https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/gestational-diabetes-screening>","note":"查出来大多数靠饮食和运动就能控住，需要用胰岛素的是少数。别因为怕查出来要打针就跳过这一次。产后还要复查血糖，得过妊娠期糖尿病的人以后得 2 型糖尿病的风险明显更高","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"27.7","sec":27,"n":7,"title":"背下这张「立刻去医院」的清单，孕期和产后一年内都算数","cost":"0 元；花五分钟记住，最好也让同住的人知道","human":"清单上的任何一条出现，当天就去医院，不要在家等一晚。生完了也别松劲，产后一年内出现同样算数。","gain":"美国疾病控制与预防中心列出的孕产期紧急预警信号：持续不缓解或越来越重的头痛；头晕或昏厥；视觉改变；体温达到 38 ℃ 或更高；手或脸严重肿胀；有伤害自己或伤害孩子的念头；呼吸困难；胸痛或心跳过快；严重恶心呕吐；持续不缓解的剧烈腹痛；孕期胎动停止或明显减少；孕期阴道出血或流液；产后阴道出血或异常分泌物；一侧手臂或腿严重肿胀、发红或疼痛。这些问题可以发生在产后一年内，不是「出了月子就没事」","grade":"A","src":"Centers for Disease Control and Prevention. Hear Her — Urgent Maternal Warning Signs. <https://www.cdc.gov/hearher/maternal-warning-signs/index.html>；World Health Organization. Maternal mortality fact sheet. <https://www.who.int/news-room/fact-sheets/detail/maternal-mortality>","note":"这张清单的价值在于把「忍一忍」和「必须马上走」分开了。头痛加视物模糊加上腹痛，指向的是子痫前期；单侧小腿肿痛指向的是深静脉血栓（见第 13 节）；产后大出血按世界卫生组织的说法可以在几小时内夺走一个健康女性的生命。任何一条出现就直接去医院，不要先在家等一晚","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"27.8","sec":27,"n":8,"title":"破水了就地平躺、垫高臀部、打 120，不要走动也不要洗澡","cost":"0 元","human":"破水不是慢慢收拾再出发，是就地躺下、垫高屁股、打 120。站着走动羊水流得更快，脐带可能跟着被冲下来，那是能要孩子命的急症。","gain":"北京市卫生健康委员会的处置口径：发现破水后「马上找个地方平躺下来，防止羊水流出来」「不要随意走动」，「立即拨打 120 急救电话」，等车期间通知家人带东西到医院会合。医疗机构的科普进一步说明为什么：站立位时羊水流失更快，胎儿的脐带可能随之脱出造成脐带脱垂，这是危及胎儿的急症，所以要卧床并把臀部垫高，可取左侧卧位","grade":"B","src":"北京市卫生健康委员会. 每周急救话题：准妈妈羊水早破怎样办？ <https://wjw.beijing.gov.cn/bmfw_20143/jkzs/jzjj/202001/t20200115_1575632.html>；北京市顺义区妇幼保健院. 孕晚期在家破水怎么办？ <https://www.bch-syfy.cn/Html/News/Articles/9453.html>","note":"三个临产征兆里，规律宫缩和见红可以从容准备，破水是唯一一个「当场躺下叫车」的。破水后洗澡、蹲厕所、自己开车都属于典型错误。记下破水的时间和羊水颜色告诉医生——羊水呈黄绿色或带胎粪颗粒提示胎儿窘迫。伴随规律宫缩、胎动明显减少、发热寒战的，更要强调是急诊","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"27.9","sec":27,"n":9,"title":"想要无痛分娩就直接说，它不增加剖宫产的风险","cost":"几百到一千多元，各地价格不同；需要提前和医院、麻醉科确认能不能做","human":"无痛比别的镇痛办法更管用，而且不会让你更可能挨一刀，「打了无痛腰疼一辈子」同样没有依据。现在它有了单独的收费项目，医院也更愿意做。","gain":"Cochrane 系统综述的结论是，硬膜外镇痛在减轻产痛和提高产妇对镇痛的满意度上比非硬膜外方法更有效，且「硬膜外镇痛对剖宫产风险和长期腰痛没有影响」；器械助产增加的现象在 2005 年以后的研究中已经看不到。2024 年起，国家医保局的产科类医疗服务价格项目立项指南把「分娩镇痛」「导乐分娩」「亲情陪产」单独立项，理由正是原先没有独立价格项目、医院提供分娩镇痛的积极性被压低","grade":"A","src":"Anim-Somuah M, Smyth RMD, Cyna AM, Cuthbert A (2018). Epidural versus non-epidural or no analgesia for pain management in labour. Cochrane Database of Systematic Reviews, (5), CD000331. <https://doi.org/10.1002/14651858.CD000331.pub4>；国家医疗保障局 (2024). 重构产科服务价格项目 助力构建生育友好型社会. <https://www.gov.cn/zhengce/202406/content_6957553.htm>","note":"「打无痛会腰疼一辈子」和「打无痛会难产要挨刀」这两条流传最广的说法，在上述综述里都没有支持。真实的副作用是低血压、发热、下肢无力、尿潴留，以及第一、第二产程变长、更可能用缩宫素。做不做由自己定，但别因为传言放弃。能不能做还取决于医院有没有 24 小时在场的麻醉医生，产检时就问清楚","money":"少","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"27.10","sec":27,"n":10,"title":"没有医学指征就别主动要求剖宫产，也别为了挑日子开刀","cost":"0 元；难在顶住家里人的说法","human":"从整个人群看，剖宫产比例超过一成以后，母亲和新生儿的死亡就不再继续下降。该剖的一定要剖，为挑日子、怕疼去剖，只是白挨一次腹部大手术，世卫组织的说法是人群剖宫产率超过 10% 之后，没有证据显示死亡还能再降。","gain":"世界卫生组织 2015 年的声明：人群层面剖宫产率上升到约 10% 时，孕产妇和新生儿死亡数下降；超过 10% 之后，没有证据显示死亡率进一步改善。世界卫生组织同时强调，应当尽一切努力为有需要的产妇提供剖宫产，而不是为了达到某个特定比率","grade":"A","src":"World Health Organization (2015). WHO Statement on Caesarean Section Rates（WHO/RHR/15.02）. <https://www.who.int/publications/i/item/WHO-RHR-15.02>","note":"这条不是反对剖宫产——有指征时剖宫产是救命手术，该做就做，别硬扛。反对的是非医学指征剖宫产：怕疼、挑吉时、算学龄。代价记在后面：剖宫产是腹部大手术，恢复更慢，再次妊娠时的前置胎盘、胎盘植入和子宫破裂风险更高，直接影响你还想不想生第二个","money":"0","time":"少","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"27.11","sec":27,"n":11,"title":"怀孕前就确认生育保险的参保状态，未就业的配偶也能报生育医疗费用","cost":"0 元；打一次社保或医保咨询电话","human":"单位交了生育保险，生孩子的医疗费和产假期间的津贴都从基金出；配偶没工作的，医疗费这一块也能报。参保月数够不够、异地生产要不要备案，得提前问，事后补不了。","gain":"《社会保险法》第五十四条：用人单位已经缴纳生育保险费的，其职工享受生育保险待遇；职工未就业配偶按照国家规定享受生育医疗费用待遇，所需资金从生育保险基金中支付。生育保险待遇包括生育医疗费用和生育津贴两块。第五十六条列明享受生育津贴的三种情形（女职工生育享受产假、享受计划生育手术休假、法律法规规定的其他情形），生育津贴「按照职工所在用人单位上年度职工月平均工资计发」","grade":"A","src":"全国人大常委会 (2010). 中华人民共和国社会保险法（第五十四、五十六条）. <https://guangdong.chinatax.gov.cn/gdsw/qysw_gkwj/2020-02/12/content_8e8c485d0db34b989531f3ba57cec5a9.shtml>（国家税务总局广东省税务局转载）","note":"两件事要提前问清楚，因为事后补不了：一是连续参保月数够不够当地的享受门槛，二是不在参保地生产的要不要先做异地生育备案，没备案的可能只能自己先垫付、回来手工报销甚至报不了。产假天数和生育津贴怎么算见第 18 节第 2 条","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"27.12","sec":27,"n":12,"title":"出院前把《出生医学证明》办掉，名字提前想好、别写错字","cost":"0 元；出院手续里顺手办完","human":"这张证是上户口、参保、上学的前置件，而且只有接生的机构能首次开。出了院再回头补，要另走一套流程、多交材料。名字里的字先确认户籍系统打得出来。","gain":"《母婴保健法》第二十三条：医疗保健机构和从事家庭接生的人员按照国务院卫生行政部门的规定，出具统一制发的新生儿出生医学证明。这张证是后面所有事的前置条件——上户口、参保、办医保卡、入园入学都要它，而且首次签发只能由接生的机构办，出了院再回头补办要走另一套流程、需要额外的证明材料","grade":"A","src":"全国人大常委会 (1994, 2017 修正). 中华人民共和国母婴保健法（第二十三条）. <https://www.gov.cn/guoqing/2021-10/29/content_5647619.htm>","note":"填之前把父母姓名、身份证号和孩子姓名逐字核对一遍。姓名用字要能在户籍系统里打得出来，生僻字后患无穷；改名和改证都要走补发或换发，比当场核对贵得多。证拿到手就单独收好，它和户口本、身份证同一个等级","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"27.13","sec":27,"n":13,"title":"新生儿足跟血筛查和听力筛查都别拒绝","cost":"多数地区免费或几十元，部分扩展项目自费；出生后扎一次足跟","human":"扎一次足跟血、做一次听力测试，能在孩子看起来完全正常的时候查出甲减、苯丙酮尿症和听力障碍。等症状显出来，智力损害已经补不回来。","gain":"《新生儿疾病筛查管理办法》第三条：「全国新生儿疾病筛查病种包括先天性甲状腺功能减低症、苯丙酮尿症等新生儿遗传代谢病和听力障碍。」这两类病的共同点是早期完全看不出异常，等到症状明显时智力损害已经不可逆，而早发现早干预（补充甲状腺素、特殊配方奶、助听或人工耳蜗）效果很好。第十条规定筛查阳性时机构应当及时通知监护人去确诊","grade":"A","src":"卫生部 (2009). 新生儿疾病筛查管理办法（卫生部令第 64 号，第三、十、十一条）. <http://www.gov.cn/gongbao/content/2009/content_1371363.htm>","note":"办法第十一条要求筛查前把项目、条件、方式、灵敏度和费用如实告知监护人并取得签字同意，所以你会拿到一张知情同意书——签之前看清楚哪些是国家病种、哪些是自费加项。初筛阳性不等于确诊，绝大多数复查就排除了，别在这一步先崩溃。听力初筛没过的要按通知去复筛，别自己判断「孩子听得见就算了」","money":"少","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"27.14","sec":27,"n":14,"title":"拿到出生医学证明就给孩子办居民医保，别等落完户","cost":"一年一档的居民医保保费，几百元","human":"拿到出生证就能在线给孩子参保，不用等落户。参上了，出院时的住院费当场就能报——新生儿住院费用不低，参保和没参保差别很大。","gain":"中国政府网 2024 年的口径：「新生儿凭出生医学证明就可以在线上参保」，不必先落户；「新生儿出院以后就能够直接报销医药费用」。此前的做法是落户才参保，住院费得先全额垫付再回头报销；参保缴费的平均办理时长也从年初的 28.7 个工作日压减到 6.4 个工作日","grade":"A","src":"中国政府网 (2024). 健全基本医疗保险参保长效机制国务院政策例行吹风会. <https://www.gov.cn/zhengce/202409/content_6973567.htm>","note":"早产、黄疸蓝光、新生儿肺炎这些是新生儿住院的常见原因，动辄上万元，参保和不参保差别很大。各地对「出生后多少天内参保可以从出生之日起享受待遇」的规定不完全一样，落地细则以当地医保部门为准，出院前打 12393 问一句最省事","money":"少","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"27.15","sec":27,"n":15,"title":"孩子出生后一个月以内去派出所申报出生登记","cost":"0 元；跑一趟户籍窗口","human":"法律给的是一个月，不是「有空再说」。落户卡着后面的接种、入园、入学和办身份证，越拖要补的材料越多。","gain":"《户口登记条例》第七条：「婴儿出生后一个月以内，由户主、亲属、抚养人或者邻居向婴儿常住地户口登记机关申报出生登记。」这是法定时限，不是建议。落户是后面接种、入园、入学、办身份证的前置条件，越拖需要补的材料越多","grade":"A","src":"国务院 (1958). 中华人民共和国户口登记条例（第七条）. <http://www.gd.gov.cn/zwgk/wjk/zcfgk/content/post_2531969.html>（广东省人民政府转载）","note":"带齐出生医学证明、父母双方身份证和户口本、结婚证。随父随母落户可以选，但两地政策不同（学区、参保地都受影响），去之前想清楚，改起来麻烦。非婚生育同样可以申报出生登记","money":"0","time":"少","will":"否","level":"小","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"27.16","sec":27,"n":16,"title":"产后 42 天那次复查别跳过，它同时是产后抑郁的筛查","cost":"0 元，属于基本公共卫生服务；半天时间","human":"这次复查免费，这次检查含血常规、白带常规，还包含一次产后抑郁筛查。产后一年内都可能出大问题，别觉得出了月子就安全。","gain":"《国家基本公共卫生服务规范（第三版）》的孕产妇健康管理里，产后有 1 次产后访视和 1 次产后 42 天健康检查；地方公开的服务清单里，这一次含化验（血常规、白带常规）和 1 次产后抑郁筛查。产后一年内都可能出现严重并发症——第 7 条那张清单里的「有伤害自己或伤害孩子的念头」「产后阴道出血或异常分泌物」「一侧肢体严重肿痛」都属于产后","grade":"A","src":"国家卫生计生委 (2017). 国家基本公共卫生服务规范（第三版）. <https://www.nhc.gov.cn/ewebeditor/uploadfile/2017/04/20170417104506514.pdf>；靖江市人民政府. 国家基本公共卫生服务项目——孕产妇健康管理服务（地方服务清单公开）. <https://www.jingjiang.gov.cn/xxgk/zdlyxxgk/wsjk/art/2023/art_383017a2e7794892bc772bfbe042f379.html>","note":"产后抑郁不是矫情，也不是靠家人说想开点能解决的，它有筛查量表、有治疗、可以恢复。有自杀念头时的处置见第 1 节，孩子生下来确实养不了时的合法出路见第 9 节第 20 条。这次复查还会看伤口愈合、子宫复旧和盆底功能，避孕方案也在这次谈——产后不来月经不等于不会怀孕","money":"0","time":"少","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"}]},{"n":28,"title":"别为了外形把身体搞坏","intro":"本节收的是「为了改变外形而对身体动手」的做法：饿、吃药、打针、开刀。共同点是决定多半来自和别人比较，代价却全落在自己身上，而且相当一部分不可逆。\n本节不评价任何人想把自己变成什么样子——那是各人自己的事。它只回答一个问题：同一个目标，走「有处方、有资质、有复查」的路，和走「网购、美容院、自己加量」的路，风险差多少。口径以健康终点为主，医美那两条同时涉及非法行医的刑事责任。","entries":[{"id":"28.1","sec":28,"n":1,"title":"不要用极端节食、断食或催吐来控制体重，要减就从运动那一侧减","cost":"0，反过来还省下减肥产品的钱","human":"神经性厌食的人，死亡概率是同龄人的近 6 倍，每一千人每年死 5.1 个，死的人里每五个有一个是自杀。而它的入口就是节食：跟踪 44 所中学的学生三年，严重节食的女生出现进食障碍的概率是不节食的 18 倍，中度节食是 5 倍；把既往节食和精神状态一起算进去之后，体重和运动量就不再预测发病。想控制体重就多动，别少吃到饿。","gain":"36 项研究荟萃（神经性厌食累计观察 166,642 人年）：神经性厌食标准化死亡比 5.86，每 1000 人年死亡 5.1 例，死亡者中约 1/5 死于自杀；贪食症标准化死亡比 1.93，其他进食障碍 1.92。澳大利亚维多利亚州 44 所中学 14–15 岁学生 3 年 6 波队列：女生新发进食障碍 21.8/1000 人年，严重节食者发病风险为不节食者的 18 倍，中度节食者为 5 倍；校正既往节食与精神症状后，BMI、运动量和性别都不再预测新发进食障碍，作者结论是「在青少年中用运动而非限食控制体重，发生进食障碍的风险似乎更低」","grade":"A","src":"Arcelus J et al. (2011). Mortality rates in patients with anorexia nervosa and other eating disorders. A meta-analysis of 36 studies. Arch Gen Psychiatry. <https://doi.org/10.1001/archgenpsychiatry.2011.74>；Patton GC et al. (1999). Onset of adolescent eating disorders: population based cohort study over 3 years. BMJ. <https://doi.org/10.1136/bmj.318.7186.765>","note":"这里的「严重节食」指的是长期把进食压到远低于需要，不是指少吃一顿或不吃夜宵。已经出现催吐、暴食后自责、反复称重停不下来的，去精神科或综合医院的临床心理科，这是有规范治疗的病，不是意志力问题。BMI 与死亡率的关系见第 2 节第 28 条，那条讲的是长期体重区间，不是减重手段。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"28.2","sec":28,"n":2,"title":"打针、埋线、开刀之前查两样：机构许可证上有没有「医疗美容」，动手的人是不是主诊医师","cost":"0，查两张证几分钟；机构该把《医疗机构执业许可证》挂在大厅，医师资质可在卫健部门的执业医师查询里核","human":"只要是手术、打针、用医疗器械这类会破皮或者进到身体里的，都算医疗行为，只能在拿到《医疗机构执业许可证》、并且许可证上核准了「医疗美容」科目的机构做。动手的医生要有执业医师资格并注册，做美容外科的还得有 6 年以上整形或美容外科的临床经历。美容院、工作室、酒店房间里做这些是非法行医：情节严重的判 3 年以下，把人弄伤的 3 到 10 年，弄死的 10 年以上。做之前医生必须书面告诉你适应症、禁忌症和风险并让你签字，跳过这一步就说明流程本身不对。","gain":"《医疗美容服务管理办法》第二条把医疗美容定义为「运用手术、药物、医疗器械以及其他具有创伤性或者侵入性的医学技术方法对人的容貌和人体各部位形态进行的修复与再塑」；第八条、第二十四条要求先取得《医疗机构执业许可证》并经登记机关核准医疗美容诊疗科目才能开展；第十一条要求主诊医师具有执业医师资格并注册，美容外科需 6 年以上、美容牙科 5 年以上、美容中医科与美容皮肤科各 3 年以上相关专业临床工作经历；第二十条要求实施前书面告知适应症、禁忌症、医疗风险和注意事项并取得签字同意。《刑法》第三百三十六条：未取得医生执业资格的人非法行医，情节严重的处 3 年以下有期徒刑、拘役或者管制，并处或者单处罚金；严重损害就诊人身体健康的处 3 年以上 10 年以下有期徒刑并处罚金；造成就诊人死亡的处 10 年以上有期徒刑并处罚金","grade":"A","src":"卫生部 (2002). 医疗美容服务管理办法（卫生部令第 19 号，第二条、第八条、第十一条、第十六条、第二十条、第二十四条）. <http://www.gov.cn/gongbao/content/2003/content_62198.htm>；全国人大 (1997). 刑法（第三百三十六条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>","note":"同一条办法第十六条还要求医疗美容项目必须在美容医疗机构或设有医疗美容科室的医疗机构里做，所以「上门服务」「工作室私密操作」本身就不合规。第二十条那句写明「未经监护人同意，不得为无行为能力或者限制行为能力人实施医疗美容项目」，未成年人做医美要监护人签字。生活美容（做脸、按摩、美甲）不在这个范围内，但一旦动到针和刀就是医疗美容。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"28.3","sec":28,"n":3,"title":"面部填充避开鼻背、眉间、额头这几个部位，更别为省钱找非正规注射","cost":"0，只是换个部位或者不做","human":"48 例注射后失明里，涉及鼻部的占 56.3%、眉间 27.1%、前额 18.8%。2015 到 2018 年新报的 48 例注射后失明中，鼻部占 56.3%，眉间 27.1%，额头 18.8%，鼻唇沟 14.6%，八成以上打的是玻尿酸。这些人里只有 20.8% 视力完全恢复，16.7% 部分恢复，剩下的没恢复；将近两成还出现了脑部并发症。目前没有一种抢救办法被证明稳定有效，所以这件事只能靠事前避开。","gain":"世界文献回顾（2015 年 1 月—2018 年 9 月新增 48 例注射填充后部分或完全视力丧失）：最高风险部位为鼻部 56.3%、眉间 27.1%、前额 18.8%、鼻唇沟 14.6%；81.3% 的病例填充物为透明质酸；43.8% 出现皮肤改变，18.8% 出现中枢神经系统并发症；10 例（20.8%）视力完全恢复，8 例（16.7%）部分恢复；作者结论为处理方式差异极大，没有一种治疗被证明能持续奏效","grade":"B","src":"Beleznay K et al. (2019). Update on Avoiding and Treating Blindness From Fillers: A Recent Review of the World Literature. Aesthet Surg J. <https://doi.org/10.1093/asj/sjz053>","note":"这是文献里报告过的病例汇总，没有分母，算不出「打一次的失明概率」，只能读出「哪些部位出事最多、事后基本救不回来」。它是 B 级的原因也在这里。降低风险的做法在正规机构本来就是常规：术前评估血管走行、用钝针、边退边小量注射、随时准备透明质酸酶——这些都要求操作者是受过训练的医生，也是不去非正规渠道的理由。做之前先按本节第 2 条查证。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"28.4","sec":28,"n":4,"title":"不要买承诺「快速瘦」的减肥药、减肥咖啡、瘦身糖果和酵素梅","cost":"0，反过来省下这笔钱","human":"这类产品里最常查出的违法添加成分是西布曲明。它原来是正经减肥药，2010 年在中国被停掉了：一项近万人、平均吃三年多的试验里，吃药的人非致死性心梗高约三成，非致死性中风高约三成六，出事比例 11.4% 对 10.0%，而三年多只多减了 1.7 公斤。往食品和保健食品里加它是违法的，抽检查到就严处，涉嫌犯罪的移送公安——但那是事后的事，你已经吃下去了。","gain":"SCOUT 试验（9,804 名 55 岁以上超重或肥胖、且有心血管病或 2 型糖尿病者随机分组，平均治疗 3.4 年）：主要终点（非致死性心梗、非致死性卒中、心脏骤停后复苏、心血管死亡）发生率 11.4% vs 10.0%，HR 1.16（95% CI 1.03–1.31，P=0.02）；非致死性心梗 4.1% vs 3.2%，HR 1.28（1.04–1.57）；非致死性卒中 2.6% vs 1.9%，HR 1.36（1.04–1.77）；心血管死亡与全因死亡未增加；随机化后西布曲明组平均多减重 1.7 kg。原国家食品药品监督管理局据安全性评估认为「减肥治疗的风险大于效益」，2010 年 10 月通知停止西布曲明制剂及原料药的生产、销售、使用；西布曲明与酚酞均禁止添加于食品（含保健食品）","grade":"A","src":"James WPT et al. (2010). Effect of sibutramine on cardiovascular outcomes in overweight and obese subjects. NEJM. <https://doi.org/10.1056/NEJMoa1003114>；天津市市场监督管理委员会. 警惕部分食品中违法添加「盐酸西布曲明」和「酚酞」. <https://scjg.tj.gov.cn/tjsscjdglwyh_52651/hdpt/cjwtyxfts/202007/t20200720_2972549.html>","note":"SCOUT 入组的是已有心血管病或糖尿病的高危人群，试验没有证明健康年轻人吃它同样出事；但正因为风险人群识别不了，监管才直接撤市。另一个常见的违法添加成分是酚酞（泻药），长期过量可造成电解质紊乱、诱发心律失常。判断方法很简单：正经减肥药是处方药，在药店和医院有批准文号可查；用「咖啡」「糖果」「梅子」「代餐」名义卖、承诺一周几斤的，按定义就不该有药效，有药效就是加了东西。国食药监办〔2010〕432 号原文在国家药监局网站，本机访问恒返回 412，故引省级监管部门的转述页，其中「风险大于效益」「2010 年 10 月停止生产销售使用」两处可逐字核对。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"28.5","sec":28,"n":5,"title":"不要用合成代谢类固醇（「增肌针」「口服药」）来长肌肉","cost":"0，省下药钱；代价是接受肌肉长得慢","human":"丹麦按健身房兴奋剂检测阳性追踪了 545 个用药的人，和 5450 个同龄人比，死亡风险是对照组的 3 倍，每年跑医院的次数中位数 0.81 次对 0.36 次；痤疮、男性乳房发育、勃起功能障碍各有超过一成的人中招，用另一批人复核结果一样。这类药在中国是处方药，同时列在兴奋剂目录里，任何单位和个人非法生产、销售、进出口都是违法的——所以能卖给你的渠道，本身就在违法，药是不是真的也没人保证。","gain":"丹麦回顾性配对队列（2006-01-03 至 2018-03-01 健身房兴奋剂检测雄激素类固醇阳性的 545 名男性，配 5,450 名对照；另以 644 名拒检者与 6,440 名对照复核）：使用者死亡率为对照的 3 倍，HR 3.0（95% CI 1.3–7.0）；每年住院/就诊次数中位数 0.81 次 vs 0.36 次（P<0.0001）；痤疮、男性乳房发育、勃起功能障碍各影响超过 10% 的使用者，均显著高于对照（P<0.0001）；复核队列结果一致。《反兴奋剂条例》第七条：国家对兴奋剂目录所列禁用物质实行严格管理，任何单位和个人不得非法生产、销售、进出口；同条例规定蛋白同化制剂、肽类激素实行处方药管理","grade":"A","src":"Horwitz H et al. (2019). Health consequences of androgenic anabolic steroid use. J Intern Med. <https://doi.org/10.1111/joim.12850>；国务院 (2004). 反兴奋剂条例（国务院令第 398 号，第七条、第九条）. <http://www.gov.cn/gongbao/content/2004/content_63129.htm>","note":"争议：这是观察性队列，用药的人本身可能在其他方面也更冒险，3 倍这个数不能全算到药头上；置信区间 1.3–7.0 也很宽。但「痤疮、男性乳房发育、勃起功能障碍在一成以上」是直接可观察的副作用，和选择偏倚关系较小。「蛋白同化制剂」是法规里对这类药的叫法。普通蛋白粉、肌酸不在本条范围内，问题出在「宣称增肌效果特别快」的产品可能非法添加，判断方法同第 4 条。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":true,"todo":false,"ratio":"高"},{"id":"28.6","sec":28,"n":6,"title":"要吃减肥药就去医院拿处方，别在不用处方就发货的网店买","cost":"一次挂号加往返，几十元、半天","human":"处方药按规定必须凭处方卖，药店还要把处方留满五年；在网上卖处方药，也必须有真实可靠的处方并且实名，页面上得写明「处方药须凭处方在药师指导下购买和使用」。所以看到不问诊、不要处方、下单就发的，只有两种可能：卖的不是它说的那个药，或者这家店本身在违规——两种情况下，出了事都没人替你的剂量和禁忌负责。挂号那几十块钱买的就是这个。","gain":"《药品经营和使用质量监督管理办法》规定药品零售企业应当遵守处方药与非处方药分类管理制度，按规定凭处方销售处方药，处方保留不少于五年；药师或其他药学技术人员不在岗时应挂牌告知，未经其审核不得销售处方药；处方药不得开架销售。《药品网络销售监督管理办法》第九条规定通过网络向个人销售处方药的应当确保处方来源真实、可靠并实行实名制；第十条要求在每个药品展示页面下突出显示风险警示信息，且通过处方审核前不得展示说明书、不得提供购买服务；第八条规定疫苗、血液制品、麻醉药品、精神药品、医疗用毒性药品、放射性药品、药品类易制毒化学品等国家实行特殊管理的药品不得在网络上销售","grade":"B","src":"国家市场监督管理总局 (2023). 药品经营和使用质量监督管理办法（总局令第 84 号）. <https://www.gov.cn/gongbao/2023/issue_10846/202311/content_6917322.html>；国家市场监督管理总局 (2022). 药品网络销售监督管理办法（总局令第 58 号，第八条至第十条）. <https://www.gov.cn/gongbao/content/2022/content_5717002.htm>","note":"法条本身可逐字核对，但「按处方吃比自己买着吃能少出多少事」没有量化研究，所以按「难以量化」记 B。这条不只管减肥药：本节第 5、7 条说的类固醇和性激素，走的是同一套规则。真有减重指征的，医生会先看 BMI、合并症和禁忌症再决定用不用药、用哪种，这个判断是买不到的。","money":"少","time":"中","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"28.7","sec":28,"n":7,"title":"性激素类药只在医生开方并定期复查的前提下用，不要网购、不要自己加量","cost":"定期挂号和抽血复查，一年几百元、几个半天","human":"这条不讨论该不该用，只讨论怎么用。在一项跨性别人群、平均随访约四年的研究里，跨性别女性（绝大多数在用雌激素）的静脉血栓比同龄对照明显多：两年里每一千人多出 4.1 例，八年多出 16.7 例；随访期间才开始用药的那部分人，血栓和缺血性中风的差距更明显；心梗总体没看出差别。关键在于，这类风险要靠长期随访盯着，前提是有人在定期给你查——网购加自己调量的路径上，恰恰没有这个人。","gain":"Kaiser Permanente 电子病历队列（2,842 名跨性别女性、2,118 名跨性别男性，平均随访 4.0 与 3.6 年，各按出生年、种族、站点和入组时间匹配约 10 倍顺性别对照，共 48,686 名顺性别男性与 48,775 名顺性别女性）：跨性别女性静脉血栓栓塞的 2 年与 8 年风险差，相对顺性别男性为每 1000 人 4.1（95% CI 1.6–6.7）与 16.7（6.4–27.5），相对顺性别女性为 3.4（1.1–5.6）与 13.7（4.1–22.7）；缺血性卒中与心肌梗死总体各组接近，但在随访期内开始激素治疗的跨性别女性中，静脉血栓与缺血性卒中的差异更明显；跨性别男性的证据不足以下结论。作者结论为「这些结果可能提示需要长期警惕跨性别激素中雌激素的血管副作用」","grade":"A","src":"Getahun D et al. (2018). Cross-sex Hormones and Acute Cardiovascular Events in Transgender Persons: A Cohort Study. Ann Intern Med. <https://doi.org/10.7326/M17-2785>；国家市场监督管理总局 (2022). 药品网络销售监督管理办法（总局令第 58 号，第九条）. <https://www.gov.cn/gongbao/content/2022/content_5717002.htm>","note":"这项研究自己写明了局限：无法知道有多少人在系统外拿药，所以「用药与否」的划分本来就不干净——而这恰好说明为什么要把用药纳入正规随访。它测的是血管事件，不评价激素治疗本身的适应症和获益，那是另一套证据。同样的道理适用于所有性激素用途：避孕药、更年期激素治疗、睾酮补充，凡是自己网购、参照网帖调量、不查血栓和肝肾指标的，风险都出在「没人监测」这一段，而不是出在用药动机上。国内规范路径是去正规医疗机构的内分泌科或相应专科评估、开方、随访。","money":"少","time":"中","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"28.8","sec":28,"n":8,"title":"如果「觉得自己丑」已经到反复照镜子、反复想改的程度，先做一次体像评估再谈手术","cost":"一次精神科或临床心理科挂号，几十元","human":"把 33 项研究合起来看，去做整形手术的人里有 15.04% 符合躯体变形障碍——就是把一个别人基本看不出来的缺陷放大到影响生活；皮肤科求美的人里是 12.65%，两边都是七成多为女性。这类困扰的落点不在脸上，手术改的是脸，不改那个「反复检查、反复不满意」的循环，就容易一台接一台做下去。先花一次挂号的钱确认自己属不属于这一类，再决定要不要动。","gain":"33 项研究系统综述与荟萃分析：整形外科就诊者中躯体变形障碍患病率 15.04%（各研究 2.21%–56.67%），平均年龄 34.54±12.41 岁，74.38% 为女性；皮肤科就诊者 12.65%（4.52%–35.16%），平均年龄 27.79±9.03 岁，76.09% 为女性；作者建议整形外科医师与皮肤科医师主动评估、识别高风险者并安排多学科处理","grade":"B","src":"Ribeiro RVE (2017). Prevalence of Body Dysmorphic Disorder in Plastic Surgery and Dermatology Patients: A Systematic Review with Meta-Analysis. Aesthetic Plast Surg. <https://doi.org/10.1007/s00266-017-0869-0>","note":"各研究结果从 2.21% 到 56.67%，跨度极大，筛查工具和人群都不统一，所以只能读出「这个比例不低、值得先筛一次」，不能拿 15.04% 当准确值，这也是记 B 的原因。本条不是说想做医美的人有心理问题，绝大多数不是；它说的是「反复、持续、已经影响到工作和社交」这一小部分人，手术解决不了他们的问题。判断线索：一天里花很长时间检查或遮挡某个部位、因此回避社交或拍照、做完一处又盯上下一处。","money":"少","time":"中","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"}]},{"n":29,"title":"遭遇重大打击之后","intro":"亲人去世、被告知重病、失业、离婚——这几件事在研究里有个共同点：出事的不只是心情，还有身体，而且高发期集中在头几周到头一年。这一节不讲怎么「走出来」，只讲这段时间里哪些事必须有人盯住、哪些决定必须往后放、什么时候该去挂号。多数条目口径是死亡率，谈花钱和待遇的第 9、11、12、13 条口径是钱，两类数字不互相换算。没有亲人也没有朋友可找的，「找个人盯住」这句话怎么落地见第 6 条。\n亲人去世当时的手续、遗体和该取的钱见第 25 节，老人生前的监护与遗嘱见第 17 节，失业能领什么见第 7 节，情绪低落时的运动与光照见第 3 节和第 22 节，有自杀念头时先打 12356 见第 1 节第 25 条、念头的时间尺度见第 1 节第 30 条、救回来之后的后遗症见第 1 节第 31 条，本节不重复。","entries":[{"id":"29.1","sec":29,"n":1,"title":"亲人刚走的那几天别一个人待着，有心脏病、高血压、糖尿病的照常吃药，胸口压着疼就叫 120","cost":"0，只是别独处、别停药","human":"亲人去世后 24 小时内，心梗发作的概率是平时的 21.1 倍，之后逐天下降。60 到 89 岁的人在伴侣去世后 30 天内发生心梗或中风的比例是 0.16%，没丧偶的同龄人是 0.08%，大约翻倍，一个月后回落。绝对数不算大：本来十年心梗风险 5% 的人，大约每 1394 个丧亲者多出 1 例；本来风险 20% 的，每 320 个多出 1 例——所以这条主要是说给本来就有心血管病的人听的。这几天别停药，胸口压着疼、喘不上气、一侧手脚没力，立刻打 120。","gain":"1985 名急性心梗患者的病例交叉分析：270 人（13.6%）在发病前 6 个月内失去过重要的人，其中 19 人在心梗前 1 天内；重要的人去世后 24 小时内急性心梗发作率升高 21.1 倍（95% CI 13.1–34.1），此后逐日下降；绝对风险为十年心梗风险 5% 者每 1394 名暴露者多 1 例、20% 者每 320 名多 1 例。英国 30447 名 60 至 89 岁丧偶者与 83588 名匹配对照：丧偶后 30 天内发生心梗或中风者 50 人（0.16%）对 67 人（0.08%），IRR 2.20（1.52–3.15），其中心梗 2.14（1.20–3.81）、中风 2.40（1.22–4.71），30 天后减弱；90 天内非心梗急性冠脉综合征 IRR 2.20（1.12–4.29）、肺栓塞 2.37（1.18–4.75）","grade":"A","src":"Mostofsky E, et al. (2012). Risk of acute myocardial infarction after the death of a significant person in one's life: the Determinants of Myocardial Infarction Onset Study. Circulation. <https://doi.org/10.1161/CIRCULATIONAHA.111.061770>；Carey IM, et al. (2014). Increased risk of acute cardiovascular events after partner bereavement: a matched cohort study. JAMA Internal Medicine. <https://doi.org/10.1001/jamainternmed.2013.14558>","note":"两项都是观察性研究，去不掉「本来就要发病」的成分，但方向一致、窗口一致。可做的事很具体：药盒交给别人管，别靠自己记；这几天别开长途；别用酒顶着（酒的账见第 2 节）。心梗、中风的识别和叫车方式见第 13 节。没有人可以把药盒交出去、这几天注定一个人在屋里的，见本节第 6 条。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"29.2","sec":29,"n":2,"title":"被告知重病诊断的那一周，别一个人去拿报告，治疗以外的决定往后放","cost":"0，找个人陪着去，把大决定推后几天","human":"拿到癌症诊断的第一周，自杀的概率是没确诊的人的 12.6 倍，死于心血管病的概率是 5.6 倍；到第一年分别降到 3.1 倍和（前四周）3.3 倍，预后越差的癌种越明显。这不是「心理素质」的问题，风险最高的就是刚知道的那几天，之后迅速回落。所以：拿报告那天带个人一起去，回家别一个人待着，胸痛、喘不上气立刻打 120；治疗方案、要不要辞职、要不要卖房，都留到下一次门诊之后再说。","gain":"瑞典 6,073,240 人 1991 至 2006 年的历史队列：与未确诊癌症者相比，确诊后第一周自杀相对风险 12.6（95% CI 8.6–17.8，发病率 2.50/1000 人年），第一年 3.1（2.7–3.5，0.60/1000 人年）；心血管死亡第一周 5.6（5.2–5.9，116.80/1000 人年），前 4 周 3.3（3.1–3.4，65.81/1000 人年）；风险升高在确诊后第一年内迅速回落，预后差的癌种升高最明显；同一批患者的自身对照分析结论一致","grade":"A","src":"Fang F, et al. (2012). Suicide and cardiovascular death after a cancer diagnosis. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1110307>","note":"这是癌症的数据，往其他重大诊断上外推没有同等强度的原文。绝对数很小（第一周自杀率 2.50/1000 人年），列出来不是吓人，是说明「刚知道的那几天」需要有人在旁边。确诊后的长期管理、报销和复查见第 16 节和第 24 节；找不到人陪着去的见本节第 6 条（把「那个人」换成邻居和社区名单）。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"29.3","sec":29,"n":3,"title":"失业之后先把作息、医保和找工作的节奏固定下来，别整天待在家里","cost":"0，先办失业登记领失业金，把找工作排成固定日程","human":"失业的人在随后的年份里死亡的概率比在职的人高约六成，男性、处在职业生涯早期和中期的人更明显，失业后头十年最高。把吸烟饮酒这类健康行为也算进去的那批研究，得出的风险比其他研究低约四分之一——也就是说，有一部分是自己能按住的。事情的顺序是：先办失业登记、领失业保险金（领的期间职工医保由失业保险代缴，见第 7 节），别让医保断掉，再把起床时间、投简历和见人排成固定日程。","gain":"42 项研究、235 个死亡风险估计、逾 2000 万人的随机效应荟萃分析：调整年龄及其他协变量后，失业者全因死亡的平均 HR 为 1.63；男性高于女性；对处于职业生涯早期和中期者影响明显，晚期较小；随访前 10 年风险最高，之后下降；在控制了健康相关行为的那部分研究里，平均 HR 低 24%","grade":"A","src":"Roelfs DJ, et al. (2011). Losing life and livelihood: a systematic review and meta-analysis of unemployment and all-cause mortality. Social Science & Medicine. <https://doi.org/10.1016/j.socscimed.2011.01.005>","note":"观察性证据，反向因果去不掉——本来身体就差的人更容易失业。但「控制健康行为后效应低 24%」这一条给了可操作的方向。失业能领什么、去哪领、社保怎么续见第 7 节；被辞退该拿多少补偿、别签主动辞职见第 19 节。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"29.4","sec":29,"n":4,"title":"亲人死于自杀、意外或凶案的，别指望硬扛，主动去找专业帮助","cost":"0 起，打 12356 免费；挂心理门诊是普通门诊的钱","human":"配偶死于自杀的人，五年内被诊断出精神障碍的概率比一般人高约八成（男性）和七成（女性）；和配偶死于其他原因的人相比也高七成到一倍，自杀行为、死亡率、需要社会救助的比例都更高。因自杀失去亲人的人还更容易感到被人疏远和羞耻——这恰恰是要主动去找人的理由，别等「自己好起来」。","gain":"丹麦 670 万成年人 1980 至 2014 年、逾 1.36 亿人年的全国登记队列：因配偶自杀而丧偶者，5 年内新发精神障碍的 IRR 男性 1.8（95% CI 1.6–2.0）、女性 1.7（1.6–1.8）（对照一般人群）；与因其他死因丧偶者相比 IRR 男性 1.7（1.5–1.9）、女性 2.0（1.9–2.2），自杀行为、死亡率与需要市政救助的比例也更高，肝硬化、睡眠障碍等躯体疾病风险同样升高。57 项研究的系统性叙述综述：因自杀丧亲与伴侣自杀风险升高、子女自杀后父母精神科住院风险升高、成年子女自杀后母亲自杀风险升高、父母自杀后子女抑郁风险升高相关；与因其他暴力死亡丧亲的人相比，因自杀丧亲者更常报告被拒斥和羞耻感","grade":"A","src":"Erlangsen A, et al. (2017). Association Between Spousal Suicide and Mental, Physical, and Social Health Outcomes: A Longitudinal and Nationwide Register-Based Study. JAMA Psychiatry. <https://doi.org/10.1001/jamapsychiatry.2017.0226>；Pitman A, et al. (2014). Effects of suicide bereavement on mental health and suicide risk. The Lancet Psychiatry. <https://doi.org/10.1016/S2215-0366(14)70224-X>","note":"突然的、暴力性的死亡（事故、凶案、灾害）之后，创伤后应激障碍、抑郁和哀伤卡住的比例都比病亡后高，恢复也更慢（Kristensen P, et al. (2012). Bereavement and mental health after sudden and violent losses: a review. Psychiatry. <https://doi.org/10.1521/psyc.2012.75.1.76>）。自己有自杀念头时的处置见第 1 节第 25 条。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"29.5","sec":29,"n":5,"title":"丧偶后的头半年，把三餐、睡觉、慢性病的药和复查交给一个固定的人盯着","cost":"0，找一个具体的人（子女、兄弟姐妹、朋友）定期上门或打电话","human":"丧偶后不到半年，同期死亡的概率比没丧偶的人高约四成；半年以后降到高约一成半。男性高约两成三，女性那一档小到可能只是巧合。另一份合并了 5 亿多人的分析给出的整体数字是高约两成三，男性两成七、女性一成五。这个差不是靠「想开点」能扛过去的，该做的是把药、饭和复查落到一个具体的人身上，所以要落到一个具体的人身上，别指望自己记得住。","gain":"15 项前瞻队列、2,263,888 人的随机效应荟萃分析：丧偶不足 6 个月时死亡 RR 1.41（95% CI 1.26–1.57），6 个月以后 1.14（1.10–1.18）；男性 RR 1.23（1.18–1.28），女性 1.04（1.00–1.08，无统计学意义）；小于 65 岁与 65 岁以上无显著差异。另一项 123 篇文献、1377 个风险估计、逾 5 亿人的荟萃分析与元回归：调整后 HR 1.23（1.19–1.28），男性 1.27（1.19–1.35）高于女性 1.15（1.08–1.22）","grade":"A","src":"Moon JR, et al. (2011). Widowhood and mortality: a meta-analysis. PLoS ONE. <https://doi.org/10.1371/journal.pone.0023465>；Shor E, et al. (2012). Widowhood and mortality: a meta-analysis and meta-regression. Demography. <https://doi.org/10.1007/s13524-012-0096-x>","note":"观察性研究，混杂去不掉（夫妻的生活方式和疾病本来就相似）。但「头半年比之后高得多」这个时间形状在两份独立荟萃里一致，值得当成一个照看窗口。男性风险更高、也更少开口求助。家里有丧偶老人的，按第 17 节把账户、监护和遗嘱一并理清。没有这样一个人可找的（独居、失独、子女也不在了），把这件事交给社区和装置，见本节第 6 条。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"29.6","sec":29,"n":6,"title":"没有亲人也没有朋友的，把「那个人」换成三样东西：能进你家门的邻居、社区的探访名单、手机里的紧急联络","cost":"0，代价是要主动开口跟邻居和居委会说「我一个人住，家里刚出事」","human":"前面几条一直说「找个人」，但没有亲人、也没有朋友的时候这句话是空的。「有人陪」其实在办两件事，可以拆开分别换：一是万一出事有人发现你，二是有人盯着你吃药、吃饭、别喝酒。第二件本来就只能靠自己，办法是把药和三餐写成清单、上闹钟，别靠记性。第一件才是要找人替代的，三样东西够用：把备用钥匙或者门锁的临时密码给一个邻居或者物业，跟他说一句「我这几天一个人」——不需要交情，只需要有人知道你在屋里；去社区居委会说明自己独居，问能不能上探访关爱的名单，老年人里独居、空巢、失独的是官方明确的服务对象，政策目标是这批老人每月都要被探访到、失能的每月至少一次，顺便问本地有没有免费装的智能呼叫器、智能水表这类装置；手机设好紧急联络人和医疗急救卡，这几天别静音、别关机。顺带一个数：本来就有心血管病、又一个人住的人，四年里死亡的比例比和人同住的高约三个百分点，45 到 65 岁这一档高约两成四。","gain":"44,573 名有动脉粥样硬化血栓风险或病史的稳定门诊患者的 REACH 国际登记（2003 年 12 月至 2004 年 12 月入组、随访 4 年）：8,594 人（19%）独居；独居者 4 年全因死亡 14.1% 对 11.1%、心血管死亡 8.6% 对 6.8%（两项 log-rank P<0.01）；年龄存在效应修饰（交互 P=0.03）——45 至 65 岁独居对同住的死亡为 7.7% 对 5.7%，调整后 HR 1.24（95% CI 1.01–1.51），66 至 80 岁 13.2% 对 12.3%，HR 1.12（1.01–1.26），80 岁以上 24.6% 对 28.4%，HR 0.92（0.79–1.06）未见升高。民政部等十部门 2022 年意见：面向独居、空巢、留守、失能、重残、计划生育特殊家庭等老年人开展探访关爱服务，服务方式为「定期上门入户、电话视频、远程监测」；由乡镇（街道）摸底排查、村（居）民委员会协助，掌握基本信息和「接受探访关爱服务的意愿」并纳入基层网格化管理；到 2025 年底「确保特殊困难老年人月探访率达到 100%」，「对失能的特殊困难老年人，每月探访关爱不少于一次」；倡导家庭配置智能呼叫系统、智能电水表、健康监测产品、养老监护装置，「一旦监测异常，能够及时预警，并同步向紧急联系人发送提示信息」；服务人员发现紧急问题「应当第一时间协助拨打紧急求助电话」","grade":"B","src":"Udell JA, et al. (2012). Living alone and cardiovascular risk in outpatients at risk of or with atherothrombosis. Archives of Internal Medicine. <https://doi.org/10.1001/archinternmed.2012.2782>；民政部等十部门 (2022). 关于开展特殊困难老年人探访关爱服务的指导意见（民发〔2022〕73 号）. <https://www.gov.cn/zhengce/zhengceku/2022-10/13/content_5718017.htm>","note":"给 B 的原因：独居与死亡率的关联是观察性的，去不掉「本来身体差、条件差的人更可能独居」这层反向解释，原文自己也写这个结果有待确认；探访关爱那份文件只覆盖老年人，不满 60 岁的没有对应的专门制度，能指的是网格员和社工「及时发现家庭变故、失业、失学等心理危机风险」这条要求（见本节第 11 条，要人陪着说话打 12356）。「有人发现」为什么值钱看第 13 节第 1 条：院外心脏骤停 79.2% 发生在家里，有旁观者按压的出院存活率 16.1%，没有的 3.9%，屋里没人就等于落在低的那一档。另外两件顺手的：办丧事本身要跑殡仪馆、社区卫生服务机构、公安、公积金几个窗口（见第 25 节），把它排成每天出门一次的固定日程，这几天的外出结构现成就有；热线是可以反复打的，不是只能打一次（见本节第 11 条，要人陪着说话打 12356）。「一个人住」本身还是个长期风险因素（独居的死亡比值比 1.32，见第 22 节第 10 条（把定期和人见面当健康支出）），但这条只管眼前这几天，长期那笔账不在这里算。","money":"0","time":"少","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"29.7","sec":29,"n":7,"title":"家长去世后，如实告诉孩子、让他参加告别、别送去别处「换个环境」","cost":"0，代价是自己也难受的时候还得跟孩子把话说清楚","human":"18 岁前失去父亲或母亲的孩子，到成年早期为止死亡的概率比没经历过的人高约五成；父母死于意外、自杀这类非自然原因的高约八成，死于疾病的高约三成。所以这不是「小孩子过两天就忘了」的事，影响会延续很多年。能做的事：如实说，别编「出远门了」；让他参加告别；别中断上学、别把他送到亲戚家「换个环境」；把监护和抚养安排落到书面。","gain":"丹麦 1968 至 2008 年、瑞典 1973 至 2006 年出生的全人群与芬兰 1987 至 2007 年出生者的 89.3% 抽样，合计逾 730 万人，其中 189,094 人在 18 岁前失去父母：全因死亡率比未丧亲者高 50%（死亡率比 1.50，95% CI 1.43–1.58）；父母死于非自然原因者 1.84（1.71–2.00），死于自然原因者 1.33（1.24–1.41）；孩子的死因与父母死因属同一类别时最高","grade":"B","src":"Li J, et al. (2014). Mortality after parental death in childhood: a nationwide cohort study from three Nordic countries. PLoS Medicine. <https://doi.org/10.1371/journal.pmed.1001679>","note":"给 B 不是因为数字不硬——这是三国全人群队列，数字本身是 A 级的——而是从这个数字到「怎么跟孩子说、要不要参加告别」的具体做法之间没有直接试验证据。作者也写明缺少丧亲后亲子关系质量与生活方式的数据，升高里既有遗传易感也有丧亲的长期影响。监护人指定与财产安排见第 17 节，孩子的抚养费和上学见第 18 节。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"29.8","sec":29,"n":8,"title":"哀伤过了半年还在原地、日子过不下去，去精神科或临床心理科挂号","cost":"挂号费加治疗费；这类治疗按疗程做，原始试验里平均 19 周做 16 次","human":"大约每十个丧亲的成年人里有一个会卡住：半年以上还在持续想念到吃不下饭、上不了班、带不了孩子，麻木、震惊、觉得生活没有意义、无法接受、回避一切和逝者有关的东西、认不清自己该是谁。这不是「不够坚强」，它有诊断标准，也有专门的治疗：针对性治疗的有效率 51%，换成普通的心理治疗是 28%，平均每治 4.3 个人就多一个人好转，而且起效更快。","gain":"14 项研究的系统综述与荟萃分析（非暴力丧亲的非精神科成人）：延长哀伤障碍合并患病率 9.8%（95% CI 6.8–14.0），平均年龄越大患病率越高。诊断标准的效度验证研究（291 名丧亲者，分 0–6、6–12、12–24 个月三次访谈）：核心症状为对逝者的强烈渴念，加上情感麻木、震惊、觉得生活没有意义、不信任他人、因这次失去而痛苦、难以接受、身份混乱、回避现实、无法继续生活这九项中至少五项，每日出现或达到致残程度，且在死亡至少 6 个月后仍存在并伴随功能损害。95 人的随机对照试验（16 次治疗、平均 19 周）：针对复杂哀伤的治疗有效率 51%，人际心理治疗 28%（P=0.02），起效更快，需治疗人数 4.3","grade":"A","src":"Lundorff M, et al. (2017). Prevalence of prolonged grief disorder in adult bereavement: A systematic review and meta-analysis. Journal of Affective Disorders. <https://doi.org/10.1016/j.jad.2017.01.030>；Prigerson HG, et al. (2009). Prolonged grief disorder: Psychometric validation of criteria proposed for DSM-V and ICD-11. PLoS Medicine. <https://doi.org/10.1371/journal.pmed.1000121>；Shear MK, et al. (2005). Treatment of complicated grief: a randomized controlled trial. JAMA. <https://doi.org/10.1001/jama.293.21.2601>","note":"这个诊断在不同文献里叫复杂哀伤或延长哀伤障碍，不同标准要求的时长也不同（6 个月或 12 个月），别自己卡月份——判断标准是「影响到吃饭、睡觉、上班、带孩子」，对上了就去挂号。9.8% 这个患病率来自方法学差异较大的 14 项研究，作者提示外部效度有限。科室叫精神科、心理科或临床心理科，公立精神专科医院都有。","money":"少","time":"中","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"29.9","sec":29,"n":9,"title":"别一上来就花钱做哀伤咨询，先看自己有没有对上第 8 条那几条","cost":"0，反过来省下一笔咨询费","human":"把心理咨询普遍安排给所有丧亲的人，在干预结束时只有很小的效果，到随访时就看不出好处了——原因是没做干预的人本来也大多会自己缓过来。丧偶前后追踪 205 人的研究里，最常见的模式恰恰是「韧性型」。但对已经出现明显适应困难的人，同样的治疗效果和治疗别的心理问题一样好，随访期还会继续变好。所以顺序是：先对照第 8 条（哀伤卡住了去精神科），对上了再花这笔钱，别一开始就买课买咨询。","gain":"61 项对照研究的荟萃分析：丧亲心理干预在治疗结束时效应量小，随访时无统计学意义的获益；只招收「已出现明显适应困难」的丧亲者的干预，效果与治疗其他心理问题的心理治疗相当；未做筛查的研究结果不佳，可归因于对照组随时间自然好转。14 项随机对照试验的荟萃分析：治疗性干预在治疗后和随访时均显著优于对照，随访期效应还在增大；预防性干预无效。205 人从丧偶前到丧偶后 6、18 个月的前瞻研究：识别出五种模式（普通哀伤、慢性哀伤、慢性抑郁、丧亲期间改善、韧性），其中韧性型最常见，普通哀伤型相对少见","grade":"A","src":"Currier JM, et al. (2008). The effectiveness of psychotherapeutic interventions for bereaved persons: a comprehensive quantitative review. Psychological Bulletin. <https://doi.org/10.1037/0033-2909.134.5.648>；Wittouck C, et al. (2011). The prevention and treatment of complicated grief: a meta-analysis. Clinical Psychology Review. <https://doi.org/10.1016/j.cpr.2010.09.005>；Bonanno GA, et al. (2002). Resilience to loss and chronic grief: a prospective study from preloss to 18-months postloss. Journal of Personality and Social Psychology. <https://doi.org/10.1037/0022-3514.83.5.1150>","note":"这条说的是「不必人人做」，不是「都别做」——第 4 条（亲人死于自杀、意外或凶案）那类高危丧亲、第 8 条（哀伤卡住了去精神科）那类已经卡住的人，正是证据支持要做的人群。一篇 Lancet 综述的结论是同一句：哀伤不是病，多数人不需要专业干预，干预应针对高危者和已出现复杂哀伤、丧亲相关抑郁与应激障碍的人（Stroebe M, et al. (2007). Health outcomes of bereavement. Lancet. <https://doi.org/10.1016/S0140-6736(07)61816-9>）。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"29.10","sec":29,"n":10,"title":"分居离婚之后别断医保、别用酒顶着","cost":"0，把医保续上，把酒停掉","human":"合并 11 个国家、650 万人的分析里，分居或离婚的人早死的概率明显高于还在婚的人，男性和年纪较轻的人升幅更大。原文没把这当成因果——离婚的人在健康、收入上本来就可能不一样。作者列的四条机制里，有两条是自己能按住的：收入和保障中断（别让医保、体检断掉），以及健康行为变差（酒和烟）。","gain":"32 项前瞻研究、逾 650 万人、16 万例死亡、逾 75.5 万例离婚、11 个国家的随机效应荟萃分析：与在婚者相比，分居或离婚的成年人早死风险显著升高；男性和较年轻的成年人升高幅度显著大于女性和年长者；作者讨论了四种可能机制——社会选择、资源中断、健康行为改变、慢性心理压力","grade":"A","src":"Sbarra DA, et al. (2011). Divorce and Death: A Meta-Analysis and Research Agenda for Clinical, Social, and Health Psychology. Perspectives on Psychological Science. <https://doi.org/10.1177/1745691611414724>","note":"原文给的是「显著升高」和分组比较，本条不写具体倍数，收益量级按「只有方向、没有可套阈值的相对降幅」定为中。离婚时的财产、债务与彩礼见第 8 节和第 10 节，孩子的抚养安排见第 18 节。","money":"0","time":"少","will":"些","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"29.11","sec":29,"n":11,"title":"要人陪着说话打 12356，未成年人和青少年打 12355，要看医生挂心理门诊","cost":"0，两条热线都免费；心理门诊按普通门诊挂号","human":"免费的两条线：12356 是全国心理援助热线，未成年人和青少年另有 12355 青少年综合服务平台，方案要求两条线联动，也要求建立和 110 的联动机制，各地进度不同。要看医生就挂精神科、心理科或临床心理科的心理门诊——按 2026 年这份方案，到 2030 年各级公立精神专科医院和每个县（区）至少一所医院都要提供心理门诊服务，八成以上的村和社区要设心理咨询室或社会工作室。遇到家庭变故、失业、失学，社区网格员和社工本来就该主动发现。","gain":"国家卫生健康委等 25 部门 2026 年方案：完善 12356 心理援助热线工作制度，保证稳定运行、提升接通率，推动建立省级 12356 信息化平台，加强与 110 等服务热线的联动机制建设；建强用好 12355 青少年综合服务平台，并与 12356 联动协作；目标为到 2030 年，80% 以上的行政村、城市社区设心理咨询室或社会工作室并提供心理服务，各级公立精神专科医院、各县（区）至少有 1 所医院提供心理门诊服务，各省建成省级 12356 心理援助平台；心理危机干预与心理援助队伍由精神科医师、心理治疗技师、心理咨询人员、社会工作专业人员和志愿者组成；要求网格员、社会工作专业人员、志愿者做前端日常排查，及时发现家庭变故、失业、失学等心理危机风险（全国，2026 年 3 月印发）","grade":"B","src":"国家卫生健康委等 25 部门 (2026). 关于印发健全社会心理服务体系和危机干预机制实施方案的通知（国卫医政发〔2026〕8 号）. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065035.htm>","note":"给 B 是因为村社区咨询室、县级心理门诊这些是 2030 年的建设目标，不是当下各地都已具备；12356 和 12355 是现在就能打的。12356 的开通时间和每日接听时长见第 1 节第 25 条。心理咨询和心理治疗不是一回事：诊断和开药要精神科医师，治疗要在有资质的医疗机构做，市面上按小时收费的「疗愈」「灵性咨询」不在这个体系里。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"29.12","sec":29,"n":12,"title":"变故后的头三个月，凡是不可逆的大决定一律往后推","cost":"0，只是把决定推迟，代价是可能错过某些机会","human":"这段时间你对各种「机会」的判断力最差：说能联系逝者的、说能帮你把钱翻回来的、劝你辞职去外地重新开始的、劝你赶紧把房子卖了的、拉你合伙的。这段时间做的决定很多不可逆——卖房、辞职、把赔偿款一次性投出去、仓促再婚、替人担保。给自己定一条硬规矩：金额超过一个月收入、或者反悔要付大代价的事，一律推后三个月，并且先讲给一个跟这件事没有利益关系的人听——没有这样的人就打 12356 讲，或者自己写下来隔三天再读一遍，要的只是「不在当天拍板」。","gain":"避免在应激期做出不可逆的财产处置——卖房、辞职、把抚恤金或赔偿款一次性投出去、仓促再婚、替人担保。这类决定的金额通常在数万元到房产级别，也是本条收益定为中的原因。官方口径同样把「家庭变故、失业、失学」列为社区要主动排查的心理危机风险，即这段时间的状态被认为是需要外部支持的","grade":"C","src":"作者经验，无直接文献；「家庭变故、失业、失学」作为心理危机风险的表述见国家卫生健康委等 25 部门 (2026). 健全社会心理服务体系和危机干预机制实施方案（国卫医政发〔2026〕8 号）. <https://www.gov.cn/zhengce/zhengceku/202604/content_7065035.htm>","note":"「三个月」是作者定的阈值，没有文献支持这个具体时长，所以本条是 C 级。针对丧亲者和老人的常见骗局见第 17 节（投资养老、以房养老）和第 6 节（算命）；担保和借条的坑见第 8 节。该主动去办的钱——公积金余额、社保待遇、工亡三笔钱——见第 25 节和第 19 节，那些不在「往后推」之列。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"29.13","sec":29,"n":13,"title":"别拿死当还债的办法：两年内的寿险不赔，工伤不认，债照样先从遗产里扣","cost":"0 元，只是把这笔账算清","human":"以死亡为给付条件的保险，从合同成立或者效力恢复算起两年内被保险人自杀的，保险公司不赔，只按合同退保单的现金价值（自杀时为无民事行为能力人的除外）。工伤这条路也堵着：自残或者自杀不认定为工伤，丧葬补助金、供养亲属抚恤金、一次性工亡补助金三笔钱一分没有。债更不会跟着人消失：分割遗产要先清偿该缴的税和债，继承人在所得遗产的实际价值内清偿——欠的钱先从你留下的东西里扣，家里人拿到的是扣完剩下的那点。留给他们的不是一笔钱，是一个缺口，外加本节第 4 条（因自杀或暴力死亡丧亲）那份健康代价。","gain":"保险法第四十四条：以被保险人死亡为给付保险金条件的合同，自合同成立或者合同效力恢复之日起二年内被保险人自杀的，保险人不承担给付保险金的责任（被保险人自杀时为无民事行为能力人的除外），并应当按照合同约定退还保险单的现金价值——寿险保额通常在数十万元级，这也是本条收益定为大的依据。工伤保险条例第十六条第三项：自残或者自杀的，不得认定为工伤或者视同工伤，第三十九条那三笔工亡待遇（丧葬补助金 6 个月统筹地区上年度职工月平均工资、供养亲属抚恤金、一次性工亡补助金为上一年度全国城镇居民人均可支配收入的 20 倍）随之全部落空。民法典第一千一百五十九条：分割遗产应当清偿被继承人依法应当缴纳的税款和债务；第一千一百六十一条：继承人以所得遗产实际价值为限清偿，放弃继承的可以不负清偿责任","grade":"A","src":"全国人大常委会 (2015 修正). 中华人民共和国保险法第四十四条. <https://flk.npc.gov.cn/detail?id=2c909fdd678bf17901678bf7c4060811>；国务院 (2010 修订). 工伤保险条例（国务院令第 586 号）第十六条、第三十九条. <https://www.gov.cn/gongbao/content/2011/content_1778064.htm>；全国人大 (2020). 中华人民共和国民法典第一千一百五十九条、第一千一百六十一条. <https://flk.npc.gov.cn/detail?id=ff808081729d1efe01729d50b5c500bf>","note":"这条只算钱这一笔账——本节和第 1 节其他条目说的是别走到这一步。保险法第四十四条只管前两年，写出来是为了把条文说全，不是给一个时间表。家人这一侧的健康代价见本节第 4 条（配偶死于自杀者 5 年内新发精神障碍风险高七到八成），念头冒出来时怎么办见第 1 节第 25、30 条，救回来之后的后遗症见第 1 节第 31 条；工亡三笔钱的标准见第 19 节第 16 条，遗产和债务的具体手续见第 25 节第 9 条（逐个去取公积金和社保待遇）","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"}]},{"n":30,"title":"上学以后的孩子","intro":"第 20 节讲的是刚出生那一年，第 18 节算的是养孩子的钱和时间，中间 3 到 18 岁这十几年原来是空的。这一节补上，只回答一个问题：当「别耽误学习」和「身体」撞在一起时，哪些事不能等——因为它们有时间窗口，过了就不可逆。学业该不该那么卷不在本节讨论范围内，本节只给窗口和数字。\n前六条口径是死亡率与健康终点，第 7 条是金钱，第 8、9 条是时间。溺水、交通、头盔、HPV 疫苗见第 1 节，婴幼儿见第 20 节，孩子被骗和游戏充值见第 5 节，未成年人自己别踩的红线见第 9 节，急症识别与叫车见第 13 节，家长去世后的孩子见第 29 节，不重复。","entries":[{"id":"30.1","sec":30,"n":1,"title":"孩子说突然剧痛、而且越来越重，立刻去医院，不要让他忍到放学","cost":"0，请半天假，挂急诊","human":"有些病是按小时算的。男孩突然一侧阴囊剧痛，是睾丸扭转：6 小时内处理，睾丸保住的比例 97.2%；拖到 7 到 12 小时降到 79.3%，13 到 18 小时 61.3%，19 到 24 小时 42.5%，超过 48 小时只剩 7.4%。它没有「先吃片止痛药看看」的余地，也等不到放学、等不到考完。同一条规矩适用于所有突然发作、持续加重、和平时不一样的疼。","gain":"30 项病例系列、2116 例睾丸扭转患者的系统综述：按 6 小时区间统计的 1283 例中，0 至 6 小时睾丸存活率 97.2%，7 至 12 小时 79.3%，13 至 18 小时 61.3%，19 至 24 小时 42.5%，25 至 48 小时 24.4%，超过 48 小时 7.4%；累计口径为 12 小时内 90.4%、13 至 24 小时 54.0%、超过 24 小时 18.1%。作者结论是存活时间可以长于通常所说的 6 至 8 小时，因此即使已经痛了很久也应积极处理","grade":"A","src":"Mellick LB, et al. (2019). A Systematic Review of Testicle Survival Time After a Torsion Event. Pediatric Emergency Care. <https://doi.org/10.1097/PEC.0000000000001287>","note":"睾丸扭转多发于青春期男孩，不少人因为难以启齿而硬忍——这句话要提前跟男孩说清楚，出这种事必须马上讲。同样按小时算的还有急性阑尾炎（拖久了穿孔）、糖尿病酮症酸中毒、脑膜炎，本节未逐条核实其时间曲线，共同信号是「突然起病、持续加重、和以往任何一次都不一样」。急症识别与叫车方式见第 13 节。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"30.2","sec":30,"n":2,"title":"该做的治疗别为了「等考完」往后拖，有些窗口跟着骨龄走，不跟着考试安排走","cost":"0，决定的是早做还是晚做，不是花不花钱；请假和复诊要占时间，治疗本身另计（支具要求每天至少佩戴 18 小时）","human":"青少年特发性脊柱侧弯有一个明确的窗口——骨头还在长的时候戴支具，弯到需要手术的比例明显下降：随机分组里，戴支具的成功率 75%，只观察的 42%，而且戴够时间的效果更好，试验因为支具确实有效被提前叫停。这个窗口跟着骨骼成熟走，不跟着中考高考走。等考完再说，等到的往往是「只剩手术」这一个选项。","gain":"多中心试验，242 例有支具指征的青少年特发性脊柱侧弯患者（116 例随机分组、126 例自选），主要终点为侧弯进展至 50 度以上（治疗失败）与骨骼成熟时未达该程度（治疗成功）：意向治疗分析中，随机戴支具组成功率 75%，随机观察组 42%（OR 4.11，95% CI 1.85–9.16）；合并随机与自选队列后为 72% 对 48%（倾向评分校正 OR 1.93，1.08–3.46）；佩戴小时数与成功率显著正相关（P<0.001）；试验因支具有效而提前终止","grade":"A","src":"Weinstein SL, et al. (2013). Effects of bracing in adolescents with idiopathic scoliosis. New England Journal of Medicine. <https://doi.org/10.1056/NEJMoa1307337>","note":"用脊柱侧弯举例，是因为它有随机试验、有明确的时间窗口，而且正好是学生体检的重点项目之一（见第 5 条）。同类的还有斜视、弱视、龋齿和先天性心脏病的择期手术，共同点是越晚做效果越差或代价越大，具体窗口问专科医生。请假不是问题：义务教育阶段休学最长 1 年且保留学籍，见第 9 条。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"30.3","sec":30,"n":3,"title":"孩子被欺凌，当天就报到学校并要求书面处理，涉及打人、抢钱、传谣的直接报警","cost":"0，找班主任和学校的学生欺凌治理组织；报警打 110","human":"被同伴欺凌的孩子，出现自杀念头的可能性是没被欺凌的约 2.2 倍，有过自杀行为的约 2.6 倍，网络欺凌和自杀念头的关联比线下更强，这个结论不随性别、年龄变化。制度上你有明确的抓手：学校接到欺凌报告应当立即调查，认定构成欺凌的要对施害学生作出教育惩戒或纪律处分；违反治安管理或者涉嫌犯罪的严重欺凌，学校不得隐瞒，必须报公安机关。所以要做的是当天报、要求走认定程序、留下书面记录，而不是「让老师说说他」。","gain":"34 项研究、284,375 名儿童青少年的荟萃分析：遭同伴欺凌与自杀意念相关，OR 2.23（95% CI 2.10–2.37）；9 项研究、70,102 人中与自杀未遂相关，OR 2.55（1.95–3.34）；结果不受性别、年龄和研究质量调节，网络欺凌与自杀意念的关联强于传统欺凌。《未成年人学校保护规定》第二十一条把殴打脚踢掌掴抓咬推撞拉扯、辱骂讥讽起侮辱性绰号、抢夺强拿硬要或故意毁坏财物、恶意排斥孤立、通过网络捏造事实诽谤或散布谣言五类行为列出，并规定在年龄、身体或人数上占优势的一方蓄意或恶意实施、造成人身伤害、财产损失或精神损害的可以认定为欺凌；第二十二条要求教职工发现学生情绪反常、身体损伤应及时了解并报告；第二十三条要求学校接到报告立即调查、提交欺凌治理组织认定处置、通知家长参与，认定构成欺凌的作出教育惩戒或纪律处分，对违反治安管理或涉嫌犯罪的严重欺凌行为不得隐瞒，应当及时向公安机关、教育行政部门报告（全国，2021 年 9 月 1 日起施行）","grade":"A","src":"van Geel M, et al. (2014). Relationship between peer victimization, cyberbullying, and suicide in children and adolescents: a meta-analysis. JAMA Pediatrics. <https://doi.org/10.1001/jamapediatrics.2013.4143>；教育部 (2021). 未成年人学校保护规定（教育部令第 50 号，第二十一、二十二、二十三条）. <https://www.gov.cn/zhengce/zhengceku/2021-06/02/content_5614946.htm>","note":"荟萃分析是观察性证据，不能证明欺凌单独导致自杀，但风险方向和量级明确。《加强中小学生欺凌综合治理方案》另外要求严格区分欺凌与学生间打闹嬉戏，也就是说学校有义务做认定、不能一句「小孩子闹着玩」了事。孩子身上出现说不清的伤、突然不肯上学、东西反复丢失，先按第二十二条那几个信号去问。","money":"0","time":"少","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"30.4","sec":30,"n":4,"title":"让孩子每天在户外待够 2 小时，这是目前唯一有随机试验支持的防近视办法","cost":"0，但每天要腾出时间，多半得从写作业和网课里挤","human":"广州 12 所小学的随机试验，给一年级学生每天多加 40 分钟户外活动课并鼓励课外多出去，三年后近视的比例是 30.4%，对照学校是 39.5%，少了 9.1 个百分点。卫健委给的量是每天日间户外不少于 2 小时，或者每周累计 14 小时，阴天也算数。课间到室外站着也算数。","gain":"广州 12 所小学一年级学生的整群随机试验（干预校 952 人，对照校 951 人，平均年龄 6.6 岁）：干预为每个上学日增加 1 节 40 分钟户外活动课并鼓励家长在课外增加户外活动；3 年累计近视发生率干预组 30.4%（853 名合格者中 259 例），对照组 39.5%（726 名中 287 例），差值 -9.1 个百分点（95% CI -14.1 至 -4.1，P<0.001）；3 年等效球镜变化 -1.42 D 对 -1.59 D（差 0.17 D，P=0.04）；眼轴增长差异无统计学意义（P=0.07）。《防控儿童青少年近视核心知识十条》要求儿童青少年每天日间户外活动不少于 2 小时或每周累计 14 小时，注明即使阴天户外活动也有防护效果，并要求避开午后高温强晒时段","grade":"A","src":"He M, et al. (2015). Effect of Time Spent Outdoors at School on the Development of Myopia Among Children in China: A Randomized Clinical Trial. JAMA. <https://doi.org/10.1001/jama.2015.10803>；国家卫生健康委办公厅 (2023). 防控儿童青少年近视核心知识十条（国卫办妇幼函〔2023〕278 号）. <https://www.gov.cn/zhengce/zhengceku/202307/content_6894284.htm>","note":"这项试验只在干预 3 年的窗口内、只在 6 岁起始的孩子身上测过，近视发生率的绝对差是 9.1 个百分点，不是「不近视」。同一份核心知识十条还给了读写「一尺一拳一寸」、近距离用眼 20 分钟后远眺 20 秒以上、中小学生非学习目的使用电子屏幕单次不超过 15 分钟且每天累计不超过 1 小时。「待在户外」和「上体育课」不是一回事，课间到室外站着也算数。","money":"0","time":"中","will":"些","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"30.5","sec":30,"n":5,"title":"每年那次学生体检的报告单要自己看一遍，异常项当年带去医院查","cost":"0，义务教育阶段的体检费由学校公用经费出，家长不另掏","human":"中小学校每年组织 1 次学生健康体检，外科查脊柱，眼科查远视力和屈光度，报告单上规定要把超重、肥胖、营养不良、脊柱弯曲异常、视力不良、龋齿列为重点指导内容——恰好就是最容易被「等等再说」拖过去的那几样。所以别只扫一眼身高体重就把单子收起来：这几项里有异常，当年就带孩子去专科查清楚，别等下一次体检。","gain":"《中小学生健康体检管理办法（2021 年版）》规定中小学校每年组织 1 次在校学生健康体检；外科检查包括头部、颈部、胸部、脊柱、四肢、皮肤、淋巴结，眼科检查包括眼外观、远视力、屈光度；个体报告单应包括客观结果、综合评价和健康指导建议，其中超重、肥胖、营养不良、脊柱弯曲异常、视力不良、龋齿须作为指导重点；教育行政部门应当对出现健康问题的学生建立档案并随访；义务教育阶段学生健康体检费用由学校公用经费开支（全国，2021 年 9 月印发）","grade":"B","src":"国家卫生健康委、教育部 (2021). 中小学生健康体检管理办法（2021 年版）（国卫医发〔2021〕29 号）. <https://www.gov.cn/zhengce/zhengceku/2021-10/21/content_5644100.htm>","note":"给 B 是因为这是一份工作规范，不是效果研究——它保证的是「每年查、查这些、异常要随访」，不保证查出来就一定处理。体检是筛查不是诊断：视力不良要去眼科做散瞳验光（第 10 条），脊柱弯曲异常要去骨科或脊柱外科（第 2 条，别为了等考完推迟治疗），这两步都得家长自己带着去。","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"30.6","sec":30,"n":6,"title":"12 到 18 岁的孩子做一次抑郁筛查，别拿学校的心理测评当诊断","cost":"0 到几十元，社区或医院门诊做量表；12355、12356 两条热线免费","human":"美国预防服务工作组建议给 12 到 18 岁的青少年筛查重度抑郁，这一档推荐的含义是「净获益中等、值得做」；11 岁及以下的证据不够，专门筛「自杀风险」的证据也不够。同一份文件提到，自杀是 10 到 19 岁人群的第二位死因。国内学校每学年会做一次心理测评，但那是普查不是诊断——孩子自己说难受，或者你看到他吃、睡、兴趣、成绩短时间内明显变样，直接挂精神科或临床心理科。","gain":"美国预防服务工作组 2022 年推荐声明：建议对 12 至 18 岁青少年筛查重度抑郁障碍（B 类推荐，中等确定性、中等净获益）；对 11 岁及以下儿童筛查重度抑郁的证据不足（I 声明）；对儿童青少年筛查自杀风险的获益与危害证据不足（I 声明）；文件指出自杀是 10 至 19 岁人群的第二位死因，儿童青少年的重度抑郁与成年期复发性抑郁、其他精神障碍以及自杀意念、自杀未遂和自杀死亡风险增加密切相关。《进一步加强中小学生心理健康工作十条措施》要求构建班主任、专兼职心理健康教师、精神科医师三级服务体系，每名学生每学年接受心理测评一般不超过 1 次，推进精神疾病转介就医和愈后复学机制，发挥 12355 青少年服务台和 12356 心理援助热线作用（全国，2025 年 10 月印发）","grade":"B","src":"US Preventive Services Task Force (2022). Screening for Depression and Suicide Risk in Children and Adolescents: US Preventive Services Task Force Recommendation Statement. JAMA. <https://doi.org/10.1001/jama.2022.16946>；教育部办公厅 (2025). 进一步加强中小学生心理健康工作十条措施（教基厅〔2025〕2 号）. <https://www.gov.cn/zhengce/zhengceku/202510/content_7045528.htm>","note":"给 B 是因为这是推荐等级而不是可换算的效应量，而且是美国的推荐，国内没有对应的官方筛查建议。筛查阳性只说明要进一步评估，不等于确诊。有自杀念头时的处置见第 1 节第 25 条，家里的应对见第 29 节。","money":"0","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"高"},{"id":"30.7","sec":30,"n":7,"title":"不买号称能「治愈近视」「降低度数」的产品和服务","cost":"0，反过来省下这笔钱","human":"市场监管总局的原话是「在目前医疗技术条件下，近视不能治愈」，并且把「康复」「恢复」「降低度数」「近视治愈」「近视克星」「度数修复」这几种说法直接列为要从严查处的违法营销表述，冒用中医药名义的、拿患者形象做疗效前后对比的、对疗效作保证性承诺的，都在查处范围里。所以看到这类词就可以直接排除，不用再比价。护眼仪之类属于医疗器械，电商平台被要求审查经营资质。","gain":"市场监管总局办公厅 2021 年 11 月至 2022 年 3 月的专项整治行动通知：明确「在目前医疗技术条件下，近视不能治愈」，要求依法从严查处使用「康复」「恢复」「降低度数」「近视治愈」「近视克星」「度数修复」等误导性表述营销儿童青少年近视防控产品的行为；加大对冒用中医药名义或假借中医药理论技术进行营销宣传欺骗消费者行为的打击力度；严厉打击使用患者名义或形象作诊疗前后效果对比、对诊疗安全性功效作保证性承诺的虚假违法广告；要求电商平台严格落实护眼仪等医疗器械及有关特殊商品的经营资质审查责任（全国）","grade":"B","src":"市场监管总局办公厅 (2021). 关于开展儿童青少年近视防控产品违法违规商业营销宣传专项整治行动的通知. <https://www.gov.cn/zhengce/zhengceku/2021-11/12/content_5650400.htm>","note":"给 B 是因为这是执法口径而不是产品有效性的对照研究，但「近视不能治愈」这句是卫生和监管部门的一致表述，《防控儿童青少年近视核心知识十条》里写的是「近视可防可控不可逆」。真正有证据的两件事在第 4 条（户外）和第 10 条（规范验光配镜与复查）。防蓝光眼镜见第 6 节。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"30.8","sec":30,"n":8,"title":"睡眠、作业、体育和排名都有明文规定，学校做不到可以提","cost":"0，知道条文，必要时向学校或当地教育行政部门反映","human":"这几条都是白纸黑字：小学生每天睡 10 小时、初中 9 小时、高中 8 小时；小学上午上课一般不早于 8:20、中学不早于 8:00，学校不得要求学生提前到校参加统一教学活动；就寝一般不晚于 21:20、22:00、23:00；校外培训结束不晚于 20:30，线上直播类不晚于 21:00；每天 22:00 到次日 8:00 不得向未成年人提供游戏服务。2025 年又加了每天综合体育活动不低于 2 小时、鼓励课间 15 分钟、不得以考试成绩给学生排名。孩子长期睡不够，先拿这几条去对，而不是先怪孩子磨蹭。","gain":"《关于进一步加强中小学生睡眠管理工作的通知》：小学生每天睡眠应达 10 小时、初中生 9 小时、高中生 8 小时；小学上午上课时间一般不早于 8:20，中学一般不早于 8:00，学校不得要求学生提前到校参加统一的教育教学活动；小学生就寝一般不晚于 21:20，初中生不晚于 22:00，高中生不晚于 23:00；校外培训机构培训结束时间不得晚于 20:30，线上直播类培训结束不得晚于 21:00，每日 22:00 到次日 8:00 不得为未成年人提供游戏服务（全国，2021 年 3 月印发）。《进一步加强中小学生心理健康工作十条措施》：全面推行中小学生每天综合体育活动时间不低于 2 小时，鼓励推行「课间 15 分钟」，不得以考试成绩对学生进行排名，严禁布置机械重复、惩罚性作业，鼓励每周设置一天「无作业日」（全国，2025 年 10 月印发）","grade":"B","src":"教育部办公厅 (2021). 关于进一步加强中小学生睡眠管理工作的通知（教基厅函〔2021〕11 号）. <https://www.gov.cn/zhengce/zhengceku/2021-04/02/content_5597443.htm>；教育部办公厅 (2025). 进一步加强中小学生心理健康工作十条措施（教基厅〔2025〕2 号）. <https://www.gov.cn/zhengce/zhengceku/202510/content_7045528.htm>","note":"这两份都是部门规范性文件，落实程度各地各校差别很大，本条给 B。它们的用处是让你知道哪些要求是学校本来就该做的，谈的时候有依据。成年人的睡眠账见第 2、3 节。","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"30.9","sec":30,"n":9,"title":"孩子撑不住了可以休学，学籍学校必须给他留着，最长 1 年","cost":"0，由父母或其他法定监护人向学校提出申请","human":"休学是有正式制度的：由父母或其他法定监护人提出申请，学校确认后报上级学籍管理部门核准；一次申请的期限不超过 1 年，期满确需继续休学的重新申请；休学期间学校应当为学生保留学籍，复学时学校应及时办理手续。2025 年的十条措施还专门要求推进「精神疾病转介就医和愈后复学机制」建设。所以「休学等于毁了」这句话在制度上不成立，具体办法由各省定，问学校教务处或当地教育局。","gain":"《中小学生学籍管理办法》第十六条：学生休学由父母或其他法定监护人提出申请，学校确认后报上级学籍管理部门核准，复学时学校应及时办理相关手续；申请休学的期限不超过 1 年，休学期满后确需继续休学的应重新申请办理；学生休学期间学校应为其保留学籍，休复学的具体办法由省级教育行政部门制定（全国，2025 年 1 月印发）。《进一步加强中小学生心理健康工作十条措施》要求推进精神疾病转介就医和愈后复学机制建设，指导学校制定校园突发心理危机事件处理预案","grade":"B","src":"教育部 (2025). 中小学生学籍管理办法（教基〔2025〕1 号，第十六条）. <https://www.gov.cn/zhengce/zhengceku/202502/content_7002620.htm>；教育部办公厅 (2025). 进一步加强中小学生心理健康工作十条措施（教基厅〔2025〕2 号）. <https://www.gov.cn/zhengce/zhengceku/202510/content_7045528.htm>","note":"给 B 是因为休学的具体条件、材料和复学衔接由省级教育行政部门规定，全国层面只定了框架。办之前先问清楚三件事：需要什么医疗证明、休学期间学籍怎么标记、复学是回原年级还是降一级。《未成年人学校保护规定》另要求义务教育学校健全辍学或者休学、长期请假学生的报告备案制度，所以这条路学校是走过的，不是特例。","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"30.10","sec":30,"n":10,"title":"查出视力不良，去医院做散瞳验光，之后按医生给的间隔复查","cost":"几十到几百元的检查和配镜费；散瞳后畏光、看近模糊，要半天到一两天缓过来","human":"散瞳验光是诊断近视的金标准，卫健委写明散瞳药物对健康的眼睛不会产生损伤，用药后短期畏光、看近不清，停药后恢复正常。确诊了就及时配镜矫正，戴镜视力正常的，学龄前和小学生每 3 到 6 个月复查一次，初高中生每 6 到 12 个月复查一次。别拿眼镜店的一次电脑验光当诊断，也别因为「怕度数涨」不给孩子配镜。","gain":"《防控儿童青少年近视核心知识十条》：散瞳验光是使用睫状肌麻痹剂放松眼部调节后进行的医学验光，为诊断近视的「金标准」，散瞳药物对健康的眼睛不会产生损伤，用药后可短期出现畏光、视近不清，停药后可恢复正常；一旦确诊近视应及时科学干预，通过配戴眼镜等矫正，配戴合适的眼镜可以有效矫正视物不清、延缓近视进展；戴镜视力正常者，学龄前儿童及小学生每 3 至 6 个月、初高中学生每 6 至 12 个月复查，根据具体情况决定是否更换眼镜；儿童在 1 至 3 岁、4 至 6 岁、7 岁之后应定期接受屈光筛查，监测远视储备量（全国，2023 年 7 月印发）","grade":"B","src":"国家卫生健康委办公厅 (2023). 防控儿童青少年近视核心知识十条（国卫办妇幼函〔2023〕278 号）. <https://www.gov.cn/zhengce/zhengceku/202307/content_6894284.htm>","note":"给 B 是因为这是官方科普文件给的做法，不是带效应量的原始研究。高度近视会带来视网膜脱离等并发症，所以复查的意义不只是换眼镜。学校体检查出的「视力不良」只是筛查结果，要拿去医院做完整的眼科检查，见第 5 条。","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"},{"id":"30.11","sec":30,"n":11,"title":"恒磨牙长出来以后做窝沟封闭","cost":"每颗几十到一两百元，不打麻药不磨牙，一次几分钟；不少地方对适龄儿童有免费项目","human":"把恒磨牙咬合面的沟槽用树脂封起来，24 个月后长蛀牙的概率明显低于不封的：按试验里对照组的患龋水平换算，对照组 16% 的话封闭组约 5.2%，对照组 40% 的话封闭组约 6.25%，对照组 70% 的话封闭组约 19%；作者给的总结是 24 个月时比不封闭减少 11 到 51 个百分点，48 个月内仍然有效。报告了不良事件的四项试验里没有不良事件。","gain":"38 项试验、7924 名 5 至 16 岁儿童的 Cochrane 系统综述：树脂类封闭剂对比不封闭，5 至 10 岁儿童第一恒磨牙 24 个月随访患龋 OR 0.12（95% CI 0.08–0.19，7 项试验，1548 名随机、1322 名评估，中等质量证据）；若对照组 24 个月内 16% 的牙面患龋，封闭后为 5.2%（3.13%–7.37%），对照组 40% 时为 6.25%（3.84%–9.63%），对照组 70% 时为 19%（12.3%–27.2%）；48 至 54 个月随访 OR 0.21（0.16–0.28）；作者结论为树脂封闭剂在 24 个月时较不封闭减少 11% 至 51% 的龋齿；4 项报告不良事件的试验中未出现不良事件；玻璃离子封闭剂与不同封闭材料之间的相对效果证据不足","grade":"A","src":"Ahovuo-Saloranta A, et al. (2017). Pit and fissure sealants for preventing dental decay in permanent teeth. Cochrane Database of Systematic Reviews. <https://doi.org/10.1002/14651858.CD001830.pub5>","note":"第一恒磨牙一般在 6 岁左右萌出，第二恒磨牙 12 岁左右，封闭要趁刚长出来、还没坏的时候做，蛀了就只能补。不少地区把适龄儿童的窝沟封闭列为免费项目，问当地疾控中心或社区卫生服务中心，本节未取得可逐字核对的全国性文件，所以不写覆盖范围和年龄段。龋齿也是学生体检的重点指导项之一，见第 5 条。","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":false,"ratio":"一般"}]},{"n":31,"title":"十八岁之后有哪几条路","intro":"口径是金钱与时间，拒服兵役那条兼及人身自由。这一节是一张路径地图，不是某一条路的说明书：先把各条路的法定门槛摆在一起，再逐条写那些「知道了才用得上」的东西——当兵能拿到什么、进体制内除了考公还有哪些口子、高考填志愿时哪两个专业直接对着编制、学历后来还能不能补、想出国打工该找什么样的公司、不进单位的人社保怎么办、没本钱起步有没有贴息的钱可借。\n先把话说明白：十八岁之后能走的路远不止这一节写到的，这里只收「有全国层面的公开文件、门槛和待遇能逐条核对」的那些。没有统一文件可查的路（进国企、进工厂、当船员、做自由职业、接着读高中读大学）不是不能走，是没有可引用的硬条文，本书不凭印象替它们写条件。\n选哪条路是你自己的事，本节只提供两样东西：门槛写在哪份文件里，以及走上去之后有哪些期限和资格是过期就作废的。读书还是打工那道题怎么算、技能怎么挑见第 23 节，进了单位之后的加班费、工伤和离职补偿见第 19 节，开店办公司的本钱和退场见第 12 节，出国留学见第 32 节，失业之后的兜底见第 7 节，都不重复。","entries":[{"id":"31.1","sec":31,"n":1,"title":"先把门槛对一遍：十二条路的年龄和学历要求都是明文写死的","cost":"0 元；花十分钟对一遍自己够不够得着","human":"打工要满 16 周岁。当兵：男性满 18 周岁进征集范围，22 周岁前仍可被征集，本科毕业生放宽到 24、研究生 26。考公务员：18 到 35 周岁、大专以上，因犯罪受过刑事处罚、被开除公职、被列为失信联合惩戒对象的不得报考。消防员：18 到 22 周岁、高中以上，大专以上学历或者退役士兵放宽到 24。军队文职：年满 18 周岁，普通工和较低职级岗位首次招录最高 35 周岁。事业单位：新聘人员原则上都要面向社会公开招聘。个体户：只要求「有经营能力的公民」，不问学历。自考：不受性别、年龄、民族、种族和已受教育程度限制，但全日制在校生不能报。公费师范生：高考提前批，只在六所教育部直属师范大学招，本科加教育硕士一体设计。农村订单定向免费医学生：录取后、拿到入学通知书前就要和学校、定向县的卫生健康和人社部门签三方协议。出国打工：你这边没有学历门槛，门槛在公司那边——只有取得对外劳务合作经营资格的企业才能组织你出去，任何单位和个人都不得以商务、旅游、留学的名义组织劳务人员赴国外工作。平台接单（外卖、网约车、同城货运）和灵活就业：没有哪份文件给它们设学历门槛，社保怎么缴、职业伤害保障谁出见本节第 11、12 条（灵活就业自己参保、平台按单缴职业伤害保障）。","gain":"兵役法「年满十八周岁的男性公民，应当被征集服现役；当年未被征集的，在二十二周岁以前仍可以被征集服现役。普通高等学校毕业生的征集年龄可以放宽至二十四周岁，研究生的征集年龄可以放宽至二十六周岁」。《公务员录用规定》第十八条报考条件含「年龄为十八周岁以上，三十五周岁以下」「具有大学专科以上文化程度」，经省级以上公务员主管部门批准可适当调整；第十九条列了五类不得报考的人。《国家综合性消防救援队伍消防员招录办法》第五条「年龄为 18 周岁以上、22 周岁以下」「具有高中以上文化程度」，第六条「大学专科以上学历人员、解放军和武警部队退役士兵……年龄可以放宽至 24 周岁」。《中国人民解放军文职人员条例》第九条基本条件含「年满 18 周岁」，第十九条较低职级岗位首次招录聘用最高年龄 35 周岁。《事业单位人事管理条例》第八条「事业单位新聘用工作人员，应当面向社会公开招聘」。《促进个体工商户发展条例》「有经营能力的公民……依法登记为个体工商户的，适用本条例」。《高等教育自学考试暂行条例》第三条「中华人民共和国公民，不受性别、年龄、民族、种族和已受教育程度的限制，均可依照本条例的规定参加高等教育自学考试」，第二十条「各级各类全日制学校的在校生不得报考」。《教育部直属师范大学本研衔接师范生公费教育实施办法》第二条，公费师范生只在北京师范大学、华东师范大学、东北师范大学、华中师范大学、陕西师范大学和西南大学六所部属师范大学招，本科和研究生阶段一体设计、分段考核，中央财政承担在校期间学费、住宿费并给生活费补助；第五条「招收公费师范生实行提前批次录取」。《关于做好农村订单定向免费培养医学生就业安置和履约管理工作的通知》：定向医学生「在录取后、获得入学通知书前，须与培养学校和定向就业所在地的县级卫生健康行政部门……人力资源社会保障部门签署协议」。《对外劳务合作管理条例》第五条从事对外劳务合作应当经商务主管部门批准取得经营资格，第七条第四款「未依法取得对外劳务合作经营资格证书并办理登记，不得从事对外劳务合作」，第八条第二款「任何单位和个人不得以商务、旅游、留学等名义组织劳务人员赴国外工作」。平台接单与灵活就业没有法定学历门槛，待遇依据见本节第 11、12 条。义务教育法「禁止用人单位招用应当接受义务教育的适龄儿童、少年」（全国）","grade":"A","src":"全国人大常委会 (2021). 兵役法（第二十条）. <http://www.mod.gov.cn/regulatory/2021-08/20/content_4892491.htm>（国防部刊登）；中共中央组织部 (2019). 公务员录用规定（第十八、十九条）. <https://www.12371.cn/2020/01/08/ARTI1578447606460158.shtml>（共产党员网刊登）；人力资源社会保障部、应急管理部 (2021). 国家综合性消防救援队伍消防员招录办法（人社部发〔2021〕58 号，第五、六条）. <https://www.gov.cn/zhengce/zhengceku/2021-08/27/content_5633684.htm>；国务院、中央军委 (2022). 中国人民解放军文职人员条例（第二次修订，令第 757 号，第九、十九条）. <https://flk.npc.gov.cn/detail?id=ff808181857bca5e01859ee5a6c06d62>（国家法律法规数据库）；国务院 (2014). 事业单位人事管理条例（国务院令第 652 号，第八条）. <https://www.gov.cn/zhengce/zhengceku/2014-05/15/content_8810.htm>；国务院 (2022). 促进个体工商户发展条例（国务院令第 755 号，第二条）. <https://www.gov.cn/zhengce/zhengceku/2022-10/25/content_5721592.htm>；国务院 (1988, 2014 修订). 高等教育自学考试暂行条例（第三、二十条）. <https://flk.npc.gov.cn/detail?id=ff8080816f3cbb3c016f415d64e5236d>（国家法律法规数据库）；全国人大常委会 (2018). 义务教育法（第十四条）. <http://www.moe.gov.cn/jyb_sjzl/sjzl_zcfg/zcfg_jyfl/202110/t20211029_575949.html>（教育部刊登）；国务院办公厅 (2024). 关于转发教育部等部门《教育部直属师范大学本研衔接师范生公费教育实施办法》的通知（国办发〔2024〕27 号，第二、五条）. <https://www.gov.cn/zhengce/zhengceku/202406/content_6957261.htm>；国家卫生健康委等 7 部门 (2019). 关于做好农村订单定向免费培养医学生就业安置和履约管理工作的通知. <https://www.gov.cn/zhengce/zhengceku/2019-11/13/content_5451684.htm>；国务院 (2012). 对外劳务合作管理条例（国务院令第 620 号，第五、七、八条）. <https://www.gov.cn/zhengce/zhengceku/2012-06/11/content_1091.htm>","note":"这条只对门槛，不比较回报。门槛之外还有政治条件、体检和政治考核，这几项没有公开的量化标准，条文里查不到。中职、技工院校和职教贯通招生的入口见第 23 节第 5 条，读不起时的资助见第 23 节第 4 条。个体户不设学历门槛不等于开店容易，本钱、个人担保和退场成本见第 12 节，起步钱能不能借到贴息的见本节第 15 条。公费师范生和定向医学生这两条是在高考填志愿时就定下的，代价写在第 13 条；出国打工的门槛在公司资质那边，怎么认见第 14 条。","money":"0","time":"少","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"31.2","sec":31,"n":2,"title":"十八岁那年 10 月 31 日前要做兵役登记；义务兵服现役就是两年","cost":"0 元；登记在网上填一次几分钟，真去当兵的代价是两年全职","human":"兵役登记是法定义务，不是报名参军。当年 12 月 31 日以前年满 18 周岁的男性，县级兵役机关应当在当年 10 月 31 日前组织完成初次登记，走网络登记、本人在平台上自主完成；不登记的，县级人民政府责令限期改正，逾期不改正的强制履行兵役义务并处罚款。真去了，义务兵的服现役期限就是两年，本人自愿的话满 17 周岁也能入伍。两年之后想接着干的转军士，军士要服满 12 年才够得上安排工作，满 30 年或者年满 55 周岁才作退休安置。征兵优先保证高校毕业生，在校生和应届毕业生可以在户籍地或者学校所在地报名。","gain":"《兵役登记工作规定》：「县、自治县、不设区的市、市辖区人民政府兵役机关应当于每年 10 月 31 日前，组织本行政区域内当年 12 月 31 日以前年满 18 周岁的男性公民进行初次兵役登记」；「初次兵役登记主要采取网络登记的方式进行，由公民通过兵役登记网络平台自主完成」。兵役法第五十七条第一款：「拒绝、逃避兵役登记的」，「由县级人民政府责令限期改正；逾期不改正的，由县级人民政府强制其履行兵役义务，并处以罚款」；「义务兵服现役的期限为二年」；「根据军队需要和本人自愿，可以征集年满十七周岁未满十八周岁的公民服现役」；军士「服现役满十二年或者符合国家规定的其他条件的，由安置地的县级以上地方人民政府安排工作」，「服现役满三十年或者年满五十五周岁或者符合国家规定的其他条件的，作退休安置」。《征兵工作条例》「优先保证普通高等学校毕业生和对政治、身体条件或者专业技能有特别要求的兵员征集」；「应征公民为普通高等学校的全日制在校生、应届毕业生的，可以在入学前户籍所在地或者学校所在地应征」（全国）","grade":"A","src":"国务院办公厅、中央军委办公厅 (2025). 兵役登记工作规定（国办发〔2025〕41 号）. <https://www.gov.cn/zhengce/zhengceku/202512/content_7051363.htm>；全国人大常委会 (2021). 兵役法（2021 年修订，第二十、二十五、二十六、五十四、五十七条）. <http://www.mod.gov.cn/regulatory/2021-08/20/content_4892491.htm>（国防部刊登）；国务院、中央军委 (2023). 征兵工作条例（国务院、中央军委令第 759 号，第五条）. <http://www.gov.cn/gongbao/content/2023/content_5753313.htm>","note":"登记和应征是两件事，代价差一大截，两年内不准出境那一串惩戒只对应征之后反悔的人，见第 3 条。女性公民不在初次兵役登记的强制范围，按军队需要征集。士兵考军校和优秀士兵提干的条件写在军队内部法规里，公开渠道查不到；兵役法只写了现役军官从「表现优秀的现役士兵」等人员中选拔招收、军队院校招收学员的年龄不受征集年龄限制，具体分数线和名额本书不给。","money":"0","time":"多","will":"是","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"31.3","sec":31,"n":3,"title":"应征之后拒服兵役，两年内不准出境或升学复学，还进不了公务员和国企","cost":"0 元；代价是在报名之前就把要不要去想清楚","human":"应征之后再拒绝、逃避服现役，兵役法接的是一串联合惩戒：不得录用为公务员或者参照公务员法管理的人员，不得招录、聘用为国有企业和事业单位工作人员，两年内不准出境或者升学复学，纳入履行国防义务严重失信主体名单。这一条一次封掉几乎所有体制内的路，也封掉出国和回学校。所以「先报上再说，不行就退回来」是个很贵的想法。","gain":"兵役法第五十七条第一款第二项是「应征公民拒绝、逃避征集服现役的」，「由县级人民政府责令限期改正；逾期不改正的，由县级人民政府强制其履行兵役义务，并处以罚款」；第二款：「有前款第二项行为，拒不改正的，不得录用为公务员或者参照《中华人民共和国公务员法》管理的工作人员，不得招录、聘用为国有企业和事业单位工作人员，两年内不准出境或者升学复学，纳入履行国防义务严重失信主体名单实施联合惩戒。」第五十八条把同一套惩戒接到已经入伍的人身上：军人以逃避服兵役为目的拒绝履行职责或者逃离部队，被军队除名、开除军籍或者被依法追究刑事责任的，依照第五十七条第二款处罚，其中被除名的并处罚款（全国，2021 年 10 月 1 日起施行）","grade":"A","src":"全国人大常委会 (2021). 兵役法（2021 年修订，第五十七、五十八条）. <http://www.mod.gov.cn/regulatory/2021-08/20/content_4892491.htm>（国防部刊登）","note":"口径是人身自由与就业资格，不是钱。射程要看准：联合惩戒只对「应征公民拒绝、逃避征集服现役」和入伍后被除名、开除军籍、追究刑责这两种，单纯没做兵役登记不在其内（见第 2 条）。触发点是「拒不改正」，认定和处罚由县级人民政府作出，罚款数额地方定，本书不写。这条不劝你去或不去，是说这个决定从报名那一刻起就不再可逆。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"31.4","sec":31,"n":4,"title":"大学生当兵最实的两块：学费每年补最高 20000 元，学籍保留两年、考研有专项计划","cost":"0 元；退役后按学校要求交材料申请，跑一两趟","human":"在校生、应届毕业生和新生应征入伍的，服役期间的学费由国家补偿，贷了国家助学贷款的由国家代偿，复学或者入学后的学费直接减免，标准是本专科生每人每年最高 20000 元、研究生每人每年最高 25000 元，两年就是最多四万或者五万。这是上限，按实际缴的学费和实际拿到的贷款里较高的那个算，超出不补；看到比这更低的标准是旧值，别照抄。学籍那头：服役期间保留入学资格或者学籍，退役后两年内允许入学或者复学，还能按规定转本校其他专业。考研另有一条单列的路，2026 年由 532 所高校承担，招生单位自己定初试线、一般不高于本单位普通计划的线。","gain":"财政部等四部门 2024 年通知：服兵役高校学生的学费补偿、用于学费的国家助学贷款代偿和学费减免标准「相应调整为本专科学生每人每年最高不超过 20000 元、研究生每人每年最高不超过 25000 元」，自 2024 年秋季学期起执行；补偿口径「按学生实际缴纳的学费或获得的国家助学贷款（包括本金及其全部偿还之前产生的利息）两者金额较高者执行」，「超出标准部分不予补偿、代偿或减免」。《退役军人保障法》：「现役军人入伍前已被普通高等学校录取或者是正在普通高等学校就学的学生，服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学，可以按照国家有关规定转入本校其他专业学习」；「高等学校根据国家统筹安排，可以通过单列计划、单独招生等方式招考退役军人」。教育部办公厅 2026 年通知：「退役大学生士兵计划」「在全国硕士研究生招生计划总规模内单列下达、专项使用，不得调整为普通计划或其他专项计划。招生单位自主确定……初试成绩要求（一般不高于本单位相应学科专业普通计划考生初试成绩要求）……同等条件下服役时间长的考生优先录取」，2026 年由 532 所普通高等学校承担（全国）","grade":"A","src":"财政部、教育部、中国人民银行、金融监管总局 (2024). 关于调整完善国家助学贷款有关政策的通知（财教〔2024〕188 号）. <https://www.gov.cn/zhengce/zhengceku/202411/content_6984812.htm>；财政部等五部门 (2019). 学生资助资金管理办法（财科教〔2019〕19 号，第五条）. <http://www.gov.cn/gongbao/content/2019/content_5421553.htm>；全国人大常委会 (2020). 退役军人保障法（第三十四、三十五条）. <http://www.mod.gov.cn/gfbw/fgwx/flfg/16048597.html>（国防部刊登）；教育部办公厅 (2025). 关于做好 2026 年退役大学生士兵专项硕士研究生招生计划招生工作的通知（教学厅〔2025〕8 号）. <http://www.moe.gov.cn/srcsite/A15/moe_778/s3261/202512/t20251211_1423174.html>","note":"TODO（待核实：退役军人免试专升本与研究生初试加分的原始通知）——这两项在退役军人事务部的政策摘要里有转述，但教育部相应通知的原文本轮未取得，所以只写有这条通道、不写加多少分，报名前以当年的招生文件为准；走了专项计划就不再享受初试加分，两者不叠加。承担专项计划的高校名单每年变（2025 年是 523 所）。学费标准调过两次：8000/12000（2019 年）→ 16000/20000（2023 年秋）→ 20000/25000（2024 年秋），退役军人事务部 2022 年的摘要里还是最早那一版，别照抄。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"极高"},{"id":"31.5","sec":31,"n":5,"title":"退役后只有六种情况由政府安排工作；自主就业的 30 日内必须报到","cost":"0 元；带退役证明到安置地退役军人事务部门跑一趟","human":"「当兵包分配」早就不是普遍情况。现行条例只列了六种由政府安排工作的情形：军士服现役满 12 年、个人获得勋章或荣誉称号、荣立三等战功或二等功以上、获得一级表彰、因战致残被评为 5 到 8 级、烈士子女。义务兵服两年退役，绝大多数落在自主就业那一档。够得上安排工作的，安置地政府要在接收后 6 个月内落实，单位签不少于 3 年的合同、军龄 10 年以上的签无固定期限，待安排期间按当地月最低工资发生活补助。自主就业的那一档有个硬期限：自被批准退出现役之日起 30 日内必须报到，无正当理由超过 30 日的，视为放弃安置待遇——回家先歇一阵再说，可能就把整笔待遇歇没了。","gain":"《退役军人安置条例》第二十五条列举六种由安置地人民政府安排工作的情形：「（一）军士服现役满 12 年的；（二）服现役期间个人获得勋章、荣誉称号的；（三）服现役期间个人荣获三等战功、二等功以上奖励的；（四）服现役期间个人获得一级表彰的；（五）因战致残被评定为 5 级至 8 级残疾等级的；（六）是烈士子女的」；「安置地人民政府应当在接收退役军士和义务兵的 6 个月内完成安排退役军士和义务兵工作的任务」；用人单位「应当按照规定与其签订不少于 3 年的中长期聘用合同或者劳动合同。其中，企业接收军龄 10 年以上的退役军士的，应当与其签订无固定期限劳动合同」；待安排工作期间「按照当地月最低工资标准逐月发放生活补助」，非因本人原因未按规定安排上岗的「按照不低于本单位同等条件人员平均工资 80% 的标准，逐月发放生活费直至上岗为止」；不得以安排工作方式安置的情形包括被开除中国共产党党籍、受过刑事处罚。第五十一条：「自主就业的退役军士和义务兵，应当自被批准退出现役之日起 30 日内，到安置地人民政府退役军人工作主管部门报到。无正当理由不按照规定时间报到超过 30 日的，视为放弃安置待遇。」（全国，2024 年 9 月 1 日起施行）","grade":"A","src":"国务院、中央军委 (2024). 退役军人安置条例（国务院、中央军委令第 787 号，2024 年 7 月 29 日公布、9 月 1 日施行；第二十五、三十一、三十二、三十五、五十一、七十五条）. <https://www.gov.cn/gongbao/2024/issue_11526/202408/content_6969192.html>；全国人大常委会 (2020). 退役军人保障法（第十三、十四、十五条）. <http://www.mod.gov.cn/gfbw/fgwx/flfg/16048597.html>（国防部刊登）","note":"这份条例施行的同一天，2011 年的《退役士兵安置条例》（国务院、中央军委令第 608 号）废止，网上大量攻略引的还是旧条例，条件表述已经变了（旧版写的是「平时荣获二等功以上奖励或者战时荣获三等功以上奖励」）。30 日这个期限只管自主就业那一档，其他安置方式是「按照规定时间」报到。报到时会发退役军人优待证，后面的退役金、就业创业扶持和教育资助都从这里接上。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"31.6","sec":31,"n":6,"title":"退役后的三笔账：一次性退役金、军龄算工龄、自己干每年扣减 20000 元税","cost":"0 元；退役时军队转保险关系和资金，到安置地社保经办机构办接续","human":"第一笔是自主就业的一次性退役金，中央财政专项安排、按服现役年限发，获得勋章或荣誉称号增发 25%，往下依次是 20%、15%、10%、5%；具体金额条例本身不写、由退役军人事务部会同财政部另定，想知道确切数额只能问当地退役军人事务局。第二笔是这两年不算社保空白：军龄计算为工龄，养老、医疗、失业的缴费年限跟入伍前和退役后合并算，医疗那块是视同缴费年限，没马上找到工作的还能申领失业保险待遇。第三笔是自己干的税：从办个体工商户登记当月起 3 年内按每户每年 20000 元为限额扣减增值税等税费，各省最多再上浮 20%；企业招你并签 1 年以上合同、依法缴社保的，3 年内按每人每年 6000 元定额扣减，各省最多上浮 50%，政策执行到 2027 年 12 月 31 日。","gain":"《退役军人安置条例》：「对自主就业的退役军士和义务兵，根据其服现役年限发放一次性退役金」，「由中央财政专项安排，具体标准由国务院退役军人工作主管部门、中央军事委员会政治工作部门会同国务院财政部门……确定，并适时调整」；增发比例为获得勋章、荣誉称号 25%，一等战功或一级表彰 20%，二等战功、一等功或二级表彰 15%，三等战功或二等功 10%，四等战功或三等功 5%；「退役军人未及时就业的，可以依法向户口所在地人力资源社会保障部门申领失业保险待遇，服现役年限视同参保缴费年限，但是以退休、供养方式安置的退役军人除外」。《退役军人保障法》：「退役军人服现役年限计算为工龄，退役后与所在单位工作年限累计计算」；服现役年限与入伍前、退役后的养老、医疗、失业缴费年限「依法合并计算」；「退役的军士和义务兵服现役经历视为基层工作经历」。《军人保险法》：「军人服现役年限视同职工基本医疗保险缴费年限，与入伍前和退出现役后参加职工基本医疗保险的缴费年限合并计算」。财政部等三部门 2023 年第 14 号公告：自主就业退役士兵从事个体经营的，「在 3 年（36 个月，下同）内按每户每年 20000 元为限额依次扣减其当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税。限额标准最高可上浮 20%」；企业招用的「定额标准为每人每年 6000 元，最高可上浮 50%」，执行期为 2023 年 1 月 1 日至 2027 年 12 月 31 日，到期未满 3 年的可继续享受至期满（全国）","grade":"A","src":"国务院、中央军委 (2024). 退役军人安置条例（国务院、中央军委令第 787 号，第二十一、二十二、七十四、八十一、八十五条）. <https://www.gov.cn/gongbao/2024/issue_11526/202408/content_6969192.html>；全国人大常委会 (2020). 退役军人保障法（第四十二、四十四、五十条）. <http://www.mod.gov.cn/gfbw/fgwx/flfg/16048597.html>（国防部刊登）；全国人大常委会 (2012). 军人保险法（第十六、二十三条）. <https://flk.npc.gov.cn/detail?id=2c909fdd678bf17901678bf73e160645>（国家法律法规数据库）；财政部、税务总局、退役军人事务部 (2023). 关于进一步扶持自主就业退役士兵创业就业有关税收政策的公告（2023 年第 14 号）. <https://www.gov.cn/zhengce/zhengceku/202308/content_6896456.htm>","note":"TODO（待核实：一次性退役金的现行具体金额）——条例明确金额由主管部门另定，本轮未在公开渠道取得现行标准原文，所以不写数字，也别信攻略里的具体数额。义务兵服现役期间家里另领一笔家庭优待金，兵役法只写「标准由地方人民政府制定，中央财政给予定额补助」，问批准入伍地的县级人民政府。税那一笔是扣减限额不是到手的钱，生意没起来就用不满，所以整条的收益量级定「中」。2026 年 8 月 1 日起施行的《退役军人就业创业促进条例》另加了一条：服役期间取得的技能人员职业资格证书退役后在全国范围内通用。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"31.7","sec":31,"n":7,"title":"想进体制内不止考公一条：基层服务项目干满两年，能报每年 10% 的定向考录计划","cost":"0 元；代价是到乡镇基层服务两年，收入是财政补助不是市场价","human":"「三支一扶」和大学生志愿服务西部计划这类基层服务项目，是给应届毕业生的另一个体制内入口。三支一扶服务期两年，各省每年要拿出公务员考录计划的 10% 左右面向服务基层项目人员定向考录；县乡事业单位公开招聘要拿出一定岗位专项招聘期满考核合格的人，聘用后可以不再约定试用期。期满考核合格的，三年内考研初试总分加 10 分；高职高专毕业的可以免试入读成人高等学历教育专升本。服务年限计算为工龄，参加工作时间从到基层报到之日起算；服务前没有工作经历的，期满两年内在考录招聘、落户、升学上还能按应届毕业生对待。西部计划由共青团中央等四部门组织，首次签约一年、可申请延长，整体服务期一到三年。","gain":"第四轮「三支一扶」计划通知：「服务期为两年」；「各省（区、市）每年应拿出公务员考录计划的 10％左右，面向『三支一扶』计划等服务基层项目人员定向考录。各省（区、市）县乡基层事业单位公开招聘时，应根据本地区实际拿出一定数量或比例的岗位，对『三支一扶』服务期满考核合格的人员进行专项招聘……聘用后可以不再约定试用期」；「期满考核合格的『三支一扶』人员，三年内参加全国硕士研究生招生考试的，初试总分加 10 分，同等条件下优先录取……高职（高专）毕业生期满且考核合格的，可免试入读成人高等学历教育专科起点本科」；「参加『三支一扶』计划前无工作经历的人员期满且考核合格的，两年内在参加机关和企事业单位考录（招聘）、自主创业、落户、升学等方面可同等享受应届毕业生相关政策。『三支一扶』人员在基层服务年限计算为工龄，其参加工作时间按其到基层报到之日起算」；中央财政补助标准为西部地区每人每年 3 万元、中部地区 2.4 万元、东部地区 1.2 万元。中办国办意见：「参加基层服务项目前无工作经历的人员服务期满且考核合格后 2 年内，在参加机关事业单位考录（招聘）、各类企业吸纳就业、自主创业、落户、升学等方面可同等享受应届高校毕业生的相关政策」；「省级以上机关录用公务员，除特殊职位外，按照有关规定一律从具有 2 年以上基层工作经历的人员中考录」。西部计划由「共青团中央、教育部、财政部、人力资源社会保障部共同组织实施」，招募高校应届毕业生或在读研究生「到西部基层从事为期 1—3 年」的志愿服务（全国）","grade":"A","src":"中共中央组织部、人力资源社会保障部等十部门 (2021). 关于实施第四轮高校毕业生「三支一扶」计划的通知（人社部发〔2021〕32 号，第七、八、九、十一、十二、十三条）. <https://www.gov.cn/zhengce/zhengceku/2021-06/04/content_5615404.htm>；中共中央办公厅、国务院办公厅 (2017). 关于进一步引导和鼓励高校毕业生到基层工作的意见（第五、十六、十八条）. <http://www.gov.cn/gongbao/content/2017/content_5171278.htm>；全国大学生志愿服务西部计划项目管理办公室 (2026). 2026—2027 年度大学生志愿服务西部计划招募协议书. <http://xibu.youth.cn/tzgg/202604/t20260423_16623558.htm>","note":"第四轮三支一扶计划的周期是 2021 到 2025 年，本轮未检索到第五轮文件和 2026 年度通知，报名前查当年的招募公告；2025 年中央财政支持招募 34430 名。西部计划的实施方案原文不在公开渠道（官网政策栏目是脚本渲染的），期满优惠按中办国办那份基层服务项目的通用条款走。这条的时间成本是实打实的两年，收入是财政补助不是市场价，别只看后面的定向考录。","money":"0","time":"多","will":"是","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"31.8","sec":31,"n":8,"title":"特岗教师三年服务期满、考核合格又愿意留下的，应当及时入编","cost":"0 元；代价是三年在农村义务教育学校任教，还要先考出教师资格证","human":"特岗计划是少数几条写明「期满入编」的路。条件是本科及以上学历、以师范类专业为主，小学阶段可以适当招师范专科毕业生，年龄不超过 30 周岁，要有相应的教师资格证。服务期三年，中央财政给工资性补助，2024 年起中部地区年人均 3.88 万元、西部 4.18 万元；在职期间的薪酬、职称评聘、评先评优、年度考核跟当地公办学校在编教师同等。三年期满考核合格且愿意留任的，文件要求及时入编并落实岗位，连续计算工龄教龄，不再实行试用期。参加过西部计划、有从教经历或者实习支教半年以上的同等条件优先，退役军人可以放宽年龄。","gain":"2024 年特岗计划通知招聘条件：「要求本科及以上学历，以师范类专业为主，小学阶段可适当招聘师范高等专科学校毕业生」；「年龄不超过 30 周岁」；须具有相应的教师资格证书；「参加过『大学生志愿服务西部计划』、有从教经历的志愿者和参加过半年以上实习支教的师范院校毕业生同等条件下优先录取」；「支持鼓励符合条件的退役军人到中小学任教，可综合考虑服役年限等因素对退役军人相应放宽年龄限制」。待遇与入编：「从 2024 年 1 月 1 日起，提高特岗教师工资性补助标准，中央财政……中部地区由年人均 3.52 万元提高到 3.88 万元，西部地区由 3.82 万元提高到 4.18 万元」；「同等条件下在薪酬待遇、职称评聘、评先评优、年度考核等方面享受与当地公办学校在编教师同等待遇」；「保证三年服务期满、考核合格且愿意留任的特岗教师及时入编并落实工作岗位，做好相关人事、工资关系等接转工作，连续计算工龄、教龄，不再实行试用期」（全国）","grade":"A","src":"教育部办公厅、财政部办公厅 (2024). 关于做好 2024 年农村义务教育阶段学校教师特设岗位计划实施工作的通知（教师厅〔2024〕1 号）. <https://www.gov.cn/zhengce/zhengceku/202405/content_6950803.htm>","note":"收益量级定「大」是因为期满入编是一份长期编制内工作，量级远过万元。本轮检索到的最新一份是 2024 年度通知，2025、2026 年度的没进政策库，具体岗位、补助标准和年龄以当年通知和本省实施方案为准——特设岗位由中央定框架、省里定细则。教师资格证要先考出来，这是入场券不是入职后再补。","money":"0","time":"多","will":"是","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"31.9","sec":31,"n":9,"title":"消防员和军队文职是另外两个公开招录的口子，门槛比考公低","cost":"0 元；报名到录用要走体检、政治考核、体能测试、心理测试和面试，前后几个月","human":"国家综合性消防救援队伍面向社会公开招录消防员，条件是 18 到 22 周岁、高中以上文化程度，大专以上学历的人、解放军和武警退役士兵、有两年以上灭火救援实战经验的政府专职消防队员放宽到 24 周岁，急需的特殊专业人才经批准原则上不超过 28 周岁，主要从本省常住人口中招、也可以跨省。军队文职走公开招考、直接引进、专项招录三条线，基本条件只要求年满 18 周岁加政治条件和岗位要求，较低职级岗位首次招录的最高年龄是 35 周岁，文职岗位应当优先招录符合条件的退役军人。两条路的共同点是不卡「大专以上」这道普遍门槛，共同的代价是政治考核和体检刷人。","gain":"《国家综合性消防救援队伍消防员招录办法》第五条基本条件含「年龄为 18 周岁以上、22 周岁以下」「具有高中以上文化程度」；第六条「大学专科以上学历人员、解放军和武警部队退役士兵、具有 2 年以上灭火救援实战经验的政府专职消防队员和政府专职林业扑火队员，年龄可以放宽至 24 周岁；对消防救援工作急需的特殊专业人才，经应急管理部批准年龄可以进一步放宽，原则上不超过 28 周岁」；第七条「消防员面向社会公开招录，主要从本省级行政区域常住人口中招录，根据需要也可以面向其他省份招录」；第九条招录程序为「宣传动员、组织报名、资格审查、体格检查、政治考核、体能测试和岗位适应性测试、心理测试和面试、公示、录用」。《中国人民解放军文职人员条例》第十八条「军队实行公开招考、直接引进、专项招录相结合的文职人员招录聘用制度」；第九条基本条件含「年满 18 周岁」「符合军队招录聘用文职人员的政治条件」「符合岗位要求的文化程度、专业水平和工作能力」；第十九条较低职级岗位首次招录聘用最高年龄 35 周岁，「文职人员岗位应当优先招录聘用符合条件的退役军人」（全国）","grade":"A","src":"人力资源社会保障部、应急管理部 (2021). 国家综合性消防救援队伍消防员招录办法（人社部发〔2021〕58 号，第五、六、七、九条）. <https://www.gov.cn/zhengce/zhengceku/2021-08/27/content_5633684.htm>；国务院、中央军委 (2022). 中国人民解放军文职人员条例（第二次修订，国务院、中央军委令第 757 号，2023 年 1 月 1 日施行；第九、十八、十九、二十条）. <https://flk.npc.gov.cn/detail?id=ff808181857bca5e01859ee5a6c06d62>（国家法律法规数据库）","note":"2026 年 8 月 1 日起施行的《退役军人就业创业促进条例》另写明，消防员招录要设一定比例专项招录退役军士和义务兵，招聘警务辅助人员时同等条件下优先招聘退役军人。这两条路的年度名额、岗位和具体条件都以当年公告为准，本书只写办法里的固定门槛。消防员是纪律部队岗位，不是普通工作，进去之前把职业风险想清楚。","money":"0","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"31.10","sec":31,"n":10,"title":"学历不是一锤子买卖：自考不限年龄和已受教育程度，成人高考和开放大学都能补","cost":"报名费和教材费每年几百元；代价是长期自学或者业余上课，非脱产的专升本最短两年半","human":"十八岁那年没读成书，后面还有三条正规通道。自考：不受性别、年龄、民族、种族和已受教育程度限制，全日制在校生不能报；考完计划内全部课程、完成毕业论文或实践任务、思想品德鉴定合格就发毕业证，国家承认学历，非在职人员录用后工资待遇与普通高校同类毕业生相同。成人高考：分高起本、高起专、专升本三种，报高起本或高起专要高中毕业或同等学力，报专升本要先有国家承认的专科毕业证；脱产最短高起本四年、高起专和专升本两年，非脱产最短高起本五年、高起专和专升本两年半。开放大学：注册入学，修满学分发学历证书，符合条件的授学位。三条路都慢，但都不看你十八岁那年考成什么样。","gain":"《高等教育自学考试暂行条例》第三条「中华人民共和国公民，不受性别、年龄、民族、种族和已受教育程度的限制，均可依照本条例的规定参加高等教育自学考试」，第二十条「各级各类全日制学校的在校生不得报考」，第二十五条考完全部课程并合格、完成毕业论文或实践任务、思想品德鉴定合格的可取得毕业证书，「获得专科（基础科）或本科毕业证书者，国家承认其学历」，第三十二条毕业证书获得者的工资待遇「非在职人员录用后，与普通高等学校同类毕业生相同」。《高等教育法》第二十一条「国家实行高等教育自学考试制度，经考试合格的，发给相应的学历证书或者其他学业证书」。《2025 年全国成人高校招生办法》：报名对象为「国家承认学历的各类高、中等学校在校生以外的从业人员和社会其他人员」，「报考高起本或高起专的考生应高级中等教育学校毕业或者具有同等学力。报考专升本的考生必须是已取得……专科毕业证书、本科结业证书或以上证书的人员」；「脱产最短学习时间为：高起本四年、高起专和专升本两年，非脱产最短学习时间为：高起本五年、高起专和专升本两年半」。《教育部关于办好开放大学的意见》：「开放大学实行注册入学，学生修完课程并获得相应学分，即可获得课程证书，修满规定的学分并达到相关要求，即可获得相应的学历与非学历证书，符合学位授予条件的应授予相应学位」（全国）","grade":"A","src":"国务院 (1988, 2014 修订). 高等教育自学考试暂行条例（第三、二十、二十五、三十二条）. <https://flk.npc.gov.cn/detail?id=ff8080816f3cbb3c016f415d64e5236d>（国家法律法规数据库）；全国人大常委会 (2018). 高等教育法（第二十一条）. <https://flk.npc.gov.cn/detail?id=ff8080816f135f46016f20df64ec16c5>（国家法律法规数据库）；教育部办公厅 (2025). 关于做好 2025 年全国成人高校招生工作的通知（教学厅〔2025〕6 号）及附件《2025 年全国成人高校招生办法》. <https://www.gov.cn/zhengce/zhengceku/202509/content_7040877.htm>；教育部 (2016). 关于办好开放大学的意见（教职成〔2016〕2 号）. <http://www.gov.cn/gongbao/content/2016/content_5067956.htm>","note":"TODO（待核实：统招专升本的全国层面规定）——面向应届全日制专科毕业生的普通专升本，现行依据是教育部高校学生司的年度函件，未在公开渠道发布，只能从省级教育厅的转发文里看到文号和口径，且招生对象基本限于当届全日制专科毕业生、规则由各省定，所以正文不写它的条件。自 2025 年秋季起，高等学历继续教育不再使用「函授」「业余」的名称，统一叫「非脱产」，看到旧名称的宣传要留神。学历补救和「学什么技能划算」是两件事，后者见第 23 节；花钱买的「快速拿证」和山寨证书见第 23 节第 8 条。","money":"少","time":"多","will":"是","level":"中","lens":"金钱","dispute":false,"todo":true,"ratio":"一般"},{"id":"31.11","sec":31,"n":11,"title":"不进单位就是灵活就业：养老和医疗要自己在就业地参保，户籍限制已经放开","cost":"养老和医疗全额自己缴，按当地缴费基数每月上千元，是这条路最容易被漏算的固定支出","human":"不进单位不等于没有社保这回事，只是没人替你交那一半。文件要求各地放开灵活就业人员在就业地参加基本养老、基本医疗保险的户籍限制，个别超大城市可以逐步放开；没参加职工养老和职工医保的，组织按规定参加城乡居民养老和居民医保，做到应保尽保。所以别把「自由」理解成不用管社保：断着不交，退休金和医保报销都要按断缴的规则算。平台企业也被要求引导和支持不完全符合确立劳动关系情形的新就业形态劳动者参保。","gain":"《关于维护新就业形态劳动者劳动保障权益的指导意见》：「各地要放开灵活就业人员在就业地参加基本养老、基本医疗保险的户籍限制，个别超大型城市难以一步实现的，要结合本地实际，积极创造条件逐步放开。组织未参加职工基本养老、职工基本医疗保险的灵活就业人员，按规定参加城乡居民基本养老、城乡居民基本医疗保险，做到应保尽保。督促企业依法参加社会保险。企业要引导和支持不完全符合确立劳动关系情形的新就业形态劳动者根据自身情况参加相应的社会保险」；同一份文件把用工分成三类：「符合确立劳动关系情形的，企业应当依法与劳动者订立劳动合同。不完全符合确立劳动关系情形但企业对劳动者进行劳动管理……指导企业与劳动者订立书面协议……个人依托平台自主开展经营活动、从事自由职业等，按照民事法律调整双方的权利义务」（全国，2021 年起）","grade":"A","src":"人力资源社会保障部等八部门 (2021). 关于维护新就业形态劳动者劳动保障权益的指导意见（人社部发〔2021〕56 号，第二、八条）. <https://www.gov.cn/zhengce/zhengceku/2021-07/23/content_5626761.htm>；国务院办公厅 (2020). 关于支持多渠道灵活就业的意见（国办发〔2020〕27 号）. <https://www.gov.cn/zhengce/zhengceku/2020-07/31/content_5531613.htm>","note":"原文写的是「放开」户籍限制并给超大城市留了口子，不是「已经全国取消」，落地程度问参保地。收益量级定「大」是因为断缴的代价是养老和医疗待遇本身，量级远过万元；但成本也是实打实的，全额自缴每月上千元。断缴之后怎么补、累计年限怎么算见第 7 节第 19 条。另外，在政府指定的场所和时间内卖农副产品和日常生活用品、或者利用自己的技能从事依法无须许可的便民劳务活动，无须办营业执照，这一条写在国办发〔2020〕27 号里。","money":"多","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"31.12","sec":31,"n":12,"title":"送外卖、跑网约车、拉同城货运，平台按单给你交职业伤害保障费，自己不缴","cost":"0 元；这笔钱由平台缴，你要做的是确认自己接单的平台在试点范围内","human":"出行、即时配送、同城货运这三个行业的平台企业，要按单给接单的人缴职业伤害保障费，实现每人必保、每单必保，你自己不出钱。费率是出行每单 0.01 元、即时配送每单 0.07 元或 0.25 元、同城货运每单 0.18 元。试点从 7 个省份和 7 家平台起步，2025 年 7 月 1 日起增加 10 个省份和多家平台，2026 年推动在全国 31 个省份和新疆生产建设兵团实施，三个行业的平台企业总体纳入。已经和平台建立劳动关系、适用工伤保险条例的，走工伤保险，不走这套。","gain":"《新就业形态人员职业伤害保障办法（试行）》第二条：「平台企业应当依照本办法规定参加新就业形态人员职业伤害保障……为通过平台注册并接单，以平台企业名义提供出行、即时配送和同城货运等劳动并获得报酬或者收入的新就业形态人员缴纳职业伤害保障费，实现每单必保、每人必保。适用《工伤保险条例》规定的劳动者，企业应当依法为其参加工伤保险，不适用本办法」；第九条「试行期间，出行行业按照每单 0.01 元执行；即时配送行业按照每单 0.07 元、0.25 元执行；同城货运行业按照每单 0.18 元执行」。扩围安排：「2025 年 7 月 1 日起，在已先行试点 7 个省份和 7 个平台企业的基础上……增加天津、河北、辽宁、浙江、安徽、福建、山东、湖北、广西、宁夏等 10 个省份……2026 年，推动职业伤害保障试点在全国 31 个省份和新疆生产建设兵团实施；将出行、即时配送和同城货运三个行业的平台企业总体纳入职业伤害保障试点范围」（试点，逐年扩围）","grade":"A","src":"人力资源社会保障部等九部门 (2025). 关于扩大新就业形态人员职业伤害保障试点的通知（人社部发〔2025〕24 号）及附件《新就业形态人员职业伤害保障办法（试行）》第二、九条. <https://www.gov.cn/zhengce/zhengceku/202507/content_7031656.htm>","note":"这是试点不是全国全覆盖的正式制度，接单前确认你所在的省份和平台在不在范围内，不在的就只剩商业保险这一层。同一份指导意见还要求平台向提供正常劳动的人支付不低于当地最低工资标准的报酬、按时足额支付、不得克扣或无故拖欠，并在法定节假日支付合理报酬（人社部发〔2021〕56 号，见第 11 条）；出了事先按这套走，别先跟站点私了。医保和养老那一块仍要自己参保，见第 11 条。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"31.13","sec":31,"n":13,"title":"高考填志愿那天就能锁定编制的两条路：公费师范生和定向医学生，代价是 6 年履约","cost":"0 元学费住宿费，还拿生活费补助；代价是毕业后 6 年不能自由择业，违约要退钱、交违约金、进信用记录","human":"这两条路都是「国家先替你出钱，你毕业后按协议去指定的地方干 6 年」。公费师范生只在六所教育部直属师范大学招，提前批录取，本科加教育硕士一体培养，学费住宿费由中央财政出、另有生活费补助，毕业后一般回生源省的定向地市中小学任教 6 年以上，去城镇学校的还要先到农村义务教育学校至少 1 年；不得定向到直辖市、计划单列市或省会城市主城区（五个自治区、陆地边境省份、海南、贵州、青海除外）。定向医学生是录取后、拿到入学通知书前就和学校、定向县签三方协议，承诺毕业后到定向的农村基层医疗卫生机构服务 6 年，报到后还要先参加 3 年全科住院医师规范化培训，违约的话这 3 年不计入服务期。两条路的退出成本都是明写的：没履约要退已享受的费用并缴违约金，违约记录进人事档案和信用系统，履约完成前不得被招录聘用为其他公务人员。想清楚 6 年的地点和岗位能不能接受，再在志愿表上填。","gain":"《教育部直属师范大学本研衔接师范生公费教育实施办法》（2024 年，2018 年办法同时废止）第二条：由中央财政承担学生在校期间学费、住宿费并给予生活费补助；第三条：重点为中西部地区省会城市之外的地（市、州、盟）及以下培养，「不得定向到直辖市、计划单列市或省会城市主城区任教（五个自治区、陆地边境省份、海南省、贵州省、青海省除外）」；第九条：毕业后一般回生源所在省份定向地（市、州、盟）中小学任教，「承诺从事中小学教育工作 6 年以上」，到城镇学校工作的「应到农村义务教育学校任教服务至少 1 年」；第十三条：未履约或履约期限不足的按协议承担责任，「违约行为纳入信用记录，并及时与全国信用信息共享平台共享，违约相关材料归入本人人事档案」，「履约任务完成前不得到定向地（市、州、盟）之外从教，不得被招录（聘用）为其他公务人员。完成履约任务后即修复相关信用」；第六条：录取后经考察不适合从教的，入学 1 年内退还已享受的公费教育费用并调整到非师范专业；第十四条：未在规定学习年限内取得教育硕士学历学位证书和教师资格证书的按违约处理，退费并缴纳违约金；第二十一条：各地在现有事业编制总量内解决公费师范生到中小学任教所需编制。农村订单定向免费医学生：录取后、获得入学通知书前须与培养学校和定向就业所在地县级卫生健康、人社部门签署协议，「承诺毕业后到定向农村基层医疗卫生机构服务 6 年」；履约报到就业后须参加 3 年全科专业住院医师规范化培训，培训期间原人事、工资关系不变；违约记录归入个人人事档案并作为医疗卫生机构等行政事业单位公开招录（招聘）、住院医师规范化培训招收、研究生招生录取的诚信评价依据，恶意违约者通过「信用中国」网站全国公示并实行失信联合惩戒，违约的培训年限不计入服务期；未按协议退还费用及违约金的由县级卫生健康行政部门通过法律途径追缴（全国）","grade":"A","src":"国务院办公厅 (2024). 关于转发教育部等部门《教育部直属师范大学本研衔接师范生公费教育实施办法》的通知（国办发〔2024〕27 号，第二、三、六、九、十三、十四、二十一条）. <https://www.gov.cn/zhengce/zhengceku/202406/content_6957261.htm>；国家卫生健康委、中央编办、国家发展改革委、教育部、财政部、人力资源社会保障部、国家中医药局 (2019). 关于做好农村订单定向免费培养医学生就业安置和履约管理工作的通知. <https://www.gov.cn/zhengce/zhengceku/2019-11/13/content_5451684.htm>","note":"2024 年那份办法把公费师范生改成了「本研衔接」，2018 年的老办法已经废止，网上还在流传的「本科毕业直接任教」口径是旧的；办法印发前已签协议的按原协议走。「有编制」不等于「进了就不用管」：编制是在现有总量内解决，具体岗位由地市组织用人学校专项招聘、双向选择。定向医学生服务期满想走是可以的，文件写明「服务期满，对自主择业的应予同意」；已经违约的也有信用修复通道，代价是按原协议或改到省内其他农村基层机构再服务至少 6 年，已交的费用和违约金不退。医学生这条还要算上 3 年规培的时间，总周期比师范长。各省还有自己的地方公费师范生和定向医学生计划，条件由省里定，填志愿前看当年本省的招生文件。","money":"0","time":"多","will":"是","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"31.14","sec":31,"n":14,"title":"想出国打工，先查这家公司有没有对外劳务合作经营资格：它不得向你收押金","cost":"0 元；出发前花十几分钟核公司资质、看两份合同","human":"出国打工这件事，法律管的不是你，是组织你出去的那家公司。只有取得对外劳务合作经营资格证书并办了登记的企业才能干这个，名单由商务主管部门公布并通报驻外使领馆；任何单位和个人都不得以商务、旅游、留学的名义组织人出国打工——听到「先办旅游签过去再转工签」，这句话本身就说明对方在违法。合规的流程长这样：公司先和国外雇主签书面劳务合作合同，再和你签书面服务合同或者劳动合同，合同要写明工作内容、期限、报酬、工时、休假、社保、人身安全风险，签完 10 个工作日内报商务主管部门备案；公司必须安排你接受技能、安全防范、外语和当地法律风俗的培训，必须给你买境外工作期间的人身意外伤害保险；公司不得以任何名目向你收押金或者要你提供财产担保。这类企业还得在指定银行存不低于 300 万元的风险处置备用金，你的工资、该退的服务费、赔偿和突发事件回国的钱，公司赖账时从这笔备用金里出。对方不让看合同、要押金、催你先走后补手续，就是这条要拦的那种公司。","gain":"《对外劳务合作管理条例》第五条从事对外劳务合作应当经省级或者设区的市级商务主管部门批准取得经营资格；第七条经营资格证书名单报国务院商务主管部门并通报中国驻外使馆、领馆，「未依法取得对外劳务合作经营资格证书并办理登记，不得从事对外劳务合作」；第八条「任何单位和个人不得以商务、旅游、留学等名义组织劳务人员赴国外工作」；第九条企业应当自登记之日起 5 个工作日内在指定银行缴存「不低于 300 万元人民币的对外劳务合作风险处置备用金」，缴存名单向社会公布；第十条备用金用于支付企业拒绝承担或者无力承担的应退服务费、劳动报酬、依法赔偿的损失，以及「因发生突发事件，劳务人员回国或者接受紧急救助所需费用」；第十一条不得组织劳务人员赴国外从事与赌博、色情活动相关的工作；第十二条未安排培训的不得组织出国；第十三条应当为劳务人员购买在国外工作期间的人身意外伤害保险；第二十一、二十三条须与国外雇主、与劳务人员分别订立书面合同，未订立的不得组织出国；第二十五条「不得以任何名目向劳务人员收取押金或者要求劳务人员提供财产担保」；第二十六条合同订立之日起 10 个工作日内报商务主管部门备案；第二十九条劳务人员实际权益与合同不符的，企业应当协助索赔，未得到应有赔偿的有权要求企业承担赔偿责任；第三十一条有关国家或者地区安全状况难以保障人身安全的，企业不得组织劳务人员前往；第三十七条商务主管部门建立不良信用记录和公告制度。罚则：第三十九条无资格从事对外劳务合作的查处取缔，构成犯罪的追究刑事责任；第四十条以商务、旅游、留学名义组织出国、出借资格、组织从事赌博色情相关工作的，吊销经营资格证书；第四十三条未签合同或者隐瞒信息、提供虚假信息组织出国的，罚 10 万元以上 20 万元以下并对主要负责人罚 2 万元以上 5 万元以下（全国）","grade":"A","src":"国务院 (2012). 对外劳务合作管理条例（国务院令第 620 号，第五、七、八、九、十、十一、十二、十三、二十一、二十三、二十五、二十六、二十九、三十一、三十七、三十九、四十、四十三条）. <https://www.gov.cn/zhengce/zhengceku/2012-06/11/content_1091.htm>","note":"这条管的是「正规怎么走」，境外高薪招聘骗局、电诈园区那一面在第 21 节第 5 条，出发前要查的安全提醒和 12308 在第 21 节，不重复。条例没有给劳务人员设学历或年龄门槛，门槛在企业资质和用工项目所在国的许可上；公司只能和经该国批准的企业或机构签合同，不得和国外的个人签。备用金不是给你随便取的钱，是企业赖账时由主管部门动用的兜底，所以真出事仍要先向商务主管部门投诉（第二十条给了投诉权）。派往同一国家或地区超过 100 人的要安排随行管理人员并报使领馆备案，人少的项目没有这层保障，更要自己留好合同和转账记录。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"31.15","sec":31,"n":15,"title":"不进单位自己干，起步钱先看创业担保贷款：个人最高 30 万、财政贴一半利息","cost":"0 元咨询；跑一次人社部门做资格审核，再到担保机构和经办银行各办一次手续","human":"如果一定要借钱起步，先看这笔有财政贴息的，而不是消费贷、网贷或者民间借贷。纳入奖补范围的个人创业担保贷款额度不超过 30 万元、期限不超过 3 年，财政按贷款实际利率的 50% 贴息；10 万元以下的个人贷款原则上取消反担保。能申请的是重点就业群体：城镇登记失业人员、就业困难人员（含残疾人）、退役军人、刑满释放人员、高校毕业生、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、脱贫人口、农村自主创业农民。有个硬条件常被忽略：申请时本人和配偶除助学贷款、脱贫人口小额信贷、房贷、车贷和 5 万元以下小额消费贷（含信用卡消费）外，不能有其他贷款——5 万元以下的小额消费贷不算在内，别的贷款没还清就申请不了。办理顺序是先到当地人社部门做资格审核，再找担保基金运营机构或政府性融资担保机构担保，最后向经办银行提交贷款申请。还款积极、带动就业的，到期后还能再申请，累计不超过 3 次。","gain":"《普惠金融发展专项资金管理办法》（财金〔2023〕75 号）第六条个人申请条件：属于城镇登记失业人员、就业困难人员（含残疾人）、退役军人、刑满释放人员、高校毕业生（含大学生村官和留学回国学生）、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、脱贫人口、农村自主创业农民等重点就业群体，且「除助学贷款、脱贫人口小额信贷、住房贷款、购车贷款、5 万元以下小额消费贷款（含信用卡消费）以外，申请人提交创业担保贷款申请时，本人及其配偶无其他贷款」；第九条「对符合条件的创业担保贷款，财政部门给予贷款实际利率 50% 的财政贴息。对展期、逾期的创业担保贷款，财政部门原则上不予贴息」；第十条个人申请的 10 万元以下创业担保贷款原则上取消反担保；第十一条纳入奖补支持范围的个人创业担保贷款「额度不超过 30 万元，贷款期限不超过 3 年」，合伙创业可适当提高、最高不超过个人额度上限之和的 110%，奖补支持的贷款利率上限东部地区为 LPR+50BPs、中西部地区 LPR+150BPs、脱贫地区 LPR+250BPs，「还款积极、带动就业能力强、创业项目好」的到期后可继续申请，累计次数不超过 3 次；第八条申请人先向当地人力资源社会保障部门申请资格审核，再向担保机构和经办银行提交申请；第十二条经省级人民政府同意，各地可扩大支持范围、提高额度和贴息比例（全国）","grade":"A","src":"财政部 (2023). 关于印发《普惠金融发展专项资金管理办法》的通知（财金〔2023〕75 号，第六、八、九、十、十一、十二条）. <https://www.gov.cn/zhengce/zhengceku/202309/content_6903691.htm>","note":"贴息不改变「借的钱要还」这件事。本书在第 12 节第 1 条的立场没变：创业只拿亏得起的钱，不动家底、不给公司贷款签个人担保，配偶更不要跟着签——这条只是说，如果你已经决定要借，政策贷款是成本最低的那一档，别去碰消费贷和民间借贷。额度和范围各省可以往上调，实际能批多少以当地人社部门当年的口径为准；2020 年疫情期那份「个人最高 20 万」的通知是临时文件，现行看这份办法。开店本身的主体选择、许可证、报税和退场见第 12 节，失业期间的培训补贴、社保补贴和就业见习见第 7 节第 14 条。","money":"0","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]},{"n":32,"title":"出国留学：身份、打工、保险和回国认证","intro":"口径是金钱与人身自由。这一节不讨论该不该出国，也不比较学校好坏，只写四件「不知道就要吃亏」的事：签证身份怎么才算没断、打工时数的红线在哪、保险和费用是强制的哪几笔、回国之后这张文凭能不能被认。\n覆盖美国、加拿大、英国、澳大利亚四国，数字逐国列出，来源是各国移民局和中国教育部的官方页面。**各国留学政策改得比中国法规勤，本节所有数字的截至日期是 2026 年 9 月，出发前和每次续签前都要照来源栏的链接自查一遍。**\n人在境外出了事怎么找使领馆、12308 能管什么、境外医疗和转运保险怎么买，见第 21 节；读书还是打工那道账见第 23 节；账号被盗和电信诈骗见第 14、8 节，都不重复。","entries":[{"id":"32.1","sec":32,"n":1,"title":"交学费之前先查学校在不在留服中心的认证院校名单里","cost":"0 元；在留服中心「认证院校查询」里输一次学校名，几分钟","human":"回国要用这张文凭考公、进国企、落户、评职称，就得先过教育部留学服务中心的学历学位认证。学校不在可认证范围里，花出去的学费和时间换回来的东西，在国内用不上。查是免费的，查完再交钱。","gain":"中国（教育部）留学服务中心设有认证院校查询入口，可按国家和学校名检索该校所发学历学位是否在认证范围内；教育部教育涉外监管信息网同时公布中外合作办学和境外办学的监管信息","grade":"A","src":"中国（教育部）留学服务中心. 认证院校查询. <http://yxcx.cscse.edu.cn/>；教育部教育涉外监管信息网. <https://jsj.moe.gov.cn/>","note":"中介说「教育部认可」不算数，以查询结果为准。名单会变，入学时在名单里不等于毕业时还在，中途每年复查一次。中外合作办学项目另有认证注册制度，2008 年以后入学的可凭姓名和身份证号在涉外监管信息网查注册序号。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"32.2","sec":32,"n":2,"title":"美国 2026 年 9 月 15 日起改了规矩：F-1 不再是「读完为止」，最长四年，读完 30 天内走","cost":"0 元；把 I-20 上的项目结束日期和 I-94 上的入境期限抄进日历，各提前 90 天提醒一次","human":"以前 F-1 按「读多久算多久」入境，现在改成给一个写死的期限、最长四年，到期要另外申请延期。读完或者提前结束学业的，只有 30 天可以留着准备走人或者转成别的合法身份，不是流传的 60 天。日期一过，人就是非法滞留。","gain":"8 CFR 214.2(f) 规定，完成学业和已获批实习的 F-1 学生，自项目结束日期、四年最长入境期限或 OPT/STEM OPT 工作许可结束日期起，另有 30 天用于准备离境或依法转换身份；提前结束学业或培训的，自结束之日起 30 天内必须离境或另求合法身份。该固定期限规则由国土安全部 2026 年 7 月 17 日公布，2026 年 9 月 15 日生效","grade":"A","src":"8 CFR 214.2(f)（现行版本）. <https://www.ecfr.gov/current/title-8/chapter-I/subchapter-B/part-214/section-214.2>；DHS (2026). Establishing a Fixed Time Period of Admission and an Extension of Stay Procedure for Nonimmigrant Academic Students, Exchange Visitors（2026-07-17 公布，2026-09-15 生效）. <https://www.federalregister.gov/documents/2026/07/17/2026-14439/establishing-a-fixed-time-period-of-admission-and-an-extension-of-stay-procedure-for-nonimmigrant>","note":"这条 2026 年 9 月 15 日刚生效，网上和中介手里大量「60 天宽限期」「duration of status 读到毕业」的说法都是旧的。延期要在期限届满前按 (f)(7) 另行申请，不是自动续。J 签证同一份规则一起改，细节不同，按自己签证类别查原文。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"32.3","sec":32,"n":3,"title":"打工时数是四国都写死的红线，超一小时就是违反签证条件","cost":"0 元；按周记工时，别信雇主「多干几个小时没人查」","human":"四个国家都给学生签证的打工时间设了上限，超了就是违反签证条件，可能被取消签证、遣返，以后再申请也会被追问。上限是按周或按两周算的，打两份工要合起来算。","gain":"美国 F-1 校内打工在学期中每周不得超过 20 小时，经批准的校外兼职同样限每周 20 小时，假期可全职（8 CFR 214.2(f)(9)）；英国学生签证读学位及以上课程学期内每周 20 小时、学位以下 10 小时、非全日制课程一律不得打工，且不得自雇、不得从事职业运动员或演艺工作（移民规则附录 Student ST26.1、ST26.5）；加拿大符合条件的全日制学生校外打工每周最多 24 小时（IRPR 第 186(v) 条）；澳大利亚学生签证课程进行期间每两周最多 48 小时，研究型硕士和博士及其家属不受此限","grade":"A","src":"8 CFR 214.2(f)(9). <https://www.ecfr.gov/current/title-8/chapter-I/subchapter-B/part-214/section-214.2>；UK Home Office. Immigration Rules Appendix Student（ST26.1、ST26.5）. <https://www.gov.uk/guidance/immigration-rules/immigration-rules-appendix-student>；IRCC. Work off campus as an international student. <https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/work/work-off-campus.html>；Australian Government Department of Home Affairs. Student visa (subclass 500). <https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500>","note":"美国的校外打工必须先获批，I-765 还在审就不能开工。加拿大旧许可上印的是每周 20 小时的，只要仍符合条件，实际可做到 24 小时，以现行规定为准。英国那条禁自雇的范围很宽，接私活、开网店、做自由职业都算。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"32.4","sec":32,"n":4,"title":"身份的根是「全日制在读」：休学、退学、转学空档期一律不能打工","cost":"0 元；停课、休学、换学校之前先找学校的国际学生办公室确认身份状态","human":"打工资格是挂在「你正在全日制上学」这件事上的。一旦休学、退学、被开除，或者转学期间没在上课，打工资格当场消失，接着干就是非法打工。很多人以为签证没到期就没事，其实身份早断了。","gain":"加拿大明文规定，在获批休学期间，或转学期间没有在学习的，不得校外打工，只有恢复学业后才能重新开始工作；美国的校内打工资格以 SEVIS 中身份为 Active 的 F-1 学生为限，且须维持全日制课业；英国的打工许可按课程类型授予，非全日制课程不得打工","grade":"A","src":"IRCC. Work off campus as an international student. <https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/work/work-off-campus.html>；U.S. Department of Homeland Security, Study in the States. Working in the United States. <https://studyinthestates.dhs.gov/students/work/working-in-the-united-states>；UK Home Office. Immigration Rules Appendix Student（ST26.1）. <https://www.gov.uk/guidance/immigration-rules/immigration-rules-appendix-student>","note":"课业压力大想减课之前，先问清楚减到多少就不算全日制了，这条比打工更早出事。被学校开除或者项目终止的，身份通常当天就断，别等学校发正式信再行动。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"32.5","sec":32,"n":5,"title":"美国：搬家后 10 天内必须报新地址","cost":"0 元；在线提交一次改址，十分钟","human":"在美国换了住址，法律要求 10 天之内通知移民局。不报不是小事，它既是违法，也会让移民局寄给你的信寄丢。","gain":"8 CFR 265.1 规定，依法负有登记义务的外国人，应当在地址变更后 10 日内按 USCIS 的要求报告地址变更和新地址","grade":"A","src":"8 CFR 265.1. <https://www.ecfr.gov/current/title-8/chapter-I/subchapter-B/part-265/section-265.1>；USCIS. AR-11, Alien's Change of Address Card. <https://www.uscis.gov/ar-11>","note":"报给移民局和报给学校是两回事，学校的 SEVIS 记录要另外更新。其余三国也都要求地址变更后通知移民局或学校，期限和方式各国不同，按本国移民局页面办。","money":"0","time":"少","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"32.6","sec":32,"n":6,"title":"出发前和在读期间，看一眼教育部的留学预警","cost":"0 元；出发前看一次，之后每学期看一次","human":"教育部会对某个国家或地区专门发预警，说明那里近期治安、政策对中国留学生不利。这是官方公开发布的、白纸黑字能查到的风险提示，比中介的说法可靠，看一眼不花钱。","gain":"教育部通过教育涉外监管信息网发布留学预警。2025 年共发布 4 号：第 1 号提示美国有关州通过的高等教育法案含涉华消极条款（2025-04-09），第 2、3 号两次提示菲律宾针对中国公民的案件多发、留学环境不佳（2025-07-18、2025-08-30），第 4 号提示日本治安形势和留学环境不佳、建议谨慎规划赴日留学（2025-11-16）","grade":"A","src":"教育部教育涉外监管信息网. 预警信息. <https://jsj.moe.gov.cn/>；教育部发布 2025 年第 4 号留学预警. <https://jsj.moe.gov.cn/n2/2/2/2060.shtml>；第 1 号. <https://jsj.moe.gov.cn/n2/2/2/2001.shtml>","note":"预警不是禁令，也不代表不能去，它给的是「做风险评估」这个动作的官方依据。预警名单随形势变，本节不长期维护，以网站当期页面为准。境外人身安全和领事保护见第 21 节。","money":"0","time":"少","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"32.7","sec":32,"n":7,"title":"澳大利亚：OSHC 必须覆盖全程且中间不能断，落地拿不出保险可能被拒绝入境","cost":"按签证时长一次性买，读几年买几年；数千到上万元人民币","human":"澳大利亚把留学生医疗保险写成签证条件，不是可选项。保险要盖住整个停留期，续签换保单之间不能有空档，入境时拿不出保险证明可能当场被拒绝入境。到了以后家里人来陪读，每个人都要单独有。","gain":"澳大利亚内政部规定，学生签证申请人及其家属须持有并在澳停留全程维持澳大利亚认可保险机构提供的海外学生医疗保险（OSHC），除非符合豁免情形；与前一签证的保险之间不得有空档；入境时无法证明已投保的，可能被拒绝入境；先于课程开始入境的，保险起始日须为实际抵澳之日","grade":"A","src":"Australian Government Department of Home Affairs. Student visa (subclass 500). <https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500>","note":"学校代办的要问清保险公司名称、保单起止日期和保单号，签证申请里要填。买短了会导致续签出问题，宁可买到毕业后再多留一点。","money":"多","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"32.8","sec":32,"n":8,"title":"英国：签证费之外还有一笔按年收的医疗附加费，学生每年 776 英镑，申请时一次付清","cost":"签证费 558 英镑，医疗附加费每年 776 英镑，申请时一次交清","human":"英国的钱不止签证费，还要按签证年数一次性预交医疗附加费，交了才能用国民医疗服务。两年的签证就是一次交 1552 英镑，加上签证费，出发前这一笔要一次交清，做预算时别漏。","gain":"英国学生签证在境外申请和在境内延期或转换的费用均为 558 英镑；医疗附加费学生本人及其家属为每年 776 英镑，例如 2 年签证为 1552 英镑，其他类别申请人为每年 1035 英镑；签证超过 6 个月不足 1 年的按整年收取","grade":"A","src":"UK Government. Student visa. <https://www.gov.uk/student-visa>；UK Government. Pay for UK healthcare as part of your immigration application. <https://www.gov.uk/healthcare-immigration-application>","note":"金额和汇率都会变，按上面两个页面当期数字算。读学位课程且年满 18 岁的，通常最长可停留 5 年，学位以下 2 年，按这个年数估附加费。","money":"多","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"32.9","sec":32,"n":9,"title":"回国前留出认证时间：留服认证要 10 到 20 个工作日","cost":"线上申请缴费；材料准备加审核，按工作日算要一个月上下","human":"国外学历回国要用，得先做学历学位认证。认证本身的审核期是 10 到 20 个工作日，赶上求职季或者材料被退回还要更久。秋招、考公报名、落户都有截止日期，别等要用了才开始办。","gain":"中国（教育部）留学服务中心网上服务大厅办理国（境）外学历学位认证，流程为注册实名认证、在线提交申请与材料、在线缴费、评估与审核，公布的认证工作时限为 10 至 20 个工作日","grade":"A","src":"中国（教育部）留学服务中心. 网上服务大厅·学历学位认证. <http://zwfw.cscse.edu.cn/>","note":"材料含文凭证书、护照或通行证、居留卡或签证签注、证件照片和授权声明，出国期间的出入境记录系统自取，所以在外期间的签证页别丢。认证书失效处置、暂停受理某校认证申请这类公告也在留服中心网站发布，办之前先看一眼有没有涉及自己的学校。","money":"少","time":"中","will":"否","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"32.10","sec":32,"n":10,"title":"认证被「加强审查」的学校每年都在加，花钱买文凭这条路已经走不通","cost":"0 元；报名前在留服中心通知公告里搜一次学校名","human":"留服中心会点名一批国外院校，对它们的学历认证单独加强审查，也会暂停受理个别学校的认证申请。这些学校往往就是宣传里「免语言、免出境、几个月拿硕士」的那种。报名前搜一次学校名，比事后申诉省事得多。","gain":"中国（教育部）留学服务中心持续发布对部分国外院校学历学位认证加强认证审查的公告，最新一份为第九号（2025-10-28）；另发布过暂停受理个别境外院校认证申请的公告，以及关于借国（境）外学历学位认证实施诈骗的提示","grade":"A","src":"中国（教育部）留学服务中心. 关于对部分国外院校学历学位认证加强认证审查的公告（九）（2025-10-28）. <https://www.cscse.edu.cn/cscse/sy/tzgg/2025102809225023345/index.html>；中国（教育部）留学服务中心. <https://www.cscse.edu.cn/>","note":"「加强审查」不等于一定认证不了，但会要求补交更多材料、时间更长。凡是承诺「包认证」「内部渠道加急」的中介都是骗局，留服中心专门发过防诈骗提示。跨境找人代写论文、代上网课被查到，学历作废之外还可能影响签证记录。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"}]}]
